8350928796547166764	code	#template('colorThemeInit.vm')\n\n.xwikiIconPickerContainer {\n  width: 520px;\n  height: 300px;\n  border: 1px solid black;\n  position: fixed;\n  z-index: 1000;\n  background-color: $theme.pageContentBackgroundColor;\n}\n\n.xwikiIconPickerList {\n  overflow-y: scroll;\n  height: 240px;\n}\n\n.xwikiIconPickerIcon {\n  float: left;\n  height: 80px;\n  width: 100px;\n  text-align: center;\n  border-radius: 4px;\n  vertical-align: middle;\n  overflow: hidden;\n  padding: 10px;\n  cursor: pointer;\n}\n\n.xwikiIconPickerIcon:hover {\n  background-color: $theme.highlightColor;\n}\n\n.xwikiIconPickerIconImage {\n  font-size: 24px;\n  margin: 0;\n}\n\n.xwikiIconPickerIconImage img{\n  width: 24px;\n}\n\n.xwikiIconPickerIconThemeSelector {\n  width: 100%;\n  background-color: $theme.menuBackgroundColor;\n  color: $theme.menuLinkColor;\n  padding: 10px;\n  text-align: center;\n  clear: left;\n  height: 60px;\n}\n
1265889115715036925	code	{{velocity output="false"}}\n  $xwiki.ssx.use('IconThemesCode.IconPicker')\n  ## The icons themes may need some SSX, so we ask for a rendering of an icon of each icon theme, to be able to display\n  ## all icon themes in the picker\n  ## ToDo: since it is a bit hacky, a better system would be to dynamically load the needed SSX on demand\n  #foreach($iconSetName in $services.icon.iconSetNames)\n    $services.icon.render('wiki', $iconSetName)\n  #end\n{{/velocity}}\n{{velocity}}\n{{html clean="false"}}\n<script language="javascript">\n  require.config({\n    paths: {\n      'xwiki-icon-picker': '$xwiki.getURL($services.model.createDocumentReference('', 'IconThemesCode', 'IconPicker'), 'jsx', "minify=$!{escapetool.url($request.minify)}")'\n    }\n  });\n  require(['jquery', 'xwiki-icon-picker'], function($) {\n    var options = {};\n    #if("$!xcontext.macro.params.prefix" != '')\n      options['prefix'] = '$escapetool.javascript($xcontext.macro.params.prefix)';\n    #end\n    #if("$!xcontext.macro.params.id" != '')\n      $('#${xcontext.macro.params.id}').xwikiIconPicker(options);\n    #end\n    #if("$!xcontext.macro.params.get('class')" != '')\n      $('.${xcontext.macro.params.get('class')}').xwikiIconPicker(options);\n    #end\n  });\n</script>\n{{/html}}\n{{/velocity}}\n\n
