8009908531353325490	code	{{velocity}}\n##\n## List spaces within the wiki.\n##\n$xwiki.ssx.use('Main.Spaces')##\n#set($spaceList = $xwiki.getSpaces())\n{{html}}\n<ul class="xlist">\n  ##\n  ## List spaces.\n  ##\n  #foreach($space in $spaceList)\n    ## Display space only if the user has view right on space home and if the space is not blacklisted.\n    ## $blacklistedSpaces is set in xwikivars.vm\n    #set ($spaceHomeDocumentReference = $services.model.createDocumentReference($xcontext.database, $space, 'WebHome'))\n    #if($xwiki.hasAccessLevel('view', $services.model.serialize($spaceHomeDocumentReference)) && !$blacklistedSpaces.contains($space))\n      <li class="xitem xunderline xhighlight space">\n        <div class="xitemcontainer">\n          <div class="spSpaceName"><a href="$xwiki.getURL($spaceHomeDocumentReference)">${escapetool.xml($space)}</a></div>\n          <div class="xshowonhover spSpaceActions">\n            ## Link to the space index.\n            <a href="$xwiki.getURL('Main.SpaceIndex', 'view', "space=$escapetool.url($space)")" title="$services.localization.render('index.spacesMacro.spaceIndex.title')">\n              <img src="$xwiki.getSkinFile('icons/silk/book_open.png')" alt="$services.localization.render('index.spacesMacro.spaceIndex.alt')"/>\n            </a>\n            ## If the user has admin right on the space display links to administration and delete.\n            #set ($spacePreferencesDocumentReference = $services.model.createDocumentReference($xcontext.database, $space, 'WebPreferences'))\n            #if($xwiki.hasAccessLevel('admin', $services.model.serialize($spacePreferencesDocumentReference)))\n              <a href="$xwiki.getURL($spacePreferencesDocumentReference, 'admin', '')" title="$services.localization.render('index.spacesMacro.spaceAdministration.title')">\n                <img src="$xwiki.getSkinFile('icons/silk/wrench.png')" alt="$services.localization.render('index.spacesMacro.spaceAdministration.alt')"/>\n              </a>\n            #end\n          </div>\n          <div class="xspacer">&nbsp;</div>\n        </div>\n      </li>\n    #end\n  #end\n  ##\n  ## Space creation.\n  ##\n  ## Only if the current user has the right to create spaces and the current action is not inline.\n  ## If it's inline, then there is already a form, and if we render the second, nested one, the DOM is messed up in IE.\n  #if($hasCreateSpace && "$!xcontext.action" != "inline" && "$!xcontext.action" != "edit")\n    <li id="spSpaceCreateItem" class="xitem space">\n      <div class="xitemcontainer">\n        <div id="spSpaceCreateLabel" class="spSpaceName"><a href="$xwiki.getURL('XWiki.CreatePage', 'view', 'tocreate=space')" onclick="toggleClass($('spSpaceCreateForm'), 'hidden'); return false;">$services.localization.render('index.spacesMacro.createSpace.link')</a></div>\n        <div class="spacer">&nbsp;</div>\n        <div id="spSpaceCreateForm" class="hidden">\n          <form method="post" action="$doc.getURL('create')" class="xformInline">\n            <div>\n              <input name="tocreate" type="hidden" value="space" />\n              #set($newSpaceName = $escapetool.xml($services.localization.render('index.spacesMacro.createSpace.defaultSpaceName')))\n              <label class="hidden" for="spSpaceCreateTextInput">$newSpaceName</label>\n              <input id="spSpaceCreateTextInput" type="text" name="space" value="$newSpaceName" class="panelinput withTip" />\n              <span class="buttonwrapper">\n                <input type="submit" value="$services.localization.render('index.spacesMacro.createSpace.submit')" class="button" />\n              </span>\n            </div>\n          </form>\n        </div>\n        <div class="spacer">&nbsp;</div>\n      </div>\n    </li>\n  #end\n</ul>\n{{/html}}\n{{/velocity}}\n
