2707485211712707399	code	#template('colorThemeInit.vm')\n\n/* General Styles */\n\n.menu-horizontal ul {\n  list-style-type: none;\n  margin: auto;\n}\n\n.menu-horizontal ul * {\n  line-height: normal;\n}\n\n.menu-horizontal li {\n  cursor: default;\n  line-height: 16px;\n  min-height: 16px;\n}\n\n.menu-horizontal img {\n  vertical-align: middle;\n}\n\n/* Horizontal separator */\n.menu-horizontal li li:empty {\n  border-top: 1px solid $theme.borderColor;\n  line-height: 1px;\n  min-height: auto;\n  padding: 0;\n}\n\n/* Horizontal Menu */\n\n.menu.menu-horizontal {\n  background-color: $theme.menuBackgroundColor;\n  #css3_backgroundLinearGradient({\n    'to': 'bottom',\n    'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n  color: $theme.menuLinkColor;\n  font-size: .85em;\n  height: 2em;\n  padding-left: 25px;\n}\n\n.menu-horizontal li {\n  padding: 0.2em 1.3em;\n}\n\n.menu-horizontal li li:empty {\n  border-top: 1px solid $theme.textSecondaryColor;\n  margin: .5em 1em;\n}\n\n/* Vertical separator */\n.menu-horizontal > ul > li:empty {\n  border-left: 1px solid $theme.textSecondaryColor;\n  margin: 0 .5em;\n  padding: 0;\n  vertical-align: middle;\n}\n\n.menu-horizontal li a, .menu-horizontal li a:visited {\n  color: inherit;\n}\n\n.menu-horizontal > ul > li {\n  display: inline-block;\n}\n\n.menu-horizontal > ul > li > .xDropdown:after {\n  content: '\\25BC';\n  font-size: .8em;\n  margin-left: .5em;\n}\n\n.menu-horizontal > ul ul {\n  background: none repeat scroll 0 0 $theme.menuBackgroundColor;\n  border-radius: 0 0 .8em .8em;\n  box-shadow: 0 1px 1px $theme.borderColor;\n  display: none;\n  margin: 0.2em 0 0 -1.3em;\n  padding-bottom: .3em;\n  position: absolute;\n  z-index: 1000;\n}\n\n.menu-horizontal li:hover > ul {\n  display: block;\n}\n\n/* The only way to have a menu with more than 2 levels without JavaScript is to use a fixed width. */\n.menu-horizonta