nInfoColor;\n  font-size: 87%;\n  padding: 0;\n  margin: 0;\n  font-style: normal;\n}\n.chapter {\n  margin: 3.5em 0 1em;\n  padding: 0 10px 5px;\n  position: relative;\n}\nh2 a.action-edit {\n  display: inline-block;\n  font-size: .8em;\n  color: $theme.textColor;\n  visibility: hidden;\n  opacity: .8;\n  margin: 0 0 0 1em;\n}\n.chapter:hover a.action-edit {\n  visibility: visible;\n}\nh1, h2, h3, h4 {\n  text-shadow: 1px 1px 0 $theme.pageContentBackgroundColor;\n}\n.chapter > h2 {\n  border-bottom: 1px solid $theme.titleColor;\n  cursor: default;\n  font-family: Georgia,serif;\n  font-size: 1.5em;\n  margin: -1.5em -10px 0;\n  padding-left: 10px;\n}\n.editbody .chapter > h2 {\n  cursor: pointer;\n}\n.chapter > h2+.hint {\n  margin: 1em 0;\n}\n.chapter h3 {\n  font-size: 1.2em;\n  text-transform: uppercase;\n  margin: 1em 0;\n  padding: 0 20px 0 0;\n}\n/** ----------------------------------------------------------- */\n/** Patient info zone **/\n.clinical-info .fieldset {\n  margin: 1em 0 !important;\n}\n.editbody .family_study {\n  margin-top: 1.2em ! important;\n}\n.clinical-info .side {\n  padding-top: .3em;\n}\n.viewbody .clinical-info .label, .viewbody .clinical-info label {\n  font-weight: bold;\n  display: inline-block;\n  width: 33%;\n}\n.viewbody .family_study .label {\n  display: inline;\n}\n.viewbody .family_study .half-width {\n  width: 33%;\n}\n.viewbody .family_study .half-width * {\n  margin: 0 !important;\n}\n.omim_id.half-width p {\n  margin: 0;\n}\n/** ----------------------------------------------------------- */\n/** PubMed search box & suggest */\n.pubmed-search-box {\n  width: 42.5% !important;\n  position: absolute;\n  top: auto;\n  bottom: -1.4em !important;\n  margin-right: -46% !important;\n}\n.pubmed-search-box fieldset {\n  border: 1px solid $theme.backgroundSecondaryColor;\n  padding: .5em .8em;\n}\n#pubmed-search-history ul {\n  max-height: 5em;\n  overflow: auto;\n  font-size: .8em;\n}\n#pubmed-search-history h4 {\n  margin-bottom: 0;