clude reference="Groups.WebHome" /}}
7180121727829606960	code	document.observe('xwiki:dom:loaded', function() {\n  var groupsTable = $('groups-directory');\n  if (!groupsTable) {\n    return false;\n  }\n  groupsTable.select('tr .tools a.tool.delete').invoke('observe', 'click', function(clickEvent) {\n    clickEvent.stop();\n    var item = clickEvent.findElement('a');\n    item.blur();\n    if (item.disabled) {\n      // Do nothing if the button was already clicked and it's waiting for a response from the server.\n      return;\n    } else {\n      var url = item.href + "?confirm=1&form_token=" + $$('meta[name=form_token]')[0].content + (Prototype.Browser.Opera ? "" : "&ajax=1");\n      new XWiki.widgets.ConfirmedAjaxRequest(\n        /* Ajax request URL */\n        url,\n        /* Ajax request parameters */\n        {\n          onCreate : function() {\n            // Disable the button, to avoid a cascade of clicks from impatient users\n            item.disabled = true;\n          },\n          onSuccess : function() {\n            // Go to space WebHome\n            // window.location = new XWiki.Document('WebHome', XWiki.Document.currentSpace).getURL('view');\n            item.up('tr').remove();\n          },\n          onFailure : function() {\n            // Better luck next time!\n            item.disabled = false;\n          }\n        },\n        /* Interaction parameters */\n        {\n          confirmationText: " $services.localization.render('phenotips.groups.deleteConfirmation')"\n        }\n      );\n    }\n  });\n\n  var creationForm = $('group-creation-form');\n  if (creationForm) {\n    creationForm.observe('submit', function(event) {\n      var iName = creationForm.down('input[name="name"]');\n      if (iName.value.strip() == '') {\n        event.stop();\n        iName.focus();\n      }\n    });\n  }\n});
