5798038344610232394	code	{{velocity output="false"}}\n#set ($groupClassName = 'PhenoTips.PhenoTipsGroupClass')\n#set ($groupTemplateName = 'PhenoTips.PhenoTipsGroupTemplate')\n#set ($groupsHome = 'Groups.WebHome')\n#set ($orders = {\n  'name' : 'asc',\n  'members' : 'desc',\n  'cases' : 'desc'\n})\n#set ($defaultOrder = 'name')\n#set ($order = "$!xcontext.macro.params.orderby")\n#if (!$orders.get($order))\n  #set($order = $defaultOrder)\n#end\n\n#set ($query = $services.query.xwql("from doc.object(${groupClassName}) as grp where doc.fullName <> :template").bindValue('template', $groupTemplateName))\n#set ($groupDocs = $xwiki.wrapDocs($query.execute()))\n\n#set ($groupData = [])\n#set ($defaultLogo = "$!{xwiki.getDocument($groupTemplateName).getObject($groupClassName).getProperty('image').value}")\n#if ($defaultLogo  != '' && $defaultLogo.indexOf('@') < 0)\n  #set ($defaultLogo = "$groupTemplateName@$!{defaultLogo}")\n#end\n\n#foreach ($groupDoc in $groupDocs)\n  #set ($groupObj = $groupDoc.getObject($groupClassName))\n  #set ($filterby = "$!{xcontext.macro.params.filterby}")\n  #set ($filterbyprop = $groupObj.getProperty($filterby))\n  #set ($filterval = "$!{xcontext.macro.params.filterval}")\n  #set ($isFilterActive = ($filterby != '' && ("$!filterbyprop" != '' || $filterby == 'member')))\n  #if ($filterby == '' || "$!filterbyprop" != '' && ($filterbyprop.value == $filterval || $filterbyprop.value.contains($filterval)) || $filterby == 'member' && $groupDoc.getObjects('XWiki.XWikiGroups', 'member', $filterval))\n    #set ($memberObjs = $groupDoc.getObjects('XWiki.XWikiGroups'))\n    #set ($phantomMemberObjs = $groupDoc.getObjects('XWiki.XWikiGroups', 'member', ''))\n    #set ($logo = "$!groupObj.getProperty('image').value")\n    #if ("$!logo" != '')\n      #set ($logo = "${groupDoc.fullName}@${logo}")\n    #else\n      #set ($logo = $defaultLogo)\n    #end\n    #set ($discard = $groupData.add({\n      'doc' : $groupDoc,\n      'obj' : $groupObj,\n      'doc.fullName' : $groupDoc.fullName,\n      'name' : $groupDoc.title,\n      'logo' : $logo,\n      'members' : $mathtool.sub($memberObjs.size(), $phantomMemberObjs.size()),\n      'cases' : $services.query.xwql('from doc.object(PhenoTips.PatientClass) as p, doc.object(PhenoTips.OwnerClass) as o where o.owner = :grp').bindValue('grp', $groupDoc.documentReference.toString()).count()\n    }))\n  #end\n#end\n#set ($groupSortedData = $sorttool.sort($groupData, ["${order}:${orders.get($order)}"]))\n\n#set ($max = $mathtool.toInteger($xcontext.macro.params.max))\n#if (!($max && $max > 0 && $max < $groupSortedData.size()))\n  #set ($max = $groupSortedData.size())\n#end\n\n$xwiki.ssx.use($groupClassName, {'colorTheme' : "$xwiki.getSpacePreference('colorTheme')"})\n$xwiki.jsx.use($groupClassName)\n{{/velocity}}\n\n{{velocity}}\n(% id="groups-directory" %)\n#if ($groupSortedData.size() == 0)\n#if ($isFilterActive)\n\n{{info}}$services.localization.render('phenotips.homepage.groups.noMatches'){{/info}}\n\n#else\n\n{{info}}$services.localization.render('phenotips.homepage.groups.noGroupsMessage')#if($hasAdmin && $doc.documentReference.name != 'XWikiPreferences') [[$services.localization.render('phenotips.homepage.groups.manageGroups')>>path:${xwiki.getDocument('XWiki.XWikiPreferences').getURL('admin', 'editor=globaladmin&section=workgroups')}]]#end{{/info}}\n\n#end\n#else\n#foreach ($groupDatum in $groupSortedData)#if ($foreach.index < $max)\n|(% class="logo" %) #if ("$!{groupDatum.get('logo')}" != '')[[[[image:${services.rendering.escape($groupDatum.get('logo'), $doc.syntax)}||width="80px"]]>>${services.rendering.escape($groupDatum.get('doc.fullName'), $doc.syntax)}]]#end##\n|(% class="name" %) [[${services.rendering.escape($groupDatum.get('name'), $doc.syntax)}>>${services.rendering.escape($groupDatum.get('doc.fullName'), $doc.syntax)}]] \\\\(% class="members"%)$services.localization.render('phenotips.group.info.members', [$groupDatum.get('members')])(%%) \\\\(% class="patients"%)$services.localization.render('phenotips.group.info.cases', [$groupDatum.get('cases')])(%%)##\n#if ($xcontext.macro.params.fullinfo == 'true')|#if ("$!{groupDatum.get('obj').getProperty('description').value.trim()}" != '')(% class="desc" %) ((($groupDatum.get('doc').display('description'))))#end#end\n#if ($xcontext.macro.params.tools == 'true' && $hasAdmin)|(% class="tools" %) (((##\n  [[{{icon name="pencil" title="$services.localization.render('phenotips.groups.edit')"/}}>>path:$xwiki.getURL($groupDatum.get('doc.fullName'), 'edit')||class="tool edit"]]##\n  [[{{icon name="times" title="$services.localization.render('phenotips.groups.delete')"/}}>>path:$xwiki.getURL($groupDatum.get('doc.fullName'), 'delete')||class="tool delete"]]##\n)))#end\\\\\n#end#end\n#end\n{{/velocity}}
