able" class="xwiki-livetable"&gt;\n    &lt;tr&gt;\n      &lt;td class="xwiki-livetable-pagination" colspan="2"&gt;\n        &lt;span id="groupstable-limits" class="xwiki-livetable-limits"&gt;&lt;/span&gt;\n        &lt;span id="groupstable-ajax-loader" class="xwiki-livetable-loader"&gt;&lt;img src="$xwiki.getSkinFile('icons/xwiki/ajax-loader-large.gif')" alt="$services.localization.render('platform.livetable.loading')" title="" /&gt;$services.localization.render('platform.livetable.loading')&lt;/span&gt;\n        &lt;span class="pagination"&gt;\n          &lt;span id="groupstable-pagination-text" class="xwiki-livetable-pagination-text"&gt;$services.localization.render('platform.livetable.paginationPage')&lt;/span&gt;\n          &lt;span id="groupstable-pagination" class="xwiki-livetable-pagination-content" &gt;&lt;/span&gt;\n        &lt;/span&gt;\n      &lt;/td&gt;\n    &lt;/tr&gt;\n    &lt;tr&gt;\n      &lt;td class="xwiki-livetable-display-container"&gt;\n        &lt;table class="xwiki-livetable-display"&gt;\n          &lt;thead class="xwiki-livetable-display-header"&gt;\n            &lt;tr&gt;\n              &lt;th class="xwiki-livetable-display-header-text" scope="col"&gt;$services.localization.render('xe.admin.groups.groupname')&lt;/th&gt;\n              &lt;th class="xwiki-livetable-display-header-text" scope="col"&gt;$services.localization.render('xe.admin.groups.members')&lt;/th&gt;\n              &lt;th class="xwiki-livetable-display-header-text" scope="col"&gt;$services.localization.render('xe.admin.groups.manage')&lt;/th&gt;\n            &lt;/tr&gt;\n            &lt;tr id="groupstable-filters" class="xwiki-livetable-display-filters"&gt;\n              &lt;td class="xwiki-livetable-display-header-filter"&gt;&lt;label for="name" class="hidden"&gt;$services.localization.render('xe.admin.groups.filter.groupName')&lt;/label&gt;&lt;input id="name" name="name" type="text" class="filter"/&gt;&lt;/td&gt;\n              &lt;td class="xwiki-livetable-display-header-filter"&gt;&lt;/td&gt;\n              &lt;td class="xwiki-livetable-display-header-filter"&gt;\n              #if (!$mainwk)\n                &lt;label for="wiki" class="hidden"&gt;$services.localization.render('xe.admin.groups.filter.scope')&lt;/label&gt;\n                &lt;select name="wiki" class="filter"&gt;\n                  &lt;option value="local" selected="selected"&gt;$services.localization.render('xe.admin.groups.local')&lt;/option&gt;\n                  &lt;option value="global"&gt;$services.localization.render('xe.admin.groups.global')&lt;/option&gt;\n                  &lt;option value="both"&gt;$services.localization.render('xe.admin.groups.both')&lt;/option&gt;\n                &lt;/select&gt;\n              #else\n                &lt;input type="hidden" value="local" name="wiki" /&gt; \n              #end\n              &lt;/td&gt;\n            &lt;/tr&gt;\n          &lt;/thead&gt;\n          &lt;tbody id="groupstable-display" class="xwiki-livetable-display-body"&gt;&lt;tr&gt;&lt;td&gt;&amp;nbsp;&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;\n        &lt;/table&gt;\n      &lt;/td&gt;\n    &lt;/tr&gt;\n    &lt;tr&gt;\n      &lt;td id="tdAddNewUserOrGroup"&gt;\n        &lt;span class="buttonwrapper"&gt;&lt;a href="#" id="addNewGroup"&gt;$services.localization.render('rightsmanager.addnewgroup')&lt;/a&gt;&lt;/span&gt;\n      &lt;/td&gt;\n    &lt;/tr&gt;\n  &lt;/table&gt;\n  #set($addnewurl = $xwiki.getURL("XWiki.XWikiGroups", "view", "xpage=addnewgroup"))\n  #set($saveurl = $xwiki.getURL("XWiki.XWikiGroups", "view"))\n  #set($redirecturl = $xwiki.getDocument("XWiki.XWikiPreferences").getURL("admin", "editor=${editor}&amp;section=Groups")) \n  &lt;script type="text/javascript"&gt;\n    //&lt;![CDATA[\n    (function() {\n      var startup = function() {\n        var callback = function(row, i, table) { return displayGroups(row, i, table, "$!{services.csrf.getToken()}"); };\n        var ta = new XWiki.widgets.LiveTable("$url", "groupstable", callback);\n        Event.observe($('addNewGroup'), "click", makeAddHandler("$addnewurl", "$saveurl", "$redirecturl"));\n      }\n      if ((typeof(XWiki) != 'undefined') &amp;&amp; (typeof(XWiki.widgets) != 'undefined') &amp;&amp; (typeof(XWiki.widgets.LiveTable) != 'undefined')) {\n        startup();\n      } else {\n        document.observe('xwiki:livetable:loading', startup);\n      }\n    })();\n    //]]&gt;\n  &lt;/script&gt;\n&lt;/div&gt; ## xwikieditcontent\n{{/html}}\n{{/velocity}}</content></xwikidoc>\n
