sType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</loginButton_autoLogin_enabled>\n<loginButton_enabled>\n<defaultValue></defaultValue>\n<disabled>0</disabled>\n<displayFormType>checkbox</displayFormType>\n<displayType></displayType>\n<name>loginButton_enabled</name>\n<number>5</number>\n<prettyName>Enable login button</prettyName>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</loginButton_enabled>\n<registrationSuccessMessage>\n<disabled>0</disabled>\n<editor>PureText</editor>\n<name>registrationSuccessMessage</name>\n<number>9</number>\n<picker>0</picker>\n<prettyName>Registration Successful Message</prettyName>\n<rows>12</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</registrationSuccessMessage>\n<requireCaptcha>\n<defaultValue></defaultValue>\n<disabled>0</disabled>\n<displayFormType>checkbox</displayFormType>\n<displayType></displayType>\n<name>requireCaptcha</name>\n<number>8</number>\n<prettyName>Require captcha to register</prettyName>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</requireCaptcha>\n<welcomeMessage>\n<disabled>0</disabled>\n<editor>PureText</editor>\n<name>welcomeMessage</name>\n<number>2</number>\n<picker>0</picker>\n<prettyName>Welcome message</prettyName>\n<rows>12</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</welcomeMessage>\n</class>\n<name>XWiki.RegistrationConfig</name>\n<number>0</number>\n<className>XWiki.Registration</className>\n<guid>1a0c3cf7-de63-4f07-8a74-5c30bf880641</guid>\n<property>\n<defaultRedirect>$xwiki.getURL($services.model.resolveDocument('', 'default', $doc.documentReference.extractReference('WIKI')))</defaultRedirect>\n</property>\n<property>\n<heading>$services.localization.render('core.register.title')</heading>\n</property>\n<property>\n<liveValidation_defaultFieldOkMessage>$services.localization.render('core.validation.valid.message')</liveValidation_defaultFieldOkMessage>\n</property>\n<property>\n<liveValidation_enabled>1</liveValidation_enabled>\n</property>\n<property>\n<loginButton_autoLogin_enabled>0</loginButton_autoLogin_enabled>\n</property>\n<property>\n<loginButton_enabled>1</loginButton_enabled>\n</property>\n<property>\n<registrationSuccessMessage>#set($fullName = "$request.get('register_first_name') $request.get('register_last_name')")\n{{info}}$services.localization.render('core.register.successful', ["[[$fullName&gt;&gt;$userSpace$userName]]", $userName]){{/info}}</registrationSuccessMessage>\n</property>\n<property>\n<requireCaptcha>0</requireCaptcha>\n</property>\n<property>\n<welcomeMessage>{{translation key="core.register.welcome"/}}</welcomeMessage>\n</property>\n</object>\n<content>{{info}}This page contains a configuration object for [[XWiki.Registration&gt;&gt;XWiki.Registration]], You can configure [[XWiki.Registration&gt;&gt;XWiki.Registration]] from the [[registration section of the administration application&gt;&gt;XWiki.XWikiPreferences?section=Registration&amp;editor=globaladmin]].{{/info}}</content></xwikidoc>\n
