ionalStorage>\n<separator> </separator>\n<size>5</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.GroupsClass</classType>\n</groups>\n<levels>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>1</multiSelect>\n<name>levels</name>\n<number>2</number>\n<prettyName>Levels</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>3</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.LevelsClass</classType>\n</levels>\n<users>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>input</displayType>\n<multiSelect>1</multiSelect>\n<name>users</name>\n<number>3</number>\n<picker>1</picker>\n<prettyName>Users</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>5</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.UsersClass</classType>\n</users>\n</class>\n<name>XWiki.ResetPassword</name>\n<number>1</number>\n<className>XWiki.XWikiRights</className>\n<guid>bb00007c-00dd-4423-9b7b-b87896c947fb</guid>\n<property>\n<allow>0</allow>\n</property>\n<property>\n<groups>xwiki:XWiki.XWikiAllGroup</groups>\n</property>\n<property>\n<levels>edit</levels>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.XWikiRights</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<allow>\n<defaultValue>1</defaultValue>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>allow</displayType>\n<name>allow</name>\n<number>4</number>\n<prettyName>Allow/Deny</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</allow>\n<groups>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>input</displayType>\n<multiSelect>1</multiSelect>\n<name>groups</name>\n<number>1</number>\n<picker>1</picker>\n<prettyName>Groups</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>5</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.GroupsClass</classType>\n</groups>\n<levels>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>1</multiSelect>\n<name>levels</name>\n<number>2</number>\n<prettyName>Levels</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>3</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.LevelsClass</classType>\n</levels>\n<users>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>input</displayType>\n<multiSelect>1</multiSelect>\n<name>users</name>\n<number>3</number>\n<picker>1</picker>\n<prettyName>Users</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>5</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.UsersClass</classType>\n</users>\n</class>\n<name>XWiki.ResetPassword</name>\n<number>2</number>\n<className>XWiki.XWikiRights</className>\n<guid>06daec64-228b-4da1-b7e6-b59d9624c866</guid>\n<property>\n<allow>1</allow>\n</property>\n<property>\n<groups>XWiki.XWikiAllGroup</groups>\n</property>\n<property>\n<levels>view</levels>\n</property>\n<property>\n<users>XWiki.XWikiGuest</users>\n</property>\n</object>\n<content>{{velocity}}\n#**\nThis page starts the password reset procedure. It works according to the next algorithm:\n1. Display a form requesting the username\n2. When receiving the username via form submission, generate a random verification string which is stored (as a hash) inside a ResetPasswordRequestClass object attached to the user's profile page. If no such object exists, it is created, but an existing object will be reused, meaning that at most one password reset request can be active at a moment.\n3. Send an email to the address configured in the user's profile, containing a link to the second step of the password reset procedure.\n\nURL parameters:\n\nu = user account sent in the form\n*###\n##\n##\n## The name of the class used for storing password reset verification data.\n#set ($verifClass = 'XWiki.ResetPasswordRequestClass')\n#set ($userName = "$!request.get('u')")\n#if ($userName == '')## First step, display the form requesting the username\n  {{translation key="xe.admin.passwordReset.instructions"/}}\n\n  {{html}}\n  &lt;form method="post" action="$doc.getURL()" class="xformInline"&gt;\n  &lt;div&gt;\n  &lt;input type="hidden" name="form_token" value="$!{services.csrf.getToken()}" /&gt;\n  &lt;label for="u"&gt;$services.localization.render('xe.admin.passwordReset.username.label')&lt;/label&gt; &lt;input type="text" id="u" name="u"/&gt; &lt;span class="buttonwrapper"&gt;&lt;input type="submit" value="$services.localization.render('xe.admin.passwordReset.submit')" class="button"/&gt;&lt;/span&gt;\n  &lt;/div&gt;\n  &lt;/form&gt;\n  {{/html}}\n#else## Second step, generate the verification string, store it, and send the email\n  ## TODO: Once the usernames are not bound to the XWiki space, revisit this code\n  #if ($userName.indexOf('.') != -1)\n    #set ($userDoc = $xwiki.getDocumentAsAuthor(${userName}))\n  #else\n    #set ($userDoc = $xwiki.getDocumentAsAuthor("XWiki.${userName}"))\n  #end\n  ## Check if the user exists and has a valid email address configured in his profile\n  #set ($userObj = '')\n  #set ($userObj = $userDoc.getObject('XWiki.XWikiUsers'))\n  #if (!$userObj)\n\n    {{warning}}$services.localization.render('xe.admin.passwordReset.error.noUser', ["//${escapetool.xml($userName)}//"]){{/warning}}\n\n  #elseif ($userDoc.getObject('XWiki.LDAPProfileClass'))\n\n    {{warning}}$services.localization.render('xe.admin.passwordReset.error.ldapUser', ["//${escapetool.xml($userName)}//"]){{/warning}}\n\n  #else\n    #set ($userEmail = $userObj.getProperty('email').value)\n    #if ("$!userEmail" == '')\n\n      {{error}}{{translation key="xe.admin.passwordReset.error.noEmail"/}}{{/error}}\n\n    #else\n      ## Find the object that will hold the verification string\n      #set ($verifObj = '')\n      #set ($verifObj = $userDoc.getObject($verifClass, true))\n      ## Generate a random string\n      #set ($verifStr = $util.generateRandomString(30))\n      ## If the class is correctly configured, the string should automatically be stored as a hash\n      #set ($discard = $verifObj.set('verification', $verifStr))\n      #set ($discard = $userDoc.saveAsAuthor($services.localization.render('xe.admin.passwordReset.versionComment'), true))\n      ## Compose the verification URL\n      #set ($passwordResetURL = $xwiki.getDocument('XWiki.ResetPasswordComplete').getExternalURL('view', "u=${userName}&amp;v=${verifStr}"))\n      ## Send the email\n      #set ($from = $services.mailsender.configuration.fromAddress)\n      #if ("$!from" == '')\n        #set ($from = "no-reply@${request.serverName}")\n      #end\n      #set ($mailTemplateReference = $services.model.createDocumentReference('', 'XWiki', 'ResetPasswordMailContent'))\n      #set ($mailParameters = {'from' : $from, 'to' : $userEmail, 'language' : $xcontext.language})\n      #set ($message = $services.mailsender.createMessage('template', $mailTemplateReference, $mailParameters))\n      #set ($discard = $message.setType('Reset Password'))\n      #macro (displayError $text)\n\n        {{html}}\n          &lt;div class="xwikirenderingerror" title="Click to get more details about the error" style="cursor: pointer;"&gt;\n            $services.localization.render('xe.admin.passwordReset.error.emailFailed')\n          &lt;/div&gt;\n          &lt;div class="xwikirenderingerrordescription hidden"&gt;\n            &lt;pre&gt;${text}&lt;/pre&gt;\n          &lt;/div&gt;\n        {{/html}}\n\n      #end\n      ## Check for an error constructing the message!\n      #if ($services.mailsender.lastError)\n        #displayError($exceptiontool.getStackTrace($services.mailsender.lastError))\n      #else \n        ## Send the message and wait for it to be sent or for any error to be raised.\n        #set ($mailResult = $services.mailsender.send([$message], 'database'))\n        ## Check for errors during the send\n        #if ($services.mailsender.lastError)\n          #displayError($exceptiontool.getStackTrace($services.mailsender.lastError))\n        #else\n          #set ($failedMailStatuses = $mailResult.statusResult.getByState('FAILED'))\n          #if ($failedMailStatuses.hasNext())\n            #set ($mailStatus = $failedMailStatuses.next())\n            #displayError($mailStatus.errorDescription)\n          #else\n\n            {{info}}$services.localization.render('xe.admin.passwordReset.emailSent', ["$userDoc.display('email', $userObj)"]){{/info}}\n\n          #end\n        #end\n      #end\n    #end\n  #end\n  [[{{translation key="xe.admin.passwordReset.error.retry"/}}&gt;&gt;$doc.fullName]] | [[{{translation key="xe.admin.passwordReset.error.recoverUsername"/}}&gt;&gt;ForgotUsername]] | [[{{translation key="xe.admin.passwordReset.login"/}}&gt;&gt;path:$xwiki.getURL('XWiki.XWikiLogin', 'login')]]\n#end\n## Clear private variables, so that they cannot be accessed from the rest of the page (comments, panels...)\n#set ($verifStr = '')\n#set ($passwordResetURL = '')\n{{/velocity}}</content></xwikidoc>\n
6159279780701781039	1	1	2017-05-12 15:43:30	Install extension [org.xwiki.platform:xwiki-platform-skin-ui-7.1.2]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>SkinsCode</web>\n<name>XWikiSkinsSheet</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>XWiki.XWikiSkins</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1364502208000</creationDate>\n<date>1494618210000</date>\n<contentUpdateDate>1494618210000</contentUpdateDate>\n<version>1.1</version>\n<title>$services.localization.render('xe.admin.skin')</title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.xwiki.platform:xwiki-platform-skin-ui-7.1.2]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.1</syntaxId>\n<hidden>true</hidden>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>SkinsCode.XWikiSkinsSheet</name>\n<number>0</number>\n<className>XWiki.JavaScriptExtension</className>\n<guid>e262ce20-f28a-4fa0-89e2-c8413e10dce4</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>#set($discard = $services.localization.use('document', 'SkinsCode.Translations'))\nrequire(['jquery', 'xwiki-meta'], function($, xm) {\n\n  // The global variable that will hold the notification widget (wo we can use it in different functions without adding\n  // it to the parameters of these functions)\n  var notif = 0;\n\n  /**\n   * Function called when the user clicks on the 'delete' button of an object\n   */\n  var onDeleteObj = function() {\n    var obj = $(this).parents('.overrideObject');\n    // Getting the object number via the name of an input (eg: XWiki.XWikiSkinFileOverrideClass_3_path -&gt; 3).\n    var objNumber = obj.find('input').prop('name').split('_')[1];\n    // Called when the user confirm the deletion\n    var deleteObjOnConfirm = function() {\n      // Perform asynchronously the deletion\n      notif = new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.deleting'))', 'inprogress');\n      $.ajax({\n        'url'      : (new XWiki.Document(xm.page, xm.space)).getURL('get'),\n        'type'     : 'POST',\n        'dataType' : 'json',\n        'data' : {\n          'action'      : 'deleteObj'            ,\n          'objNumber'   : objNumber ,\n          'form_token'  : xm.form_token       ,\n          'outputSyntax': 'plain'\n        }\n      }).done(function(data){\n        if (data.status == 'success') {\n          obj.fadeOut();\n          notif.replace(new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.deletingDone'))', 'done'));\n        } else if (data.status == 'fail') {\n          if (data.cause == 'form_token') {\n            notif.replace(new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.error.csrf'))', 'error'));\n          } else if (data.cause == 'rights') {\n            notif.replace(new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.error.rights'))', 'error'));\n          }\n        }\n      });\n    }\n    \n    var confirmationBoxParams = {\n      confirmationText: '$escapetool.javascript($services.localization.render('skin.sheet.js.deleteConfirmationText'))',\n      yesButtonText: '$escapetool.javascript($services.localization.render('skin.sheet.js.deleteConfirmationYes'))',\n      noButtonText: '$escapetool.javascript($services.localization.render('skin.sheet.js.deleteConfirmationNo'))'\n    };\n    \n    // Display a confirmation box\n    new XWiki.widgets.ConfirmationBox({onYes: deleteObjOnConfirm}, confirmationBoxParams);\n    \n    // Do not perform the default action bound to the &lt;button&gt; element\n    return false;\n  }\n\n  /**\n   * Function called when an override object is clicked.\n   * It shows/hides the properties of the object.\n   */\n  var objTitleClicked = function() {\n    var properties = $(this).parent().find('.overrideProperties');\n    if (properties.hasClass('hidden')) {\n      // It is the first time we open the object\n      // So we remove our own 'hidden' property\n      properties.removeClass('hidden');\n      // Then we hide the object via jQuery\n      properties.hide();\n      // So now we can make it slide (not possible if it were not hidden by jQuery first)\n      properties.slideDown();\n    } else {\n      // The other time, we just use the toggle function\n      properties.slideToggle();\n    }\n  }\n  \n  /**\n   * Function that performs an ajax request to get the code that displays an object and inject it in the page.\n   */\n  var displayObj = function(objNumber) {\n    $.ajax({\n      'url'  : (new XWiki.Document(xm.page, xm.space)).getURL('get'),\n      'type' : 'GET',\n      'data' : {\n        'action'    : 'displayObj',\n        'objNumber' : objNumber\n      }\n    }).done(function(data) {\n      notif.replace(new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.addingDone'))', 'done'));\n      // Add the html code into the document\n      $('#overrideSection').append(data);\n      // Get the new object\n      var newObj = $('.overrideObject').last();\n      // Bind the events of the new objects\n      newObj.find('.overrideTitle').click(objTitleClicked);\n      newObj.find('button').click(onDeleteObj);\n      // Show the new object\n      // First we remove our own 'hidden' class\n      newObj.find('.overrideProperties').removeClass('hidden');\n      // Then we hide the object via the jQuery API\n      newObj.hide();\n      // So now we can make it fade (not possible if it were not hidden by jQuery first)\n      newObj.fadeIn();\n      // Scroll to the element\n      $('html, body').animate({scrollTop: newObj.offset().top}, 500);\n    });\n  }\n\n  /**\n   * Function called when the user add a new override object\n   */\n  $('#newPathAdd').click(function() {\n    $.ajax({\n      'url'      : (new XWiki.Document(xm.page, xm.space)).getURL('get'),\n      'type'     : 'POST',\n      'dataType' : 'json',\n      'data' : {\n        'action'      : 'newObj'            ,\n        'path'        : $('#newPath').val() ,\n        'form_token'  : xm.form_token       ,\n        'outputSyntax': 'plain'\n      }\n    }).done(function(data) {\n      notif = new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.adding'))', 'inprogress');\n      if (data.status == 'success') {\n        displayObj(data.objNumber);\n      } else if (data.status == 'fail') {\n        if (data.cause == 'form_token') {\n          notif.replace(new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.error.csrf'))', 'error'));\n        } else if (data.cause == 'rights') {\n          notif.replace(new XWiki.widgets.Notification('$escapetool.javascript($services.localization.render('skin.sheet.js.error.rights'))', 'error'));\n        }\n      }\n    });\n    \n    // Do not perform the default action bound to the &lt;button&gt; element\n    return false;\n  });\n  \n  var onDeprecatedPropertyClicked = function() {\n    $('.deprecatedProperties &gt; dl').slideToggle();\n  }\n  \n  /**\n   * Function that initialize the javascript events\n   */\n  var init = function() {\n    // Bind objTitleClicked to the existing objects\n    $('.overrideTitle').click(objTitleClicked);\n    // Bind onDeleteObj to the existing objects\n    $('.overrideObject button').click(onDeleteObj);\n    $('.deprecatedProperties &gt; dl').hide();\n    $('.deprecatedProperties &gt; h2').click(onDeprecatedPropertyClicked);\n  }\n  \n  init();\n\n});\n</code></property><property><name>JS</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>currentPage</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.StyleSheetExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<contentType>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>contentType</name>\n<number>6</number>\n<prettyName>Content Type</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>CSS|LESS</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</contentType>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>SkinsCode.XWikiSkinsSheet</name>\n<number>0</number>\n<className>XWiki.StyleSheetExtension</className>\n<guid>1e4faabf-d1ba-4fff-806a-2b88c6688e92</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>#template('colorThemeInit.vm')\n\n.overrideTitle:hover, .deprecatedProperties h2:hover{\n  background-color: $theme.highlightColor;\n  cursor: pointer;\n}\n\n.overrideProperties {\n  margin-left: 25px;\n}\n\n.overrideObjectDelete {\n  position: relative;\n  text-align: right;\n  margin-top: -40px;\n  float: right;\n  font-size: 130%;\n}\n\n.skin-colibri .overrideObjectDelete {\n  margin-top: -55px;\n}\n\n.newPathLabel {\n  color: $theme.linkColor;\n  display: inline;\n  font-size: 100%;\n  font-style: italic;\n  font-weight: normal;\n  margin: 0px;\n  text-transform: none;\n}\n</code></property><property><contentType>CSS</contentType>\n</property>\n<property>\n<name>CSS</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<content>{{velocity}}\n#####################################\n##      XWikiSkins Sheet\n#####################################\n#set($discard = $xwiki.ssx.use('SkinsCode.XWikiSkinsSheet'))\n#set($discard = $xwiki.jsx.use('SkinsCode.XWikiSkinsSheet'))\n#set($discard = $services.localization.use('document', 'SkinsCode.Translations'))\n#####################\n##   CONTROLLER\n#####################\n## Keep testing the inline action for backward compatibility with existing skin documents.\n#if ($xcontext.action == 'edit' || $xcontext.action == 'inline')\n  #edit()\n#elseif ($xcontext.action == 'get')\n  #if($request.action == 'newObj')\n    #newObj()\n  #elseif($request.action == 'displayObj')\n    #set($obj = $doc.getObject('XWiki.XWikiSkinFileOverrideClass', $numbertool.toNumber($request.objNumber).intValue()))\n    #displayOverrideObject($obj)\n  #elseif($request.action == 'deleteObj')\n    #deleteObj()\n  #end\n#else\n  #view()\n#end\n#####################\n##      VIEW\n#####################\n#macro(view)\n  ## Call getDefaultEditMode() for backward compatibility with existing skins.\n  * [[{{translation key="xe.admin.skin.editskin"/}}&gt;&gt;path:${doc.getURL($doc.getDefaultEditMode())}]]\n  * [[{{translation key="xe.admin.skin.testskin"/}}&gt;&gt;$services.model.resolveDocument('', 'default', $doc.documentReference.extractReference('WIKI'))||queryString="skin=${doc.fullName}"]]\n#end\n#####################\n##      EDIT\n#####################\n#macro(edit)\n  == {{translation key="skin.sheet.properties" /}} ==\n  ## Display the class properties\n  #set ($deprecatedProperties = [])\n  #set ($className = 'XWiki.XWikiSkins')\n  #set ($class = $doc.getObject($className).xWikiClass)\n  #foreach ($prop in $class.properties)\n    #if ($prop.classType != 'TextArea')\n    ; $prop.prettyName\n    : #if($prop.name == 'logo'){{attachmentSelector classname="${className}" property="${prop.name}" filter="png,jpg,gif" displayImage="true"/}}#else $doc.display($prop.name)#end\n    \n    #else\n      #set($discard = $deprecatedProperties.add($prop))\n    #end\n  #end\n  (% id="overrideSection" %)\n  (((\n    == {{translation key="skin.sheet.overriddenTemplates" /}} ==\n    \n    {{warning}}\n      {{translation key="skin.sheet.overrideTemplateWarning" /}}\n    {{/warning}}\n    \n    {{html}}\n    &lt;noscript&gt;\n      &lt;div class="box errormessage"&gt;\n        $services.localization.render('skin.sheet.nojs', ["&lt;a href='$doc.getURL('edit', 'editor=object')'&gt;", '&lt;/a&gt;', 'XWiki.XWikiSkinFileOverrideClass'])\n      &lt;/div&gt;\n    &lt;/noscript&gt;\n    {{/html}}\n    \n    {{html}}\n    &lt;div id="addOverride"&gt;\n      &lt;label for="newPath" class="newPathLabel"&gt;$services.icon.renderHTML('add') $services.localization.render("skin.sheet.addTemplate")&lt;/label&gt;\n      &lt;input placeholder="file.vm" id="newPath" name="newPath" value="file.vm" size="20" class="withTip" type="text" /&gt;\n      &lt;button class="btn btn-primary" id="newPathAdd"&gt;$services.localization.render("skin.sheet.add")&lt;/button&gt;\n    &lt;/div&gt;\n    {{/html}}\n    ## Display the XWiki.XWikiSkinFileOverrideClass objects\n    #foreach ($obj in $doc.getObjects('XWiki.XWikiSkinFileOverrideClass'))\n      #displayOverrideObject($obj)\n    #end\n  )))\n  \n  #if ($deprecatedProperties.size() &gt; 0)\n    (% class="deprecatedProperties" %)\n    (((\n      == {{translation key="skin.sheet.deprecatedProperties" /}} ==\n      \n      {{warning}}\n        {{translation key="skin.sheet.deprecatedPropertiesWarning" /}}\n      {{/warning}}\n      \n      #foreach ($prop in $deprecatedProperties)\n        #if ($prop.classType == 'TextArea')\n        ; $services.icon.render('file-white') $prop.prettyName\n        : $doc.display($prop.name)\n        \n        #end\n      #end\n    )))\n  #end\n#end\n###########################\n##  DISPLAY OVERRIDE OBJ\n###########################\n#macro(displayOverrideObject $obj)\n  (% class="overrideObject" %)\n  (((\n    (% class="overrideTitle" %)\n    === $services.icon.render('file-white') $obj.display('path', 'view') ===\n    (% class="overrideObjectDelete" %)\n    (((\n      {{html}}&lt;button class="btn btn-default btn-xs"&gt;$services.icon.renderHTML('cross')&lt;/button&gt;{{/html}}\n    )))\n    (% class="overrideProperties hidden" %)\n    (((\n      #set ($className = 'XWiki.XWikiSkinFileOverrideClass')\n      #set ($class = $doc.getObject($className).xWikiClass)\n      #foreach ($prop in $class.properties)\n        ; $prop.prettyName\n        : $obj.display($prop.name, 'edit')\n    \n      #end\n    )))\n    ----\n  )))\n#end\n###########################\n##     CHECK RIGHTS\n###########################\n#macro(checkRights $response)\n  #if(!$services.csrf.isTokenValid($request.form_token))\n    #set($discard = $response.put('status', 'fail'))\n    #set($discard = $response.put('cause', 'form_token'))\n  #elseif(!$xwiki.hasAccessLevel('edit', $xcontext.user, $doc.fullname))\n    #set($discard = $response.put('status', 'fail'))\n    #set($discard = $response.put('cause', 'rights'))\n  #end\n#end\n###########################\n##       NEW OBJ\n###########################\n#macro(newObj)\n  #set($response = {})\n  #checkRights($response)\n  #if("$!response.get('status')" != 'fail')\n    #set($obj = $doc.newObject('XWiki.XWikiSkinFileOverrideClass'))\n    #set($discard = $obj.set('path', $request.path))\n    #set($discard = $doc.save('Add a new XWiki.XWikiSkinFileOverrideClass object'))\n    #set($discard = $response.put('objNumber', $obj.number))\n    #set($discard = $response.put('status', 'success'))\n  #end\n  $jsontool.serialize($response)\n#end\n###########################\n##      DELETE OBJ\n###########################\n#macro(deleteObj)\n  #set($response = {})\n  #checkRights($response)\n  #if("$!response.get('status')" != 'fail')\n    #set($objNumber = $numbertool.toNumber($request.objNumber).intValue())\n    #set($obj = $doc.getObject('XWiki.XWikiSkinFileOverrideClass', $objNumber))\n    #set($discard = $doc.removeObject($obj))\n    #set($saveMessage = "Remove the object XWiki.XWikiSkinFileOverrideClass[" + $obj.getValue('path') + "]")\n    #set($discard = $doc.save($saveMessage))\n    #set($discard = $response.put('status', 'success'))\n  #end\n  $jsontool.serialize($response)\n#end\n{{/velocity}}\n</content></xwikidoc>
