2919783485271046162	1	1	2017-05-12 15:43:31	Install extension [org.xwiki.platform:xwiki-platform-index-ui-7.1.2]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>XWiki</web>\n<name>AllAttachments</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>Main.AllDocs</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1252454400000</creationDate>\n<date>1494618211000</date>\n<contentUpdateDate>1494618211000</contentUpdateDate>\n<version>1.1</version>\n<title>$services.localization.render('platform.index.attachments')</title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.xwiki.platform:xwiki-platform-index-ui-7.1.2]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.0</syntaxId>\n<hidden>true</hidden>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>XWiki.AllAttachments</name>\n<number>0</number>\n<className>XWiki.JavaScriptExtension</className>\n<guid>9ad0f248-6336-4543-ae2b-fd41dda77be4</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>(function(){\n\nif (typeof XWiki == "undefined") {\n   XWiki = new Object();\n}\n\nif (typeof XWiki.index == "undefined") {\n   XWiki.index = new Object();\n}\n\nvar mimetypes = {\n  "image/svg"                     : { "src" : "$xwiki.getSkinFile('icons/silk/vector.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.svg')}", "title" : "${services.localization.render('core.viewers.attachments.mime.svg')}" },\n  "application/svg+xml"           : { "src" : "$xwiki.getSkinFile('icons/silk/vector.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.svg')}", "title" : "${services.localization.render('core.viewers.attachments.mime.svg')}" },\n  "text/plain"                    : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_text.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.text')}", "title" : "${services.localization.render('core.viewers.attachments.mime.text')}"},\n  "text/html"                     : { "src" : "$xwiki.getSkinFile('icons/silk/html.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.html')}", "title" : "${services.localization.render('core.viewers.attachments.mime.html')}"},\n  "text/css"                      : { "src" : "$xwiki.getSkinFile('icons/silk/css.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.css')}", "title" : "${services.localization.render('core.viewers.attachments.mime.css')}" },\n  "application/xml"               : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_code.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.xml')}", "title" : "${services.localization.render('core.viewers.attachments.mime.xml')}" },\n  "application/pdf"               : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_acrobat.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.pdf')}", "title" : "${services.localization.render('core.viewers.attachments.mime.pdf')}" },\n  "application/postscript"        : { "src" : "$xwiki.getSkinFile('icons/silk/page_red.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.ps')}",   "title" : "${services.localization.render('core.viewers.attachments.mime.ps')}"  },\n  "application/msword"            : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_word.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.document')}", "title" : "${services.localization.render('core.viewers.attachments.mime.document')}"},\n  "application/powerpoint"        : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_powerpoint.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.presentation')}", "title" : "${services.localization.render('core.viewers.attachments.mime.presentation')}" },\n  "application/x-shockwave-flash" : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_flash.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.flash')}", "title" : "${services.localization.render('core.viewers.attachments.mime.flash')}" },\n  "application/x-tar"             : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_compressed.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.tar')}", "title" : "${services.localization.render('core.viewers.attachments.mime.tar')}" },\n  "application/zip"               : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_zip.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.zip')}", "title" : "${services.localization.render('core.viewers.attachments.mime.zip')}" },\n  "application/x-gzip"            : { "src" : "$xwiki.getSkinFile('icons/silk/page_white_compressed.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.gz')}", "title" : "${services.localization.render('core.viewers.attachments.mime.gz')}"  },\n  "application/java-archive"      : { "src" : "$xwiki.getSkinFile('icons/silk/cup.png')", "alt" : "${services.localization.render('core.viewers.attachments.mime.jar')}", "title" : "${services.localization.render('core.viewers.attachments.mime.jar')}" }\n};\n\n/**\n * JavasScript equivalent of the #mimetype macro.\n * Returns a 20px * 20px image (as an element) corresponding to the passed mimetype.\n * First lookup if the type is in the mimetypes object above, then handles some other cases (starts/end with, etc.)\n * This function should be cleaned at the same time the mimetype images and macro are.\n */\nfunction getMimeTypeImage(type) {\n  var image = undefined;\n  if (mimetypes[type]) {\n    image = new Element('img',{'src':mimetypes[type].src,'alt':mimetypes[type].alt,'title':mimetypes[type].title});\n  }\n  else if(type.match(/^image\\//)) {\n    image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/picture.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.image')}", 'title': "${services.localization.render('core.viewers.attachments.mime.image')}"});\n  }\n  else if(type.match(/^text\\//)) {\n    image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/page_white_text.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.text')}", 'title': "${services.localization.render('core.viewers.attachments.mime.text')}"});\n  }\n  else if(type.match(/^audio\\//)){\n    image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/music.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.audio')}", 'title': "${services.localization.render('core.viewers.attachments.mime.audio')}"});\n  }\n  else if(type.match(/^video\\//)){\n    image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/film.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.video')}", 'title': "${services.localization.render('core.viewers.attachments.mime.video')}"});\n  }\n  else if(type=="application/octet-stream") {\n    if (type.match(/\\.xls$/)) {\n      image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/page_white_excel.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.spreadsheet')}", 'title': "${services.localization.render('core.viewers.attachments.mime.spreadsheet')}"});\n    }\n    else if (type.match(/\\.bz$/)) {\n      image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/page_white_compressed.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.bz')}", 'title': "${services.localization.render('core.viewers.attachments.mime.bz')}"});\n    }\n    else if (type.match(/\\.tgz$/)) {\n      image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/page_white_compressed.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.gz')}", 'title': "${services.localization.render('core.viewers.attachments.mime.gz')}"});\n    }\n    else if (type.match(/\\.rar$/)) {\n      image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/page_white_compressed.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.rar')}", 'title': "${services.localization.render('core.viewers.attachments.mime.rar')}"});\n    }\n    else if (type.match(/\\.(odt|odp|odf|ods|sxw|stw)$/)) {\n      image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/page.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.office')}", 'title': "${services.localization.render('core.viewers.attachments.mime.office')}"});\n    }\n  } \n  else if (type.match(/^application\\//)) {\n    image = new Element('img', {'src':"$xwiki.getSkinFile('icons/silk/cog.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.exe')}", 'title': "${services.localization.render('core.viewers.attachments.mime.exe')}"});\n  }\n  if (typeof image == "undefined") {\n    image = new Element('img', {'src': "$xwiki.getSkinFile('icons/silk/page_white.png')", 'alt':"${services.localization.render('core.viewers.attachments.mime.attachment')}", 'title': "${services.localization.render('core.viewers.attachments.mime.attachment')}"});\n  }\n  image.style.width = '16px';\n  image.style.height = '16px';\n  return image;\n}\n\nXWiki.index.displayAttachmentEntry = function (row, i, table) {\n  var inaccessibleDocs = false;\n  if(row.acclev == true) {\n    var fileLink = new Element('a', {'href' : row.fileurl}).update(row.filename);\n    var tr = new Element('tr').update(new Element('td').update(fileLink));\n    var pageLink = new Element('a', {'href' : row.url}).update(row.page);\n    tr.appendChild(new Element('td', {'class' : 'pagename'}).update(pageLink));\n    var spaceLink = new Element('a', {'href' : row.spaceurl}).update(row.space);\n    tr.appendChild(new Element('td', {'class' : 'spacename'}).update(spaceLink));\n    tr.appendChild(new Element('td').update(row.date));\n    var aa = new Element('a', {'href' : row.authorurl}).update(row.authorname);\n    tr.appendChild(new Element('td').update(aa));\n    var type = new Element('td').update(getMimeTypeImage(row.type));\n    tr.appendChild(type);\n    return tr;\n  } else {\n    var tr = new Element('tr');\n    var page = row.fullname;\n\n    var td1 = new Element('td').update("unavailable");\n    var td2 = new Element('td', {'class' : 'pagename'}).update(page + "*");\n    var td3 = new Element('td').update(" ");\n    var td4 = new Element('td').update(" ");\n    var td5 = new Element('td').update(" ");\n    var td6 = new Element('td').update(" ");\n    tr.appendChild(td1);\n    tr.appendChild(td2);\n    tr.appendChild(td3);\n    tr.appendChild(td4);\n    tr.appendChild(td5);\n    tr.appendChild(td6);\n    $('inaccessibleDocsMessage').removeClassName('hidden');\n    return tr;\n  }\n}\n\n})();\n</code></property><property><name></name></property><property><parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<content>{{velocity}}\n#set ($discard = $xwiki.jsx.use('XWiki.AllAttachments'))\n##\n#set ($collist = ['filename', 'doc.name', 'doc.space', 'date', 'author', 'type'])\n#set ($colprops = {\n                   'filename'  : { 'type' : 'text', 'size' : 10 },\n                   'doc.name'  : { 'type' : 'text', 'size' : 10 },\n                   'doc.space' : { 'type' : 'text', 'size' : 10 },\n                   'date'      : { 'type' : 'date', 'size' : 10, 'filterable' : false },\n                   'author'    : { 'type' : 'text', 'size' : 10 },\n                   'type'      : { 'sortable' : false }\n                 })\n#set($options = { 'url' : $xwiki.getURL('XWiki.AllAttachmentsResults', 'get', 'xpage=plain&amp;outputSyntax=plain'),\n                  'callback' : 'XWiki.index.displayAttachmentEntry',\n                  'translationPrefix' : 'platform.index.attachments.' })\n#livetable('allattachments' $collist $colprops $options)\n\n(% id="inaccessibleDocsMessage" class="hidden" %)\n(((\n{{info}}$services.localization.render('rightsmanager.documentrequireviewrights'){{/info}}\n)))\n{{/velocity}}</content></xwikidoc>\n
-4173326538303807814	1	1	2017-05-12 15:43:31	Install extension [org.xwiki.platform:xwiki-platform-index-ui-7.1.2]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>XWiki</web>\n<name>DocumentTreeTranslations</name>\n<language></language>\n<defaultLanguage>en</defaultLanguage>\n<translation>0</translation>\n<parent>XWiki.DocumentTree</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1424709160000</creationDate>\n<date>1494618211000</date>\n<contentUpdateDate>1494618211000</contentUpdateDate>\n<version>1.1</version>\n<title>Document Tree Translations</title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.xwiki.platform:xwiki-platform-index-ui-7.1.2]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.1</syntaxId>\n<hidden>true</hidden>\n<object>\n<class>\n<name>XWiki.TranslationDocumentClass</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<scope>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>scope</name>\n<number>1</number>\n<prettyName>Scope</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>GLOBAL|WIKI|USER|ON_DEMAND</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</scope>\n</class>\n<name>XWiki.DocumentTreeTranslations</name>\n<number>0</number>\n<className>XWiki.TranslationDocumentClass</className>\n<guid>7b0ef63b-7bc3-4950-a557-9d076eeafa54</guid>\n<property>\n<scope>WIKI</scope>\n</property>\n</object>\n<content>rendering.macro.documentTree.name=Document Tree\nrendering.macro.documentTree.description=Displays the tree of XWiki documents.\nrendering.macro.documentTree.parameter.readOnly.name=Read Only\nrendering.macro.documentTree.parameter.readOnly.description=Should the user be able to modify the tree structure, provided she has the necessary rights?\nrendering.macro.documentTree.parameter.showWikis.name=Show Wikis\nrendering.macro.documentTree.parameter.showWikis.description=Whether to show the wiki nodes or not. This can be used only on the main wiki and if the tree source has been saved with programming rights.\nrendering.macro.documentTree.parameter.showWikiPrettyName.name=Show Wiki Pretty Name\nrendering.macro.documentTree.parameter.showWikiPrettyName.description=Show the wiki pretty name instead of the wiki id when displaying a wiki node.\nrendering.macro.documentTree.parameter.showSpaces.name=Show Spaces\nrendering.macro.documentTree.parameter.showSpaces.description=Whether to show the space nodes or not. The documents are grouped by space if the space nodes are displayed.\nrendering.macro.documentTree.parameter.showDocumentTitle.name=Show Document Title\nrendering.macro.documentTree.parameter.showDocumentTitle.description=Whether to show the document title instead of the document name when displaying a document node.\nrendering.macro.documentTree.parameter.showTranslations.name=Show Translations\nrendering.macro.documentTree.parameter.showTranslations.description=Whether to show the document translations or not.\nrendering.macro.documentTree.parameter.showAttachments.name=Show Attachments\nrendering.macro.documentTree.parameter.showAttachments.description=Whether to show the document attachments or not.\nrendering.macro.documentTree.parameter.showObjects.name=Show Objects\nrendering.macro.documentTree.parameter.showObjects.description=Whether to show the document objects or not.\nrendering.macro.documentTree.parameter.showClassProperties.name=Show Class Properties\nrendering.macro.documentTree.parameter.showClassProperties.description=Whether to show the class properties for documents that define classes.\nrendering.macro.documentTree.parameter.showChildDocuments.name=Show Child Documents\nrendering.macro.documentTree.parameter.showChildDocuments.description=Whether to show the child documents based on the document parent field.\nrendering.macro.documentTree.parameter.root.name=Root\nrendering.macro.documentTree.parameter.root.description=The root node id. This is useful if you want to display only the descendants of a given node (which is the specified root). The tree displays the children of the root node on the first level, so the root node is not actually displayed. The entire tree is displayed if the root node is not specified. The format of a node identifier is entityType:entityReference, where the entity type can be for instance wiki, space, document. E.g.: wiki:xwiki, space:xwiki:Main, document:xwiki:Main.WebHome\nrendering.macro.documentTree.parameter.compact.name=Compact\nrendering.macro.documentTree.parameter.compact.description=If you have limited horizontal space available then you should probably set this to true. The effect is that the node icons and the edges that connect them will be hidden. Some special styles will also be applied to ensure the tree takes less horizontal space while keeping the node labels fully visible.\nrendering.macro.documentTree.parameter.links.name=Links\nrendering.macro.documentTree.parameter.links.description=Specifies whether the node labels should look and behave as links (anchors).\nrendering.macro.documentTree.parameter.checkboxes.name=Checkboxes\nrendering.macro.documentTree.parameter.checkboxes.description=Whether to display a checkbox in front of each tree node to allow the user to select multiple tree nodes.\nrendering.macro.documentTree.parameter.openTo.name=Open to\nrendering.macro.documentTree.parameter.openTo.description=The id of the node to open the tree to. All the ancestors of the specified node, up to the root of the tree, will be opened also. The format of the node id is the one used for the root parameter.\nrendering.macro.documentTree.parameter.showOnlyViewable.name=Show only Viewable\nrendering.macro.documentTree.parameter.showOnlyViewable.description=Show only the wiki, space and document nodes for which the current user has view right. If this is set to false then the wiki, space and document nodes that are not viewable by the current user are listed in the tree using their names. The user won't be able to see their content by following their links though (the user will just be aware of their existence).\nrendering.macro.documentTree.parameter.filterByClass.name=Filter by Class\nrendering.macro.documentTree.parameter.filterByClass.description=Show only the documents that have an object of the specified type. The value of this parameter is the full name of an XWiki document that holds a class definition. For example, 'Blog.CategoryClass' can be used to show only the documents that represent blog categories. Leave this parameter empty if you don't want to restrict the type of documents shown in the tree.\nrendering.macro.documentTree.parameter.finder.name=Finder\nrendering.macro.documentTree.parameter.finder.description=Show a text input that can be used to find tree nodes. The input is displayed above the tree and offers suggestions as you type based on the content of the tree. When a suggestion is selected the tree is expanded up to the corresponding node.</content></xwikidoc>\n
22690398456488318	1	1	2017-05-12 15:43:31	Install extension [org.xwiki.platform:xwiki-platform-index-ui-7.1.2]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>XWiki</web>\n<name>DeletedDocuments</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>Main.AllDocs</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1404731556000</creationDate>\n<date>1494618211000</date>\n<contentUpdateDate>1494618211000</contentUpdateDate>\n<version>1.1</version>\n<title>$services.localization.render('platform.index.documentsTrash')</title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.xwiki.platform:xwiki-platform-index-ui-7.1.2]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.0</syntaxId>\n<hidden>true</hidden>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>XWiki.DeletedDocuments</name>\n<number>0</number>\n<className>XWiki.JavaScriptExtension</className>\n<guid>222ca0ed-b042-41d5-9d7e-942c4cc8a94b</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>// Make sure the XWiki.index.trash.documents 'namespace' exists.\nif (typeof XWiki == "undefined") {\n  XWiki = new Object();\n}\nif (typeof XWiki.index == "undefined") {\n  XWiki.index = new Object();\n}\nif (typeof XWiki.index.trash == "undefined") {\n  XWiki.index.trash = new Object();\n}\nif (typeof XWiki.index.trash.documents == "undefined") {\n  XWiki.index.trash.documents = new Object();\n}\n\n/**\n * Callback function used by the DeletedDocuments livetable for generating the HTML code needed to display an entry.\n * \n * @param row the JSON data corresponding to the entry to be displayed\n * @param i the index of the row in the list of entries\n * @param table the LiveTable javascript object\n */\nXWiki.index.trash.documents.displayEntry = function (row, i, table) {\n  var tr = new Element('tr'); // The resulting table row\n  var pageTd = new Element('td');\n  var page = new Element('a', {'href' : row.url}).update(row.fullname);\n  pageTd.appendChild(page);\n  if (row.language &amp;&amp; row.language.trim().length != 0) {\n    var language = new Element('span').update('(' + row.language.trim() + ')');\n    pageTd.appendChild(document.createTextNode(' '));\n    pageTd.appendChild(language);\n  }\n  tr.appendChild(pageTd);\n  tr.appendChild(new Element('td').update(row.title));\n  tr.appendChild(new Element('td').update(row.date));\n  var deleter = new Element('a', {'href' : row.deleterurl}).update(row.deletername);\n  tr.appendChild(new Element('td').update(deleter));\n  var actions = new Element('td', {'class' : 'itemActions'});\n  if(!row.alreadyExists) {\n    if(row.canRestore) {\n      if (row.causesOrphanedTranslation) {\n        // Can not restore: It would cause the translation to be inaccessible from the UI until the main document is restored/created.\n        var restore = new Element('a', {\n            'href' : row.originalUrl,\n            'class' : 'tool cannot-restore',\n            'title' : "$services.localization.render('platform.index.trashDocumentsActionsCannotRestoreCausesOrphanedTranslationTooltip')"\n          }).update("$services.localization.render('platform.index.trashDocumentsActionsCannotRestoreText')");\n        actions.appendChild(restore);\n      } else {\n        // Restore the document.\n        var restore = new Element('a', {\n            'href' : row.restoreUrl,\n            'class' : 'tool restore',\n            'title' : "$services.localization.render('platform.index.trashDocumentsActionsRestoreTooltip')"\n          }).update("$services.localization.render('platform.index.trashDocumentsActionsRestoreText')");\n        actions.appendChild(restore);\n      }\n    }\n  } else {\n    // Can not restore: A document was already restored at that location.\n    // TODO: Add an overwrite dialog here.\n    var restore = new Element('a', {\n        'href' : row.originalUrl,\n        'class' : "tool cannot-restore",\n        'title' : "$services.localization.render('platform.index.trashDocumentsActionsCannotRestoreTooltip')"\n      }).update("$services.localization.render('platform.index.trashDocumentsActionsCannotRestoreText')");\n    actions.appendChild(restore);\n  }\n  if(row.canDelete) {\n    var delete_ = new Element('a', {\n        'href' : row.deleteUrl,\n        'class' : "tool delete",\n        'title' : "$services.localization.render('platform.index.trashDocumentsActionsDeleteTooltip')"\n      }).update("$services.localization.render('platform.index.trashDocumentsActionsDeleteText')");\n    actions.appendChild(document.createTextNode(' '));\n    actions.appendChild(delete_);\n    delete_.observe('click', XWiki.index.trash.documents.confirmDelete.bindAsEventListener(delete_, table, i));\n  }\n  tr.appendChild(actions);\n  return tr;\n}\n\n/**\n * Event listener, called when clicking a delete version link. It displays a confirmation box, speeding up the two-step\n * deletion process.\n * \n * @param event the link activation event\n * @param table the LiveTable javascript object\n * @param rowIdx the index of the row corresponding to the entry to be deleted\n */\nXWiki.index.trash.documents.confirmDelete = function(event, table, rowIdx) {\n  event.stop();\n  if (this.disabled) {\n    // Do nothing if the button was already clicked and it's waiting for a response from the server.\n    return;\n  } else {\n    new XWiki.widgets.ConfirmedAjaxRequest(\n      /* Ajax request URL */\n      this.href + '&amp;confirm=1' + (Prototype.Browser.Opera ? "" : "&amp;ajax=1"),\n      /* Ajax request parameters */\n      {\n        onCreate : function() {\n          // Disable the button, to avoid a cascade of clicks from impatient users\n          this.disabled = true;\n        }.bind(this),\n        onSuccess : function(table, rowIdx) {\n          // Remove the corresponding HTML element from the UI and update the livetable\n          table.deleteRow(rowIdx);\n        }.bind(this, table, rowIdx),\n        // This is an expected 404, returned when the document has been successfully deleted and is no longer found\n        on404 : function(response, table, rowIdx) {\n          response.request.options.onSuccess(table, rowIdx);\n        }.bindAsEventListener(this, table, rowIdx),\n        onComplete : function() {\n          // In the end: re-enable the button\n          this.disabled = false;\n        }.bind(this)\n      },\n      /* Interaction parameters */\n      {\n         confirmationText: "$services.localization.render('core.recyclebin.completelyDeleteConfirm')",\n         progressMessageText : "$services.localization.render('platform.index.trashDocumentsDeleteInProgress')",\n         successMessageText : "$services.localization.render('platform.index.trashDocumentsDeleteDone')",\n         failureMessageText : "$services.localization.render('platform.index.trashDocumentsDeleteFailed')"\n      }\n      );\n  }\n}\n/*\n * The livetable is hidden when javascript is disabled, so that an alternative &lt;noscript&gt; table is displayed.\n * Re-display it when the document loads and Javascript is available.\n */\ndocument.observe('xwiki:dom:loaded', function() {\n  if ($('documentsTrash')) {\n    $('documentsTrash').up('.hidden').removeClassName('hidden');\n  }\n});</code>\n</property>\n<property>\n<name></name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<name>XWiki.DeletedDocuments</name>\n<number>0</number>\n<className>XWiki.RequiredRightClass</className>\n<guid>8de78194-f5ba-4cd8-8f0e-69b9d554e31c</guid>\n<property>\n<level>programming</level>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.StyleSheetExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<contentType>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>contentType</name>\n<number>6</number>\n<prettyName>Content Type</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>CSS|LESS</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</contentType>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>XWiki.DeletedDocuments</name>\n<number>0</number>\n<className>XWiki.StyleSheetExtension</className>\n<guid>aa8c7e27-a767-4e44-ac29-7809763dff56</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>.itemActions .tool {\n  width: 16px;\n  height: 16px;\n  margin: 0 2px;\n  float: left;\n  text-indent: -1000em;\n  overflow: hidden;\n  background: transparent no-repeat center center;\n}\n.itemActions .delete {\n  background-image: url("$xwiki.getSkinFile('icons/silk/cross.png')") !important;\n}\n.itemActions .restore {\n   background-image: url("$xwiki.getSkinFile('icons/silk/arrow_refresh.png')") !important;\n}\n.itemActions .cannot-restore {\n   background-image: url("$xwiki.getSkinFile('icons/silk/page_error.png')") !important;\n}</code>\n</property>\n<property>\n<name></name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.XWikiRights</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<allow>\n<defaultValue>1</defaultValue>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>allow</displayType>\n<name>allow</name>\n<number>4</number>\n<prettyName>Allow/Deny</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</allow>\n<groups>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>input</displayType>\n<multiSelect>1</multiSelect>\n<name>groups</name>\n<number>1</number>\n<picker>1</picker>\n<prettyName>Groups</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>5</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.GroupsClass</classType>\n</groups>\n<levels>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>1</multiSelect>\n<name>levels</name>\n<number>2</number>\n<prettyName>Levels</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>3</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.LevelsClass</classType>\n</levels>\n<users>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>input</displayType>\n<multiSelect>1</multiSelect>\n<name>users</name>\n<number>3</number>\n<picker>1</picker>\n<prettyName>Users</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<size>5</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.UsersClass</classType>\n</users>\n</class>\n<name>XWiki.DeletedDocuments</name>\n<number>1</number>\n<className>XWiki.XWikiRights</className>\n<guid>f31fc0c5-7569-4716-8529-b30d3d6a9d9b</guid>\n<property>\n<allow>1</allow>\n</property>\n<property>\n<groups>XWiki.XWikiAdminGroup</groups>\n</property>\n<property>\n<levels>view,edit</levels>\n</property>\n<property>\n<users></users>\n</property>\n</object>\n<content>{{velocity}}##\n#if(!$xwiki.hasProgrammingRights())\n  {{warning}}This document requires programming rights and needs to be saved by an administrator of this Wiki{{/warning}}\n#else\n#set($dateFormat = 'yyyy MMMM d, HH:mm')\n$xwiki.ssx.use('XWiki.DeletedDocuments')##\n$xwiki.jsx.use('XWiki.DeletedDocuments')##\n##\n#set($columns = ["ddoc.fullName", "ddoc.title", "ddoc.date", "ddoc.deleter", 'actions'])\n#set($columnProperties = {\n    'ddoc.fullName'  : { 'type' : 'text', 'size' : 10 },\n    'ddoc.title'     : { 'type' : 'text', 'filterable' : false, 'sortable' : false },\n    'ddoc.date'      : { 'type' : 'date', 'filterable' : false },\n    'ddoc.deleter'   : { 'type' : 'text', 'size' : 10 },\n    'actions'        : { 'type' : 'text', 'filterable' : false, 'sortable' : false }\n  })##\n#set($options = {\n    'url'               : "$xwiki.getURL('XWiki.DeletedDocumentsJSON', 'view', 'list=1&amp;xpage=plain&amp;outputSyntax=plain')",\n    'callback'          : 'XWiki.index.trash.documents.displayEntry',\n    'translationPrefix' : 'platform.index.trashDocuments.'\n  })##\n##\n##\n##\n{{html wiki="true" clean="false"}}\n&lt;div class="hidden"&gt;\n#livetable('documentsTrash' $columns $columnProperties $options)\n&lt;/div&gt;\n{{/html}}\n##\n##\n##\n\n{{html wiki="true" clean="false"}}\n&lt;noscript&gt;\n  #set($deletedDocuments = $services.query.hql('select count(ddoc.id) from XWikiDeletedDocument as ddoc').execute().get(0))\n  #if($deletedDocuments == 0)\n\n    {{info}}$services.localization.render('platform.index.trashDocumentsEmpty'){{/info}}\n\n  #else\n  #macro(displayDeletedDoc $id)\n    #set($ddoc = $xwiki.getDeletedDocument('', '', "$id"))\n    #set($originalDocument = $ddoc.getDocument())\n    &lt;tr&gt;\n      &lt;td&gt;&lt;a href="$originalDocument.getURL('view', "viewer=recyclebin&amp;amp;id=${id}")"&gt;$escapetool.xml($ddoc.fullName)&lt;/a&gt;&lt;/td&gt;\n      &lt;td&gt;$escapetool.xml($originalDocument.plainTitle)&lt;/td&gt;\n      &lt;td&gt;$xwiki.formatDate($ddoc.getDate(), $dateFormat)&lt;/td&gt;\n      &lt;td&gt;$xwiki.getUserName($ddoc.getDeleter())&lt;/td&gt;\n      &lt;td class="itemActions"&gt;\n        #if($xwiki.getDocument($ddoc.fullName).isNew())\n          #if($ddoc.canUndelete())\n            &lt;a href="${originalDocument.getURL('undelete', "id=${id}")}" class="tool restore" title="$services.localization.render('platform.index.trashDocumentsActionsRestoreTooltip')"&gt;$services.localization.render('platform.index.trashDocumentsActionsRestoreText')&lt;/a&gt;\n          #end\n        #else\n          &lt;a href="${originalDocument.getURL()}" class="tool cannot-restore" title="$services.localization.render('platform.index.trashDocumentsActionsCannotRestoreTooltip')"&gt;$services.localization.render('platform.index.trashDocumentsActionsCannotRestoreText')&lt;/a&gt;\n        #end\n        #if($ddoc.canDelete())\n          &lt;a href="${originalDocument.getURL('delete', "id=${id}&amp;amp;xredirect=$escapetool.url($!request.getRequestURI())?$escapetool.url($!request.getQueryString())")}" class="tool delete" title="$services.localization.render('platform.index.trashDocumentsActionsDeleteTooltip')"&gt;$services.localization.render('platform.index.trashDocumentsActionsDeleteText')&lt;/a&gt;\n        #end\n      &lt;/td&gt;\n    &lt;/tr&gt;\n  #end\n##\n  #if("$!{request.view}" == '')\n    #set($queryParams = '')\n  #else\n    #set($queryParams = "view=$!{escapetool.url($request.view)}")\n  #end\n  #set($paginationParameters = {\n    'totalItems' : $services.query.hql('select count(ddoc.id) from XWikiDeletedDocument as ddoc').execute().get(0),\n    'defaultItemsPerPage' : 15,\n    'url' : $doc.getURL('view', $queryParams)\n  })\n  #pagination($paginationParameters)\n  &lt;table id="searchResults" class="xwiki-livetable xwiki-livetable-display"&gt;\n    &lt;thead class="xwiki-livetable-display-header"&gt;&lt;tr&gt;\n      &lt;th scope="col" class="xwiki-livetable-display-header-text selected asc"&gt;$services.localization.render('platform.index.trashDocuments.ddoc.fullName')&lt;/th&gt;\n      &lt;th scope="col" class="xwiki-livetable-display-header-text"&gt;$services.localization.render('platform.index.trashDocuments.ddoc.title')&lt;/th&gt;\n      &lt;th scope="col" class="xwiki-livetable-display-header-text"&gt;$services.localization.render('platform.index.trashDocuments.ddoc.date')&lt;/th&gt;\n      &lt;th scope="col" class="xwiki-livetable-display-header-text"&gt;$services.localization.render('platform.index.trashDocuments.ddoc.deleter')&lt;/th&gt;\n      &lt;th scope="col" class="xwiki-livetable-display-header-text"&gt;$services.localization.render('platform.index.trashDocuments.actions')&lt;/th&gt;\n    &lt;/tr&gt;&lt;/thead&gt;\n    &lt;tbody class="xwiki-livetable-display-body"&gt;\n    #set ($statement = 'select ddoc.id from XWikiDeletedDocument as ddoc order by ddoc.fullName asc')\n    #foreach ($item in $services.query.hql($statement).setLimit($paginationParameters.itemsPerPage).setOffset($paginationParameters.firstItem).execute())\n      #displayDeletedDoc($item)\n    #end\n    &lt;/tbody&gt;\n  &lt;/table&gt;\n  #set($discard = $paginationParameters.put('position', 'bottom'))\n  #pagination($paginationParameters)\n  #end ## deletedDocuments.size\n&lt;/noscript&gt;\n{{/html}}##\n#end## hasProgramR\n{{/velocity}}</content></xwikidoc>\n
