r: pointer;\n  margin: 0px !important;\n  padding: 0px !important;\n  float: none !important;\n}\n#body .yes-no-picker label.highlighted {\n  background-color: #999;\n  color: #fff;\n  text-shadow: 0 1px 1px #000;\n}\n.yes-no-picker label.selected {\n  text-shadow: 0 1px 1px #000;\n}\n\n.yes-no-picker label:first-child {\n  border-top-left-radius: 4px;\n  border-bottom-left-radius: 4px;\n}\n\n.yes-no-picker label:last-child {\n  border-top-right-radius: 4px;\n  border-bottom-right-radius: 4px;\n}\n.yes-no-picker label.yes {\n  color: #000;\n  border-right: 1px solid #fff;\n  border-left: 1px solid #fff;\n}\n.yes-no-picker label.selected.yes {\n  background: #333;\n  color: #FFF;\n}\n\n.yes-no-picker label.no {\n  color: #a00;\n  border-left: 1px solid #fff;\n}\n.yes-no-picker label.semi-selected {\n  background-color: #ccc;\n}\n.yes-no-picker label.selected.no {\n  background: #a00;\n  color: #FFF;\n}\n.yes-no-picker label.na {\n  color: #888;\n  border-right: 4px solid #fff;\n}\n.yes-no-picker label.selected.na {\n  background-color: #888;\n  color: #fff;\n  cursor: default;\n}\n.yes-no-picker-label {\n  color: #777;\n}\n.yes-no-picker-label.yes-selected {\n  color: #000;\n}\n.yes-no-picker-label.no-selected {\n  color: #a00;\n  text-decoration: line-through;\n}</code>\n</property>\n<property>\n<name></name>\n</property>\n<property>\n<parse>0</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<content>{{velocity}}\n$xwiki.jsx.use('PhenoTips.YesNoNAPicker')##\n$xwiki.ssx.use('PhenoTips.YesNoNAPicker')##\n#set ($doDisplay = ($xcontext.action == 'edit' || "$!value" != ''))\n{{html clean=false wiki=false}}##\n#if ($xcontext.action == 'edit')&lt;span class="yes-no-picker"&gt;&lt;label class="na" title="$services.localization.render('phenotips.yesNoNAPicker.NA.title')"&gt;&lt;input type="checkbox" name="${prefix}${name}" value="" #if($value == '')checked="checked"#end /&gt;NA&lt;/label&gt;&lt;label class="yes" title="$services.localization.render('phenotips.yesNoNAPicker.yes.title')"&gt;&lt;input type="checkbox" name="${prefix}${name}" value="1" #if($value == '1')checked="checked"#end /&gt;Y&lt;/label&gt;&lt;label class="no" title="$services.localization.render('phenotips.yesNoNAPicker.no.title')"&gt;&lt;input type="checkbox" name="${prefix}${name}" value="0" #if($value == '0')checked="checked" #end/&gt;N&lt;/label&gt;&lt;/span&gt;#elseif ($value == '0')NO #{end}#if ($doDisplay)&lt;label class="yes-no-picker-label"&gt;$!object.xWikiClass.get($name).prettyName&lt;/label&gt;#end{{/html}}{{/velocity}}\n</content></xwikidoc>
