egmentFill = 100 * Math.min(Math.max((this.value - i * valueUnit) / valueUnit, 0), 1);\n        var segment = new Element('span', {\n          'class': 'segmented-unit'\n        });\n        var segmentFillElement =  new Element('span', {\n          'class': 'segmented-unit-fill'\n        });\n        segmentFillElement.setStyle({\n          width: segmentFill + '%',\n        });\n        segment.insert(segmentFillElement);\n        bar.insert(segment);\n      }\n      if(this.options.displayValue){\n        bar.insert(' ' + Math.round(this.value * 100) + '%');\n      }\n      return bar;\n    }\n  });\n  return PhenoTips;\n})(PhenoTips || {});</code>\n</property>\n<property>\n<name>Segmented Bar</name>\n</property>\n<property>\n<parse>0</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.StyleSheetExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<contentType>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>contentType</name>\n<number>6</number>\n<pr