nfo span.legend {\n  font-weight: normal;\n}\n\nul.suggestList {\n  margin:0px !important;\n  text-transform:none;\n  color: #333;\n  font-weight:normal;\n  padding: 0;\n}\n\nul.suggestList li{\n  padding: 4px;\n  border-top: 1px dotted #777;\n}\nul.suggestList li:first-child{\n  border-top: 0 none;\n}\nul.suggestList .xhighlight {\n  background-color: $theme.highlightColor;\n  cursor:pointer;\n}\n\ndiv.suggestItemName {\n  text-indent: 0;\n}\n\ndiv.suggestItem, li.noSuggestion div {\n  color: #333;\n  font-size: 0.875em;\n}\n\ndiv.suggestItemName,\ndiv.suggestItemInfo {\n  text-decoration: inherit;\n}\n\n.highlight {\n  background-color: $theme.highlightColor;\n  color: #000;\n  font-weight:bold;\n  text-decoration: inherit;\n}\n\ndiv.resultContainer div.sourceName {\n  background-color: #DDD;\n  font-variant: small-caps;\n  font-weight: 700;\n  color: #333;\n  padding-top:3px;\n  font-size:0.875em;\n  background-position:3px 3px;\n  background-repeat:no-repeat;\n}\n\n.horizontalLayout div.resultContainer div.sourceName {\n  float:left;\n  width:150px;\n  margin-right:3px;\n  padding-right:20px;\n  text-align:right;\n  background-position:right center;\n}\n\n.horizontalLayout div.resultContainer div.xitemcontainer {\n  margin-left:10px;\n}\n\n.horizontalLayout div.resultContainer div.results {\n  clear:both;\n  background-color: #DDD;\n}\n\n.horizontalLayout div.resultContainer ul.suggestList {\n  background-color:white;\n}\n\ndiv.resultContainer div.sourceContent.loading {\n  background-position:center center;\n  min-height:30px;\n}\n\n.suggestId:before {\n  content: "[";\n}\n.suggestId:after {\n  content: "] ";\n}\n.suggestId {\n  font-size: 87%;\n}\n.suggestInfo {\n  font-size: 100%;\n  word-wrap: normal !important;\n  display: inline-block;\n  width: 100%;\n  float: right;\n  line-height:1.2em !important;\n}\n.suggestInfo dl {\n  display: inline;\n}\n.suggestInfo dt {\n  font-style: italic;\n}\n\n.suggestInfo dt, .suggestInfo dd {\n  margin-left: 1.2em;\n  posi