/classType>\n</use>\n</class>\n<name>XWiki.DateTimePicker</name>\n<number>5</number>\n<className>XWiki.JavaScriptExtension</className>\n<guid>3c2e2312-63bb-4599-bbec-ed37ae4ba254</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>/**\n * Copyright 2007 Tim Down.\n * \n * Licensed under the Apache License, Version 2.0 (the "License");\n * you may not use this file except in compliance with the License.\n * You may obtain a copy of the License at\n * \n *      http://www.apache.org/licenses/LICENSE-2.0\n * \n * Unless required by applicable law or agreed to in writing, software\n * distributed under the License is distributed on an "AS IS" BASIS,\n * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n * See the License for the specific language governing permissions and\n * limitations under the License.\n */\n \n/**\n * simpledateformat.js\n *\n * A faithful JavaScript implementation of Java's SimpleDateFormat's format\n * method. All pattern layouts present in the Java implementation are\n * implemented here except for z, the text version of the date's time zone.\n *\n * Thanks to Ash Searle (http://hexmen.com/blog/) for his fix to my\n * misinterpretation of pattern letters h and k.\n * \n * See the official Sun documentation for the Java version:\n * http://java.sun.com/j2se/1.5.0/docs/api/java/text/SimpleDateFormat.html\n *\n * Author: Tim Down &lt;tim@timdown.co.uk&gt;\n * Last modified: 6/2/2007\n * Website: http://www.timdown.co.uk/code/simpledateformat.php\n */\n \n/* ------------------------------------------------------------------------- */\n\nvar SimpleDateFormat;\n\n(function() {\n\tfunction isUndefined(obj) {\n\t\treturn typeof obj == "undefined";\n\t}\n\n\tvar regex = /('[^']*')|(G+|y+|M+|w+|W+|D+|d+|F+|E+|a+|H+|k+|K+|h+|m+|s+|S+|Z+)|([a-zA-Z]+)|([^a-zA-Z']+)/;\n\tvar monthNames = Date.CultureInfo.monthNames;\n\tvar dayNames = Date.CultureInfo.dayNames;\n\tvar TEXT2 = 0, TEXT3 = 1, NUMBER = 2, YEAR = 3, MONTH = 4, TIMEZONE = 5;\n\tvar types = {\n\t\tG : TEXT2,\n\t\ty : YEAR,\n\t\tM : MONTH,\n\t\tw : NUMBER,\n\t\tW : NUMBER,\n\t\tD : NUMBER,\n\t\td : NUMBER,\n\t\tF : NUMBER,\n\t\tE : TEXT3,\n\t\ta : TEXT2,\n\t\tH : NUMBER,\n\t\tk : NUMBER,\n\t\tK : NUMBER,\n\t\th : NUMBER,\n\t\tm : NUMBER,\n\t\ts : NUMBER,\n\t\tS : NUMBER,\n\t\tZ : TIMEZONE\n\t};\n\tvar ONE_DAY = 24 * 60 * 60 * 1000;\n\tvar ONE_WEEK = 7 * ONE_DAY;\n\tvar DEFAULT_MINIMAL_DAYS_IN_FIRST_WEEK = 1;\n\n\tvar newDateAtMidnight = function(year, month, day) {\n\t\tvar d = new Date(year, month, day, 0, 0, 0);\n\t\td.setMilliseconds(0);\n\t\treturn d;\n\t}\n\n\tDate.prototype.getDifference = function(date) {\n\t\treturn this.getTime() - date.getTime();\n\t};\n\n\tDate.prototype.isBefore = function(d) {\n\t\treturn this.getTime() &lt; d.getTime();\n\t};\n\n\tDate.prototype.getUTCTime = function() {\n\t\treturn Date.UTC(this.getFullYear(), this.getMonth(), this.getDate(), this.getHours(), this.getMinutes(),\n\t\t\t\tthis.getSeconds(), this.getMilliseconds());\n\t};\n\n\tDate.prototype.getTimeSince = function(d) {\n\t\treturn this.getUTCTime() - d.getUTCTime();\n\t};\n\n\tDate.prototype.getPreviousSunday = function() {\n\t\t// Using midday avoids any possibility of DST messing things up\n\t\tvar midday = new Date(this.getFullYear(), this.getMonth(), this.getDate(), 12, 0, 0);\n\t\tvar previousSunday = new Date(midday.getTime() - this.getDay() * ONE_DAY);\n\t\treturn newDateAtMidnight(previousSunday.getFullYear(), previousSunday.getMonth(),\n\t\t\t\tpreviousSunday.getDate());\n\t}\n\n\tDate.prototype.getWeekInYear = function(minimalDaysInFirstWeek) {\n\t\tif (isUndefined(this.minimalDaysInFirstWeek)) {\n\t\t\tminimalDaysInFirstWeek = DEFAULT_MINIMAL_DAYS_IN_FIRST_WEEK;\n\t\t}\n\t\tvar previousSunday = this.getPreviousSunday();\n\t\tvar startOfYear = newDateAtMidnight(this.getFullYear(), 0, 1);\n\t\tvar numberOfSundays = previousSunday.isBefore(startOfYear) ?\n\t\t\t0 : 1 + Math.floor(previousSunday.getTimeSince(startOfYear) / ONE_WEEK);\n\t\tvar numberOfDaysInFirstWeek =  7 - startOfYear.getDay();\n\t\tvar weekInYear = numberOfSundays;\n\t\tif (numberOfDaysInFirstWeek &lt; minimalDaysInFirstWeek) {\n\t\t\tweekInYear--;\n\t\t}\n\t\treturn weekInYear;\n\t};\n\n\tDate.prototype.getWeekInMonth = function(minimalDaysInFirstWeek) {\n\t\tif (isUndefined(this.minimalDaysInFirstWeek)) {\n\t\t\tminimalDaysInFirstWeek = DEFAULT_MINIMAL_DAYS_IN_FIRST_WEEK;\n\t\t}\n\t\tvar previousSunday = this.getPreviousSunday();\n\t\tvar startOfMonth = newDateAtMidnight(this.getFullYear(), this.getMonth(), 1);\n\t\tvar numberOfSundays = previousSunday.isBefore(startOfMonth) ?\n\t\t\t0 : 1 + Math.floor((previousSunday.getTimeSince(startOfMonth)) / ONE_WEEK);\n\t\tvar numberOfDaysInFirstWeek =  7 - startOfMonth.getDay();\n\t\tvar weekInMonth = numberOfSundays;\n\t\tif (numberOfDaysInFirstWeek &gt;= minimalDaysInFirstWeek) {\n\t\t\tweekInMonth++;\n\t\t}\n\t\treturn weekInMonth;\n\t};\n\n\tDate.prototype.getDayInYear = function() {\n\t\tvar startOfYear = newDateAtMidnight(this.getFullYear(), 0, 1);\n\t\treturn 1 + Math.floor(this.getTimeSince(startOfYear) / ONE_DAY);\n\t};\n\n\t/* ----------------------------------------------------------------- */\n\n\tSimpleDateFormat = function(formatString) {\n\t\tthis.formatString = formatString;\n\t};\n\n\t/**\n\t * Sets the minimum number of days in a week in order for that week to\n\t * be considered as belonging to a particular month or year\n\t */\n\tSimpleDateFormat.prototype.setMinimalDaysInFirstWeek = function(days) {\n\t\tthis.minimalDaysInFirstWeek = days;\n\t};\n\n\tSimpleDateFormat.prototype.getMinimalDaysInFirstWeek = function(days) {\n\t\treturn isUndefined(this.minimalDaysInFirstWeek)\t?\n\t\t\tDEFAULT_MINIMAL_DAYS_IN_FIRST_WEEK : this.minimalDaysInFirstWeek;\n\t};\n\n\tSimpleDateFormat.prototype.format = function(date) {\n    if (date == "Invalid Date") {\n      return "";\n    }\n    var formattedString = "";\n\t\tvar result;\n\t\tvar padWithZeroes = function(str, len) {\n\t\t\twhile (str.length &lt; len) {\n\t\t\t\tstr = "0" + str;\n\t\t\t}\n\t\t\treturn str;\n\t\t};\n\n\t\tvar formatText = function(data, numberOfLetters, minLength) {\n\t\t\treturn (numberOfLetters &gt;= 4) ? data : data.substr(0, Math.max(minLength, numberOfLetters));\n\t\t};\n\n\t\tvar formatNumber = function(data, numberOfLetters) {\n\t\t\tvar dataString = "" + data;\n\t\t\t// Pad with 0s as necessary\n\t\t\treturn padWithZeroes(dataString, numberOfLetters);\n\t\t};\n\n\t\tvar searchString = this.formatString;\n\t\twhile ((result = regex.exec(searchString))) {\n\t\t\tvar matchedString = result[0];\n\t\t\tvar quotedString = result[1];\n\t\t\tvar patternLetters = result[2];\n\t\t\tvar otherLetters = result[3];\n\t\t\tvar otherCharacters = result[4];\n\n\t\t\t// If the pattern matched is quoted string, output the text between the quotes\n\t\t\tif (quotedString) {\n\t\t\t\tif (quotedString == "''") {\n\t\t\t\t\tformattedString += "'";\n\t\t\t\t} else {\n\t\t\t\t\tformattedString += quotedString.substring(1, quotedString.length - 1);\n\t\t\t\t}\n\t\t\t} else if (otherLetters) {\n\t\t\t\t// Swallow non-pattern letters by doing nothing here\n\t\t\t} else if (otherCharacters) {\n\t\t\t\t// Simply output other characters\n\t\t\t\tformattedString += otherCharacters;\n\t\t\t} else if (patternLetters) {\n\t\t\t\t// Replace pattern letters\n\t\t\t\tvar patternLetter = patternLetters.charAt(0);\n\t\t\t\tvar numberOfLetters = patternLetters.length;\n\t\t\t\tvar rawData = "";\n\t\t\t\tswitch (patternLetter) {\n\t\t\t\t\tcase "G":\n\t\t\t\t\t\trawData = "AD";\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "y":\n\t\t\t\t\t\trawData = date.getFullYear();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "M":\n\t\t\t\t\t\trawData = date.getMonth();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "w":\n\t\t\t\t\t\trawData = date.getWeekInYear(this.getMinimalDaysInFirstWeek());\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "W":\n\t\t\t\t\t\trawData = date.getWeekInMonth(this.getMinimalDaysInFirstWeek());\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "D":\n\t\t\t\t\t\trawData = date.getDayInYear();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "d":\n\t\t\t\t\t\trawData = date.getDate();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "F":\n\t\t\t\t\t\trawData = 1 + Math.floor((date.getDate() - 1) / 7);\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "E":\n\t\t\t\t\t\trawData = dayNames[date.getDay()];\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "a":\n\t\t\t\t\t\trawData = (date.getHours() &gt;= 12) ? "PM" : "AM";\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "H":\n\t\t\t\t\t\trawData = date.getHours();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "k":\n\t\t\t\t\t\trawData = date.getHours() || 24;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "K":\n\t\t\t\t\t\trawData = date.getHours() % 12;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "h":\n\t\t\t\t\t\trawData = (date.getHours() % 12) || 12;\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "m":\n\t\t\t\t\t\trawData = date.getMinutes();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "s":\n\t\t\t\t\t\trawData = date.getSeconds();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "S":\n\t\t\t\t\t\trawData = date.getMilliseconds();\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase "Z":\n\t\t\t\t\t\trawData = date.getTimezoneOffset(); // This is returns the number of minutes since GMT was this time.\n\t\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t\t// Format the raw data depending on the type\n\t\t\t\tswitch (types[patternLetter]) {\n\t\t\t\t\tcase TEXT2:\n\t\t\t\t\t\tformattedString += formatText(rawData, numberOfLetters, 2);\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase TEXT3:\n\t\t\t\t\t\tformattedString += formatText(rawData, numberOfLetters, 3);\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase NUMBER:\n\t\t\t\t\t\tformattedString += formatNumber(rawData, numberOfLetters);\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase YEAR:\n\t\t\t\t\t\tif (numberOfLetters &lt;= 3) {\n\t\t\t\t\t\t\t// Output a 2-digit year\n\t\t\t\t\t\t\tvar dataString = "" + rawData;\n\t\t\t\t\t\t\tformattedString += dataString.substr(2, 2);\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tformattedString += formatNumber(rawData, numberOfLetters);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase MONTH:\n\t\t\t\t\t\tif (numberOfLetters &gt;= 3) {\n\t\t\t\t\t\t\tformattedString += formatText(monthNames[rawData], numberOfLetters, numberOfLetters);\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t// NB. Months returned by getMonth are zero-based\n\t\t\t\t\t\t\tformattedString += formatNumber(rawData + 1, numberOfLetters);\n\t\t\t\t\t\t}\n\t\t\t\t\t\tbreak;\n\t\t\t\t\tcase TIMEZONE:\n\t\t\t\t\t\tvar isPositive = (rawData &gt; 0);\n\t\t\t\t\t\t// The following line looks like a mistake but isn't\n\t\t\t\t\t\t// because of the way getTimezoneOffset measures.\n\t\t\t\t\t\tvar prefix = isPositive ? "-" : "+";\n\t\t\t\t\t\tvar absData = Math.abs(rawData);\n\n\t\t\t\t\t\t// Hours\n\t\t\t\t\t\tvar hours = "" + Math.floor(absData / 60);\n\t\t\t\t\t\thours = padWithZeroes(hours, 2);\n\t\t\t\t\t\t// Minutes\n\t\t\t\t\t\tvar minutes = "" + (absData % 60);\n\t\t\t\t\t\tminutes = padWithZeroes(minutes, 2);\n\n\t\t\t\t\t\tformattedString += prefix + hours + minutes;\n\t\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tsearchString = searchString.substr(result.index + result[0].length);\n\t\t}\n\t\treturn formattedString;\n\t};\n})();</code>\n</property>\n<property>\n<name>SimpleDateFormat</name>\n</property>\n<property>\n<parse>0</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.StyleSheetExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<contentType>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>contentType</name>\n<number>6</number>\n<prettyName>Content Type</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>CSS|LESS</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</contentType>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>XWiki.DateTimePicker</name>\n<number>0</number>\n<className>XWiki.StyleSheetExtension</className>\n<guid>ce37339d-1130-4b6a-94f4-f998389b5320</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>#template('colorThemeInit.vm')\ninput.xwiki-date {\n  background-image: url("$xwiki.getSkinFile('icons/silk/date.png')");\n  background-position: right center;\n  background-repeat: no-repeat;\n  min-height: 16px;\n  cursor: pointer;\n}\n.calendar_date_select {\n  color:$theme.textColor;\n  border: $theme.pageContentBackgroundColor 1px solid;\n  box-shadow: 0 0 6px $theme.borderColor;\n  display:block;\n  width:13.929em;\n  z-index: 1000;\n}\n/* this is a fun ie6 hack to get drop downs to stay behind the popup window.  This should always be just underneath .calendar_date_select */\niframe.ie6_blocker {\n  position: absolute;\n  z-index: 999;\n}\n\n.calendar_date_select thead th {\n  font-weight:bold;\n  background-color: $theme.panelHeaderBackgroundColor;\n  border-top:1px solid $theme.borderColor;\n  border-bottom:2px solid $theme.borderColor;\n  color: $theme.panelHeaderTextColor !important;\n  text-align:center;\n}\n\n.calendar_date_select .cds_part {\n  clear: left;\n}\n.calendar_date_select .cds_buttons {\n  text-align:center;\n  padding:0.357em 0;\n  background-color: $theme.backgroundSecondaryColor;\n}\n\n.calendar_date_select .cds_footer {\n  color: $theme.panelHeaderTextColor;\n  background-color: $theme.panelHeaderBackgroundColor;\n  padding:0.214em;\n  font-size:0.857em;\n  text-align:center;\n}\n\n.calendar_date_select table {\n  margin: 0;\n  padding: 0;\n}\n\n\n.calendar_date_select .cds_header {\n  background-color: $theme.backgroundSecondaryColor;\n  border-bottom:2px solid $theme.borderColor;\n  text-align:center;\n}\n\n.calendar_date_select .cds_header span {\n  font-size:1.071em;\n  color: $theme.textColor;\n  font-weight: bold;\n}\n\n.calendar_date_select select { font-size:0.786em;}\n\n.calendar_date_select .cds_header a:hover {\n  color: $theme.textColor;\n}\n.calendar_date_select .cds_header a {\n  width:1.571em;\n  height:1.429em;\n  text-decoration: none;\n  font-size:1em;\n  color:$theme.textColor !important;\n}\n\n.calendar_date_select .cds_header a.prev {\n  float:left;\n}\n.calendar_date_select .cds_header a.next {\n  float:right;\n}\n.calendar_date_select .cds_header a.close {\n  float:right;\n  display:none;\n}\n\n*html div.calendar_date_select .cds_header select.month {\n  width:5.714em;\n}\n\n.calendar_date_select .cds_buttons a {\n  color: $theme.textColor;\n  font-size:0.643em;\n}\n.calendar_date_select td {\n  cursor: pointer;\n  font-size:0.857em;\n  width: 1.714em;\n  height: 1.5em;\n  text-align:center;\n  vertical-align: middle;\n  background-color: $theme.pageContentBackgroundColor;\n}\n.calendar_date_select td.weekend {\n  background-color: $theme.backgroundSecondaryColor;\n}\n\n.calendar_date_select td div {\n  color: $theme.linkColor;\n}\n.calendar_date_select td div.other {\n  color: $theme.textSecondaryColor;\n}\n.calendar_date_select td.selected div {\n  color:$theme.textColor;\n  font-weight:bold;\n}\n\n.calendar_date_select .cds_body table {\n  cell-padding: 0;\n  cell-spacing: 0;\n  width: 100%;\n}\n\n.calendar_date_select tbody td {\n  border-bottom: 1px solid $theme.borderColor;\n}\n.calendar_date_select td.selected {\n  background-color: $theme.pageBackgroundColor;\n}\n\n.calendar_date_select td:hover {\n  background-color: $theme.highlightColor;\n}\n\n.calendar_date_select td.today {\n  border: 2px solid $theme.linkColor;\n}\n\n.calendar_date_select td.disabled div {\n  color: $theme.textSecondaryColor;\n}\n\n\n.fieldWithErrors .calendar_date_select {\n  border: 2px solid $theme.notificationWarningColor;\n}\n\n*html .calendar_date_select .cds_top, *html .calendar_date_select .cds_bottom {\n  display:none;\n}\n</code></property><property><name>Calendar styling</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.XWikiRights</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<default