sion</className>\n<guid>b3934e65-aa68-4fcb-8df4-875c955e2f93</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>#template("colorThemeInit.vm")\n\n#patient-record-actions {\n  float: right;\n  margin: 0;\n  position: absolute;\n  right: 0px;\n  top: 0;\n  z-index: 3000;\n}\n\n#patient-record-actions .menu.menu-horizontal {\n  border: 0 none;\n  font-size: 1em;\n  height: 1.833em;\n  padding: 0 0 0 10px;\n  text-shadow: none;\n}\n#patient-record-actions .menu.menu-horizontal a:hover {\n  text-decoration: none !important;\n  text-shadow: 0 0 2px $theme.highlightColor;\n}\n\n#patient-record-actions .menu-horizontal &gt; ul &gt; li {\n  padding: 0.2em 1.3em 0.2em 0.3em;\n}\n#patient-record-actions .menu-horizontal &gt; ul {\n  white-space: nowrap;\n}\n#patient-record-actions .menu-horizontal ul ul {\n  white-space: normal;\n}\n.menu-vertical li:empty, .menu-horizontal li li:empty {\n  min-height: 1px !important;\n}\n\n#patient-record-actions .menu-horizontal input {\n  background: transparent !important;\n  /* Buttons without a border in IE don't trigger the :hover state */\n  border: 1px solid transparent !important;\n  color: inherit !important;\n  margin: 0 !important;\n  padding: 0 !important;\n}\n#patient-record-actions .menu-horizontal label:hover, #patient-record-actions .menu-horizontal label:hover input {\n  cursor: pointer;\n  text-shadow: 0 0 2px $theme.highlightColor;\n}</code>\n</property>\n<property>\n<name></name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>currentPage</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.StyleSheetExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<contentType>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>contentType</name>\n<number>6</number>\n<prettyName>Content Type</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>CSS|LESS</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</contentType>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>PhenoTips.ContentTopMenu</name>\n<number>1</number>\n<className>XWiki.StyleSheetExtension</className>\n<guid>87c40da3-7d05-4feb-ad36-18d4a49376d3</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>#template('colorThemeInit.vm')\n\n/* General Styles */\n\n.menu-horizontal ul {\n  list-style-type: none;\n  margin: auto;\n}\n\n.menu-horizontal ul * {\n  line-height: normal;\n}\n\n.menu-horizontal li {\n  cursor: default;\n  line-height: 16px;\n  min-height: 16px;\n}\n\n.menu-horizontal img {\n  vertical-align: middle;\n}\n\n/* Horizontal separator */\n.menu-horizontal li li:empty {\n  border-top: 1px solid $theme.borderColor;\n  line-height: 1px;\n  min-height: auto;\n  padding: 0;\n}\n\n/* Horizontal Menu */\n\n.menu.menu-horizontal {\n  background-color: $theme.menuBackgroundColor;\n  #css3_backgroundLinearGradient({\n    'to': 'bottom',\n    'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n  color: $theme.menuLinkColor;\n  font-size: .85em;\n  height: 2em;\n  padding-left: 25px;\n}\n\n.menu-horizontal li {\n  padding: 0.2em 1.3em;\n}\n\n.menu-horizontal li li:empty {\n  border-top: 1px solid $theme.textSecondaryColor;\n  margin: .5em 1em;\n}\n\n/* Vertical separator */\n.menu-horizontal &gt; ul &gt; li:empty {\n  border-left: 1px solid $theme.textSecondaryColor;\n  margin: 0 .5em;\n  padding: 0;\n  vertical-align: middle;\n}\n\n.menu-horizontal li a, .menu-horizontal li a:visited {\n  color: inherit;\n}\n\n.menu-horizontal &gt; ul &gt; li {\n  display: inline-block;\n}\n\n.menu-horizontal &gt; ul &gt; li &gt; .xDropdown:after {\n  content: '\\25BC';\n  font-size: .8em;\n  margin-left: .5em;\n}\n\n.menu-horizontal &gt; ul ul {\n  background: none repeat scroll 0 0 $theme.menuBackgroundColor;\n  border-radius: 0 0 .8em .8em;\n  box-shadow: 0 1px 1px $theme.borderColor;\n  display: none;\n  margin: 0.2em 0 0 -1.3em;\n  padding-bottom: .3em;\n  position: absolute;\n  z-index: 1000;\n}\n\n.menu-horizontal li:hover &gt; ul {\n  display: block;\n}\n\n/* The only way to have a menu with more than 2 levels without JavaScript is to use a fixed width. */\n.menu-horizontal.fixedWidth li li {\n  position: relative;\n}\n\n.menu-horizontal.fixedWidth ul ul {\n  width: 12em;\n}\n\n.menu-horizontal.fixedWidth ul ul ul {\n  left: 12em;\n  margin: 0;\n  top: 0;\n}\n</code></property><property><name>Menu styles</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.UIExtensionClass</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<content>\n<disabled>0</disabled>\n<name>content</name>\n<number>3</number>\n<prettyName>Extension Content</prettyName>\n<rows>10</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</content>\n<extensionPointId>\n<disabled>0</disabled>\n<name>extensionPointId</name>\n<number>1</number>\n<prettyName>Extension Point ID</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</extensionPointId>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>2</number>\n<prettyName>Extension ID</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parameters>\n<disabled>0</disabled>\n<name>parameters</name>\n<number>4</number>\n<prettyName>Extension Parameters</prettyName>\n<rows>10</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</parameters>\n<scope>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>scope</name>\n<number>5</number>\n<prettyName>Extension Scope</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>wiki=Current Wiki|user=Current User|global=Global</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</scope>\n</class>\n<name>PhenoTips.ContentTopMenu</name>\n<number>0</number>\n<className>XWiki.UIExtensionClass</className>\n<guid>9449621f-d20d-42a1-bc70-18096cd6be2a</guid>\n<property>\n<content>{{velocity}}\n#macro (__icon $name){{html clean="false"}}&lt;span class="fa fa-fw fa-${name}"&gt; &lt;/span&gt;{{/html}}#end\n#if ($doc.getObject('PhenoTips.PatientClass'))\n#set ($colorTheme = $xwiki.getUserPreference('colorTheme'))\n#if ("$!colorTheme" != '')\n  ## Make sure we use an absolute reference (see XWIKI-9672)\n  #set ($colorTheme = $services.model.resolveDocument($colorTheme, $doc.documentReference))\n#end\n$xwiki.ssx.use('PhenoTips.ContentTopMenu', {'colorTheme': $colorTheme})##\n$xwiki.jsx.use('PhenoTips.ContentTopMenu')##\n(% id="patient-record-actions" %)(((\n(% id="pr-more-actions-menu" class="menu menu-horizontal" %)(((\n#if ($xcontext.action == 'view')\n#if($hasEdit &amp;&amp; !$isReadOnly)\n  #set($editaction = $doc.getDefaultEditMode())\n* [[#__icon("pencil")$services.localization.render('core.menu.edit')&gt;&gt;path:$doc.getURL($editaction, $!languageparams)|| id="prActionEdit"]]\n#end## HAS EDIT\n#set ($canDelete = !$doc.isNew() &amp;&amp; $xwiki.hasAccessLevel('delete'))\n#if ($canDelete)\n* [[#__icon("times")$services.localization.render('core.menu.delete')&gt;&gt;path:$doc.getURL('delete', $!languageparams)|| id="prActionDelete"]]\n#end## HAS DELETE\n#else## NOT IN VIEW MODE, SHOW EDIT MODE ACTIONS\n* (% class="xDropdown" %){{html clean="false"}}&lt;span class="fa fa-fw fa-check"&gt; &lt;/span&gt;&lt;label&gt;&lt;input type="submit" value="$services.localization.render('phenotips.contentTopMenu.save')" name="action_saveandcontinue"/&gt;&lt;/label&gt;{{/html}}\n** {{html clean="false"}}&lt;label&gt;&lt;input id="tmActionSave" type="submit" value="$services.localization.render('saveandcontinue')" title="$services.localization.render('saveandcontinue')" name="action_saveandcontinue"/&gt;&lt;/label&gt;{{/html}}\n** {{html clean="false"}}&lt;label&gt;&lt;input id="tmActionSaveAndContinue" type="submit" value="$services.localization.render('saveandview')" title="$services.localization.render('saveandview')" name="action_save"/&gt;&lt;/label&gt;{{/html}}\n* {{html clean="false"}}&lt;span class="fa fa-fw fa-ban"&gt; &lt;/span&gt;&lt;label&gt;&lt;input id="tmActionCancel" type="submit" value="$services.localization.render('phenotips.contentTopMenu.cancel')" title="$services.localization.render('phenotips.contentTopMenu.cancel.title')" name="action_cancel"/&gt;&lt;/label&gt;{{/html}}\n#end## DONE WITH EDIT MODE SPECIFIC ACTIONS\n* (% class="xDropdown" %){{html clean="false"}}&lt;span class="fa fa-fw fa-list"&gt; &lt;/span&gt;&lt;span id="toc-entry"&gt;$services.localization.render('phenotips.contentTopMenu.jumpMenu')&lt;/span&gt;{{/html}}\n##The ToC will be populated by JS\n** ----\n* (% class="xDropdown" %)#__icon("cog") $services.localization.render('phenotips.contentTopMenu.moreActionsMenu')\n#if ($xcontext.action != 'view' || $viewer != 'content')\n** [[$services.localization.render('phenotips.contentTopMenu.moreActionsMenu.viewMode')&gt;&gt;$doc.fullName|| title="$services.localization.render('phenotips.contentTopMenu.moreActionsMenu.viewMode.title')" target="_blank"]]\n#end\n#if ($isAdvancedUser &amp;&amp; $xcontext.action != 'view' || $viewer != 'history')\n** [[$services.localization.render('phenotips.contentTopMenu.moreActionsMenu.history')&gt;&gt;path:$doc.getURL('view', 'viewer=history')|| target="_blank" title="$services.localization.render('phenot