n  #set ($discard = $contents.put($s.id, $s.content))\n#end\n#set ($crtContent = '')\n#if ($menu.size() &gt; 0)\n  #set ($crtItem = "$!request.s")\n  #if ("$!contents.get($crtItem)" == '')\n    #set ($crtItem = "$!menu.get(0).id")\n  #end\n  #set ($crtContent = "$!contents.get($crtItem)")\n#end\n#if ($menu.size() &gt; 1)\n(% class="vertical-menu $!{options.cssClass}" %)(((\n#foreach ($i in $menu)\n* {{html clean=false wiki=false}}&lt;a href="$i.url" id="group-section-$i.id" #if ($i.id == $crtItem) class="current" #end&gt;$i.name&lt;/a&gt;{{/html}}\n#end\n)))\n(% class="menu-section" id="content-${crtItem}" %)#end((($crtContent)))\n#end\n#end\n{{/velocity}}</content></xwikidoc>\n
