onfigurationClass', 'property', 'study-visibility-option', false).getProperty('value').value)\n#if ($studiesVisibilityPreference == 'unrestricted')\n  #set ($studyClassName = 'PhenoTips.StudyClass')\n  #set ($studyTemplateName = 'PhenoTips.StudyTemplate')\n  #set ($query = $services.query.xwql("from doc.object(${studyClassName}) as std where doc.fullName &lt;&gt; :template").bindValue('template', $studyTemplateName))\n  #set ($studyDocs = $xwiki.wrapDocs($query.execute()))\n  #set ($studies = $collectionstool.sortedSet)\n  #foreach ($study in $studyDocs)\n    #set ($discard = $studies.add($services.model.serialize($study.documentReference, 'default')))\n  #end\n#else\n  #set ($toProcess = $collectionstool.queue)\n  #set ($discard = $toProcess.add($xcontext.userReference.toString()))\n  #set ($groups = [])\n  #set ($studies = $collectionstool.sortedSet)\n  #foreach ($iteration in [0..1000])\n    #if ($toProcess.empty)\n      #break\n    #end\n    #set ($item = $toProcess.poll())\n    #foreach ($group in $xwiki.wrapDocs($xwiki.rightsmanager.getAllGroupsNamesForMember($item)))\n      #set ($groupObj = $group.getObject('PhenoTips.PhenoTipsGroupClass'))\n      #if (!$groupObj &amp;&amp; $group.documentReference.name.endsWith(' Administrators'))\n        #set ($groupObj = $xwiki.getDocument($services.model.resolveDocument($stringtool.removeEnd($group.documentReference.name, ' Administrators'), $group.documentReference.parent)).getObject('PhenoTips.PhenoTipsGroupClass'))\n      #end\n      #if ($groupObj &amp;&amp; !$groups.contains($group.documentReference.toString()))\n        #set ($discard = $toProcess.add($group.documentReference.toString()))\n        #set ($discard = $groups.add($escapetool.sql($group.documentReference.toString())))\n        #if ($groupObj.getProperty('studies').value.isEmpty() == false)\n          #set ($discard = $studies.addAll($groupObj.getProperty('studies').value))\n        #end\n      #end\n    #end\n  #end\n#end\n#if ($studies.size() &gt; 0)\n  #set ($studyConfig = $doc.getObject($className, true))\n  #set ($value = $studyConfig.getProperty('studyReference').value)\n  #if ("$!value" == '')\n    #set($displayedValue = '(% class="hint" %)None(%%)')\n  #else\n    #set ($s = $xwiki.getDocument($value))\n    #set ($config = $s.getObject('PhenoTips.StudyClass'))\n    #set ($configTitle = '')\n    #if ("$!{s.plainTitle}" != '')\n      #set ($configTitle = "$s.plainTitle")\n    #else\n      #set ($configTitle = "${s.name}")\n    #end\n    #set($displayedValue = "(% class='buttonwrapper' %)[[{{icon name='copy' /}} ${services.rendering.escape($configTitle, $doc.syntax)}&gt;&gt;${services.rendering.escape($value, $doc.syntax)}||rel='__blank' class='button secondary']]")\n  #end\n  #set ($faction = $doc.getURL('save', "form_token=${services.csrf.token}&amp;objectPolicy=updateOrCreate&amp;xredirect=$escapetool.url($doc.getURL($xcontext.action))"))\n(% class="study-assignment-config" %)(((Study: $displayedValue (% class="buttonwrapper" %)[[ {{icon name="edit" title="$services.localization.render('phenotips.studyBindingClass.changeStudyButton.title')" /}} {{html clean=false}}&lt;input type="hidden" name="faction" value="$faction"/&gt;{{/html}}&gt;&gt;path:$doc.getURL('get', "sheet=$!{sheetName}&amp;faction=$!{escapetool.url($faction)}")||class="button" rel="__blank" id="study-assignment-config" class="$xcontext.action"]])))\n#end\n{{/velocity}}</content>\n</property>\n<property>\n<extensionPointId>org.phenotips.patientSheet.before</extensionPointId>\n</property>\n<property>\n<name>org.phenotips.patientSheet.study</name>\n</property>\n<property>\n<parameters></parameters>\n</property>\n<property>\n<scope>wiki</scope>\n</property>\n</object>\n<content>{{velocity output=false}}\n#if ("$!mode" == '' || "$!mode" == 'get')\n  #set ($mode = 'edit')\n#end\n#if ("$!name" == '')\n  #set ($name = 'studyReference')\n#end\n#if ("$!prefix" == '')\n  #set ($prefix = 'PhenoTips.StudyBindingClass_')\n#end\n#if ("$!value" == '')\n  #set ($value = '')\n#end\n{{/velocity}}\n\n{{velocity}}{{html clean="false" wiki="true"}}\n#if ($mode == 'edit')\n#set ($studiesVisibilityPreference = $xwiki.getDocument('XWiki.XWikiPreferences').getObject('XWiki.ConfigurationClass', 'property', 'study-visibility-option', false).getProperty('value').value)\n#if ($studiesVisibilityPreference == 'unrestricted')\n  #set ($studyClassName = 'PhenoTips.StudyClass')\n  #set ($studyTemplateName = 'PhenoTips.StudyTemplate')\n  #set ($query = $services.query.xwql("from doc.object(${studyClassName}) as std where doc.fullName &lt;&gt; :template").bindValue('template', $studyTemplateName))\n  #set ($studyDocs = $xwiki.wrapDocs($query.execute()))\n  #set ($studies = $collectionstool.sortedSet)\n  #foreach ($study in $studyDocs)\n    #set ($discard = $studies.add($services.model.serialize($study.documentReference, 'default')))\n  #end\n#else\n  #set ($toProcess = $collectionstool.queue)\n  #set ($discard = $toProcess.add($xcontext.userReference.toString()))\n  #set ($groups = [])\n  #set ($studies = $collectionstool.sortedSet)\n  #foreach ($iteration in [0..1000])\n    #if ($toProcess.empty)\n      #break\n    #end\n    #set ($item = $toProcess.poll())\n    #foreach ($group in $xwiki.wrapDocs($xwiki.rightsmanager.getAllGroupsNamesForMember($item)))\n      #set ($groupObj = $group.getObject('PhenoTips.PhenoTipsGroupClass'))\n      #if (!$groupObj &amp;&amp; $group.documentReference.name.endsWith(' Administrators'))\n        #set ($groupObj = $xwiki.getDocument($services.model.resolveDocument($stringtool.removeEnd($group.documentReference.name, ' Administrators'), $group.documentReference.parent)).getObject('PhenoTips.PhenoTipsGroupClass'))\n      #end\n      #if ($groupObj &amp;&amp; !$groups.contains($group.documentReference.toString()))\n        #set ($discard = $toProcess.add($group.documentReference.toString()))\n        #set ($discard = $groups.add($escapetool.sql($group.documentReference.toString())))\n        #if ($groupObj.getProperty('studies').value.isEmpty() == false)\n          #set ($discard = $studies.addAll($groupObj.getProperty('studies').value))\n        #end\n      #end\n    #end\n  #end\n#end\n&lt;div class="form-template-option"&gt;\n&lt;label&gt;&lt;input type="radio" name="${prefix}${name}" value=""#if ("$!{value}" == '') checked="checked"#end/&gt;$services.localization.render('phenotips.studyBindingClass.noStudyOption')&lt;/label&gt;\n&lt;p class="xHint"&gt;$services.localization.render('phenotips.studyBindingClass.noStudyOption.hint')&lt;/p&gt;\n&lt;/div&gt;\n#foreach ($sName in $studies)\n  #set ($s = $xwiki.getDocument($sName))\n  #if (!$s.isNew())\n    #set ($config = $s.getObject('PhenoTips.StudyClass'))\n    #set ($configTitle = '')\n    #if ("$!{s.plainTitle}" != '')\n      #set ($configTitle = "$s.plainTitle")\n    #else\n      #set ($configTitle = "${s.name}")\n    #end\n    &lt;div class="form-template-option"&gt;\n    &lt;label&gt;&lt;input type="radio" name="${prefix}${name}" value="${services.rendering.escape($services.model.serialize($s.documentReference), $doc.syntax)}" #if ("$!{value}" == "${s.documentReference}") checked="checked" #end/&gt;$services.rendering.escape($configTitle, $doc.syntax)&lt;/label&gt;\n    &lt;p class="xHint"&gt;$!{s.content}&lt;/p&gt;\n    &lt;/div&gt;\n  #end\n#end\n#else\n  #if ("$!value" == '')\n    None\n  #else\n    #set ($s = $xwiki.getDocument($value))\n    #set ($config = $s.getObject('PhenoTips.StudyClass'))\n    #set ($configTitle = '')\n    #if ("$!{s.plainTitle}" != '')\n      #set ($configTitle = "$s.plainTitle")\n    #else\n      #set ($configTitle = "${s.name}")\n    #end\n    [[${configTitle}&gt;&gt;${value}]]\n  #end\n#end\n{{/html}}{{/velocity}}\n</content></xwikidoc>
