: function() {\n      this.valid = true;\n    },\n    available : function() {\n      this.valid = true;\n    },\n    empty : function() {\n      this.valid = false;\n    },\n    exists : function() {\n      this.valid = false;\n    },\n    responded : function() {\n      this.state = 'DONE';\n      this.input.__validation.validate();\n    }\n  });\n\n  var init = function(event) {\n    ((event &amp;&amp; event.memo.elements) || [$('body')]).each(function(element) {\n      element.select('input.check-unique, .external_id input').each(function(input) {\n        if (!input.__uniqueness_validator) {\n          input.__uniqueness_validator = new XWiki.widgets.UniquenessValidator(input);\n        }\n      });\n    });\n    return true;\n  };\n\n  (XWiki.domIsLoaded &amp;&amp; init()) || document.observe("xwiki:dom:loaded", init);\n  document.observe('xwiki:dom:updated', init);\n\n  // End XWiki augmentation.\n  return XWiki;\n}(XWiki || {}));</code>\n</property>\n<property>\n<name>ID uniqueness validation</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<row