{{velocity}}\n#set ($searchEnginePropertyClass = $searchConfigClass.engine)\n#set ($availableSearchExtensions = $services.uix.getExtensions('org.xwiki.platform.search', {'sortById' : ''}))\n{{html wiki='true'}}\n&lt;form id='search_XWiki.SearchConfig' method='post' action="${searchConfigDoc.getURL('save')}" class='xform half'&gt;\n  &lt;dl&gt;\n    &lt;dt&gt;\n      &lt;input type='hidden' name='form_token' value="$!{services.csrf.getToken()}" /&gt;\n      &lt;input type='hidden' name='xredirect' value="$doc.getURL($xcontext.action, $!{request.queryString})" /&gt;\n    &lt;/dt&gt;\n\n    &lt;dt&gt;\n      &lt;label&gt;$searchEnginePropertyClass.translatedPrettyName&lt;/label&gt;\n      &lt;span class='xHint'&gt;$services.localization.render('search.admin.configuration.seexwikicfg')&lt;/span&gt;\n    &lt;/dt&gt;\n    &lt;dd&gt;\n      &lt;select name='XWiki.SearchConfigClass_0_engine'&gt;\n      #foreach ($availableSearchExtension in $availableSearchExtensions)\n        &lt;option value="$availableSearchExtension.id" #if($availableSearchExtension.id == $searchEngine)selected='selected'#end&gt;$availableSearchExtension.parameters.label&lt;/option&gt;\n      #end\n      &lt;/select&gt;\n    &lt;/dd&gt;\n\n    &lt;dt&gt;\n      &lt;span class='buttonwrapper'&gt;\n        &lt;input value="$services.localization.render('search.admin.configuration.button')" class='button' type='submit'&gt;\n      &lt;/span&gt;\n    &lt;/dt&gt;\n  &lt;/dl&gt;\n&lt;/form&gt;\n{{/html}}\n\n## If no Search UI Extension exist then don't display the Search Admin section.\n#if ("$!searchAdminPage" != '')\n  #set ($searchAdminDoc = $xwiki.getDocument($searchAdminPage))\n  ## If the document doesn't exist don't display it either.\n  #if (!$searchAdminDoc.isNew())\n    = $searchAdminDoc.displayTitle =\n\n    ## Use context='new' in the include so that we can use PR.\n    {{include reference="$searchAdminPage" context='new'}}\n  #end\n#end\n{{/velocity}}</content></xwikidoc>\n
