7862198511921928654	1	1	2017-05-12 15:43:35	Install extension [org.xwiki.platform:xwiki-platform-search-ui-7.1.2]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>XWiki</web>\n<name>Results</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>Main.WebSearch</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1252454400000</creationDate>\n<date>1494618215000</date>\n<contentUpdateDate>1494618215000</contentUpdateDate>\n<version>1.1</version>\n<title>$services.localization.render("search.page.results")</title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.xwiki.platform:xwiki-platform-search-ui-7.1.2]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.0</syntaxId>\n<hidden>true</hidden>\n<content>{{velocity}}\n{{html}}\n#set($showdata = 0)\n&lt;div id="searchResults"&gt;\n  #foreach ($item in $list)\n    #set($itemClass = "$item.class")\n    #set($itemfullname = "${xcontext.database}:${item}")\n    #if ($xwiki.hasAccessLevel('view', $xcontext.user, $itemfullname))\n      &lt;div class="resultItem"&gt;\n      &lt;div class="resultContainer"&gt;\n      #set($itemDoc = $xwiki.getDocument($item))\n      #set($author = $xwiki.getUserName($itemDoc.author))\n      ##*********************************************************##\n      ## Description                                             ##\n      ##*********************************************************##\n      &lt;div class="itemDescription type-${item.type}"&gt;\n        ##*********************************************************##\n        ## Title                                                   ##\n        ##*********************************************************##\n        &lt;h2 class="itemTitle"&gt;\n          &lt;a href="$xwiki.getURL($itemfullname)"&gt;$escapetool.xml($itemDoc.plainTitle)&lt;/a&gt;\n        &lt;/h2&gt;\n        ##*********************************************************##\n        ## Location                                                ##\n        ##*********************************************************##\n        &lt;div class="itemLocation"&gt;\n          $services.localization.render('search.item.location', [\n          $escapetool.xml($itemDoc.wiki), $xwiki.getURL("${itemDoc.wiki}:Main.WebHome"),\n          $escapetool.xml($itemDoc.space), $xwiki.getURL("${itemDoc.wiki}:${itemDoc.space}.WebHome"),\n          $escapetool.xml($itemDoc.name), $xwiki.getURL($itemfullname)])\n        &lt;/div&gt;\n        ##*********************************************************##\n        ## Modifiers - content update date                         ##\n        ##*********************************************************##\n        &lt;div class="itemModified"&gt;\n          #if ($author == 'XWikiGuest')\n            #set($author = $services.localization.render('search.page.results.guest'))\n          #end\n          $services.localization.render('search.item.modified', [$author, $xwiki.formatDate($itemDoc.date, 'dd MMM yyyy')])\n        &lt;/div&gt;\n## TODO: Uncomment when the attachment and comment count will be implemented\n##         &lt;div class="itemOthers"&gt;\n          ##*********************************************************##\n          ## Rating                                                  ##\n          ##*********************************************************##\n          #if($xwiki.ratings &amp;&amp; $item.type != 'attachment')\n            #set($avarageRating = $xwiki.ratings.getAverageRating($xwiki.getDocument($itemfullname)).averageVote)\n            #set($percentageRating = $avarageRating * 20)\n            &lt;span class="itemRating" title="$services.localization.render('search.item.rating.title')"&gt;\n              &lt;span class="currentRating" style="width:$percentageRating%;"&gt;&lt;/span&gt;\n            &lt;/span&gt;\n          #end\n##         &lt;/div&gt;\n      &lt;/div&gt; ## end &lt;div class="itemDescription"&gt;\n      #if ($isScored)\n        #set ($resval = $mathtool.min($mathtool.mul($itemDoc.score, 100), 100))\n        ##*********************************************************##\n        ## Relevance                                               ##\n        ##*********************************************************##\n        &lt;div class="itemRelevance"&gt;\n          &lt;span class="relevance" title="$services.localization.render('search.item.relevance.title')"&gt;\n            &lt;span class="currentRelevance" style="width:${resval}%;"&gt;&lt;/span&gt;\n          &lt;/span&gt;\n          &lt;span class="relevanceText"&gt;$resval.intValue()%&lt;/span&gt;\n        &lt;/div&gt;\n      #end ## isScored\n      ##*********************************************************##\n      ## Actions (admins only)                                   ##\n      ##*********************************************************##\n#*\n      #if($xwiki.hasAdminRights())\n          #set($copyURL = $xwiki.getURL('XWiki.CopyDocument', 'view', "sourcedoc=${escapetool.url($itemfullname)}"))\n          #set($deleteURL = $xwiki.getDocument($itemfullname).getURL('delete'))\n          #set($renameURL = $xwiki.getDocument($itemfullname).getURL('view', 'xpage=rename&amp;amp;step=1'))\n          #set($rightsURL = $xwiki.getDocument($itemfullname).getURL('edit', 'editor=rights'))\n          &lt;div class="itemActions"&gt;\n            &lt;a href="$copyURL" class="tool copy" title="$services.localization.render('search.page.results.copy')"&gt;$services.localization.render('search.page.results.copy')&lt;/a&gt;\n            &lt;a href='$renameURL' class="tool rename" title="$services.localization.render('search.page.results.rename')"&gt;$services.localization.render('search.page.results.rename')&lt;/a&gt;\n            &lt;a href="$deleteURL" class="tool delete" title="$services.localization.render('search.page.results.delete')"&gt;$services.localization.render('search.page.results.delete')&lt;/a&gt;\n            &lt;a href='$rightsURL' class="tool rights" title="$services.localization.render('search.page.results.rights')"&gt;$services.localization.render('search.page.results.rights')&lt;/a&gt;\n          &lt;/div&gt; ## itemActions\n        #end ## has admin rights *# ##\n      &lt;/div&gt; ## resultContainer\n      &lt;/div&gt; ## resultItem\n    #end ## hasAccessLevel\n  #end ## foreach item\n&lt;/div&gt; ## searchResults\n{{/html}}\n{{/velocity}}</content></xwikidoc>\n
