   } else {\n      var form_token = $$('meta[name=form_token]')[0].content;\n      new XWiki.widgets.ConfirmedAjaxRequest(\n        /* Ajax request URL */\n        item.readAttribute('href') + "?confirm=1&amp;form_token=" + form_token + (Prototype.Browser.Opera ? "" : "&amp;ajax=1"),\n        /* Ajax request parameters */\n        {\n          onCreate : function() {\n            // Disable the button, to avoid a cascade of clicks from impatient users\n            item.disabled = true;\n          },\n          onSuccess : function() {\n            // Refresh the table after deleting the row\n            var table = tableEvent.memo.table;\n            table.clearCache();\n            table.showRows(table.lastOffset, table.limit);\n          },\n          onFailure : function() {\n            // Better luck next time!\n            item.disabled = false;\n          }\n        },\n        /* Interaction parameters */\n        {\n          confirmationText: "$services.localization.render('core.delete.confirm')"\n        }\n      );\n    }\n  });\n});</code>\n</property>\n<property>\n<name>Confirmed AJAX deletion</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache