;input id="${targetDocName}title" name="title" size="30" type="text" value="$!escapetool.xml($targetDoc.title)"&gt;&lt;/input&gt;&lt;/dd&gt;\n&lt;dt&gt;&lt;label for="${fullPrefix}title"&gt;$services.localization.render('phenotips.navigation.webHome.welcomeMessage.label')&lt;/label&gt;&lt;/dt&gt;\n&lt;dd&gt;&lt;input id="${fullPrefix}title" name="${prefix}title" size="30" type="text" value="$!escapetool.xml($gadgetObj.getProperty('title').value)"&gt;&lt;/input&gt;&lt;/dd&gt;\n&lt;dt&gt;&lt;label for="${fullPrefix}content"&gt;$services.localization.render('phenotips.navigation.webHome.welcomeMessageContent.label')&lt;/label&gt;&lt;/dt&gt;\n&lt;dd&gt;&lt;textarea cols="40" id="${fullPrefix}content" name="${prefix}content" rows="10"&gt;$!escapetool.xml($gadgetObj.getProperty('content').value)&lt;/textarea&gt;&lt;/dd&gt;\n&lt;/dl&gt;\n&lt;input type="hidden" id="${targetDocName}_redirect" name="xredirect" value="$escapetool.xml($doc.getURL($xcontext.action, $request.queryString))" /&gt;\n&lt;input type="hidden" name="form_token" value="$!{escapetool.xml($services.csrf.token)}" /&gt;\n&lt;/fieldset&gt;\n&lt;div class="bottombuttons"&gt;&lt;p class="admin-buttons"&gt;\n&lt;span class="buttonwrapper"&gt;&lt;input class="button" type="submit" name="action_saveandcontinue" value="$services.localization.render('phenotips.navigation.webHome.save')" /&gt;&lt;/span&gt;\n&lt;/p&gt;&lt;/div&gt;\n&lt;/form&gt;\n{{/html}}</codeToExecute>\n</property>\n<property>\n<configurationClass></configurationClass>\n</property>\n<property>\n<configureGlobally>1</configureGlobally>\n</property>\n<property>\n<displayInCategory>phenotips</displayInCategory>\n</property>\n<property>\n<displayInSection>welcome</displayInSection>\n</property>\n<property>\n<heading></heading>\n</property>\n<property>\n<iconAttachment></iconAttachment>\n</property>\n<property>\n<linkPrefix></linkPrefix>\n</property>\n<property>\n<propertiesToShow/>\n</property>\n<property>\n<sectionPriority>0</sectionPriority>\n</property>\n</object>\n<object>\n<name>data.WebHome</name>\n<number>4</number>\n<className>XWiki.ConfigurableClass</className>\n<guid>2227bbb8-f5a2-4749-acf1-a63e68f453cd</guid>\n<property>\n<advancedOnly></advancedOnly>\n</property>\n<property>\n<categoryPriority>0</categoryPriority>\n</property>\n<property>\n<codeToExecute>{{info}}$services.localization.render('phenotips.navigation.webHome.defaultPhenotypes.info'){{/info}}\n\n#if ($isAdvancedUser)\n#set ($errorMessage = '')\n#if ($request.doCreate == '1' &amp;&amp; $services.csrf.isTokenValid($request.form_token))\n  #if ("$!{request.name.trim()}" == '')\n    #set ($errorMessage = "$services.localization.render('phenotips.navigation.webHome.defaultPhenotypes.error.noName')")\n  #else\n    #set ($targetDocument = $services.model.createDocumentReference($xcontext.database, $request.space, $request.name.trim()))\n    #if ($xwiki.exists($targetDocument))\n      #set ($errorMessage = "$services.localization.render('phenotips.navigation.webHome.defaultPhenotypes.error.nameExists', [${request.name}])")\n    #else\n      $response.sendRedirect($xwiki.getURL($targetDocument, 'edit', "editor=inline&amp;template=$escapetool.url($!{request.classTemplate})&amp;title=$!escapetool.url($request.name)&amp;parent=$!escapetool.url($request.parent)"))\n      #break\n    #end\n  #end\n#end\n\n\n#if ("$!errorMessage" != '')\n{{error}}$errorMessage{{/error}}\n\n#end\n{{html clean=false}}\n&lt;form class="xformInline" action="$doc.getURL($xcontext.action, $request.queryString)" method="post"&gt;&lt;div&gt;\n  &lt;input type="hidden" name="form_token" value="$!{services.csrf.getToken()}" /&gt;\n  &lt;input type="hidden" name="doCreate" value="1" /&gt;\n  &lt;input type="hidden" name="classTemplate" value="PhenoTips.PhenotypeMappingTemplate" /&gt;\n  &lt;input type="hidden" name="space" value="PhenoTips" /&gt;\n  &lt;input type="hidden" name="parent" value="data.WebHome" /&gt;\n  &lt;label for="config-name"&gt;$services.localization.render('phenotips.navigation.webHome.defaultPhenotypes.newConfig.label') &lt;/label&gt;&lt;input type="text" name="name" id="config-name" placeholder="$services.localization.render('phenotips.navigation.webHome.defaultPhenotypes.newConfig.placeholder')"/&gt;&lt;input class="button" type="submit" value="$services.localization.render('phenotips.navigation.webHome.create')"/&gt;\n&lt;/div&gt;&lt;/form&gt;\n{{/html}}\n#end\n\n(% class="mappingPreviewContainer side" %)(((\n(% class="hint side" %)(((Preview)))\n(% id="mappingPreview"%)((()))\n)))\n$xwiki.ssx.use('PhenoTips.YesNoNAPicker', {'colorTheme' : "$!{themeDocFullName}"})##\n$xwiki.ssx.use('PhenoTips.Widgets', {'colorTheme' : "$!{themeDocFullName}"})##\n$xwiki.ssx.use('PhenoTips.PatientSheetCode', {'colorTheme' : "$!{themeDocFullName}"})##\n$xwiki.ssx.use('PhenoTips.PhenotypeMappingPreview', {'colorTheme' : "$!{themeDocFullName}"})##\n$xwiki.jsx.use('PhenoTips.PhenotypeMappingPreview')##</codeToExecute>\n</property>\n<property>\n<configurationClass>PhenoTips.DBConfigurationClass</configurationClass>\n</property>\n<property>\n<configureGlobally>1</configureGlobally>\n</property>\n<property>\n<displayInCategory>phenotips</displayInCategory>\n</property>\n<property>\n<displayInSection>mapping</displayInSection>\n</property>\n<property>\n<heading>$services.localization.render('phenotips.navigation.webHome.defaultPhenotypes.heading')</heading>\n</property>\n<property>\n<iconAttachment></iconAttachment>\n</property>\n<property>\n<linkPrefix></linkPrefix>\n</property>\n<property>\n<propertiesToShow>\n<value>phenotypeMapping</value>\n</propertiesToShow>\n</property>\n<property>\n<sectionPriority>150</sectionPriority>\n</property>\n</object>\n<object>\n<name>data.WebHome</name>\n<number>5</number>\n<className>XWiki.ConfigurableClass</className>\n<guid>1a9fbd0f-69b8-4a86-b441-2572e8d872a2</guid>\n<property>\n<advancedOnly></advancedOnly>\n</property>\n<property>\n<categoryPriority>0</categoryPriority>\n</property>\n<property>\n<codeToE