ect>\n<object>\n<name>data.WebHome</name>\n<number>2</number>\n<className>XWiki.GadgetClass</className>\n<guid>1662b049-1db2-42d1-8093-8cfcace7069c</guid>\n<property>\n<content>{{velocity}}\n#if ($isGuest)\n#set ($availableData = $services.query.xwql("from doc.object(PhenoTips.PatientClass) as pat, doc.object(PhenoTips.OwnerClass) as owner where doc.fullName &lt;&gt; 'PhenoTips.PatientTemplate' and (owner.owner = '' or owner.owner is null) and pat.identifier &gt;= 0").addFilter('unique').count())\n#else\n#set ($availableData = $services.query.xwql("from doc.object(PhenoTips.PatientClass) as pat, doc.object(PhenoTips.OwnerClass) as owner where doc.fullName &lt;&gt; 'PhenoTips.PatientTemplate' and owner.owner = :o and pat.identifier &gt;= 0").bindValue('o', $services.model.serialize($xcontext.userReference, 'default')).addFilter('unique').count())\n#end\n#if ($availableData &gt; 0)\n$xwiki.ssfx.use('uicomponents/suggest/suggestPicker.css', true)##\n$xwiki.jsfx.use('uicomponents/suggest/suggestPicker.js', true)##\n$xwiki.ssfx.use('uicomponents/widgets/userpicker/userPicker.css', true)##\n$xwiki.jsfx.use('uicomponents/widgets/userpicker/userPicker.js', true)##\n$xwiki.ssx.use('PhenoTips.DatabaseFilters')##\n$xwiki.ssx.use('PhenoTips.Skin', {'colorTheme' : "$xwiki.getSpacePreference('colorTheme')"})##\n$xwiki.jsx.use('PhenoTips.DBWebHomeSheet')##\n$xwiki.ssx.use('PhenoTips.DBWebHomeSheet')##\n$xwiki.ssx.use('PhenoTips.Widgets')##\n$xwiki.jsx.use('PhenoTips.Widgets')##\n$xwiki.jsx.use('XWiki.DateTimePicker')##\n$xwiki.ssx.use('XWiki.DateTimePicker')##\n#set ($config = $xwiki.getDocument('data.WebHome').getObject('PhenoTips.DBConfigurationClass'))\n#set ($patientClassName = 'PhenoTips.PatientClass')\n#if ($config)\n#set ($columns = ['external_id', 'doc.creator', 'doc.creationDate', '_actions'])\n#set ($columnsProperties = {\n  '_actions' : {'actions': ['edit', 'delete']}\n})\n#foreach ($column in $columns)\n  #set ($isFilterable = ($column == 'external_id'))\n  #set ($discard = $columnsProperties.put($column, { 'type' : 'text', 'link' : 'view', 'size' : 7, 'filterable' : $isFilterable, 'sortable': true  }))\n#end\n##\n##\n#set ($options = {\n  'className'         : $patientClassName,\n  'translationPrefix' : 'patient.livetable.',\n  'rowCount'          : 25,\n  'maxPages'          : 10,\n  'selectedColumn'    : $config.getProperty('livetableSortColumn').value,\n  'defaultOrder'      : 'asc',\n  'resultPage'        : 'PhenoTips.LiveTableResults'\n})\n#set ($filterFrom = ", BaseObject ownerObj, StringProperty ownerProp, LongProperty iid")\n#if ($isGuest)\n  #set ($filterWhere = "and iid.id.id = obj.id and iid.id.name = 'identifier' and iid.value &gt;= 0 and ownerObj.name = doc.fullName and ownerObj.className = 'PhenoTips.OwnerClass' and ownerProp.id.id = ownerObj.id and (ownerProp.value = '' or ownerProp.value is null)")\n#else\n  #set ($o = $escapetool.sql($services.model.serialize($xcontext.userReference, 'default')))\n  #set ($filterWhere = "and iid.id.id = obj.id and iid.id.name = 'identifier' and iid.value &gt;= 0 and ownerObj.name = doc.fullName and ownerObj.className = 'PhenoTips.OwnerClass' and ownerProp.id.id = ownerObj.id and ownerProp.value = '${o}'")\n#end\n#set ($discard = $options.put('extraParams', "&amp;filterFrom=${escapetool.url($filterFrom)}&amp;filterWhere=${escapetool.url($filterWhere)}"))\n#if ("$!config.getProperty('livetableRows').value" != '' &amp;&amp; $config.getProperty('livetableRows').value &gt; 0)\n  #set ($options.rowCount = $config.getProperty('livetableRows').value)\n#end\n#livetable('mypatients' $columns $columnsProperties $options)\n$xwiki.ssfx.use('js/xwiki/table/livetable.css', {'colorTheme' : "$xwiki.getSpacePreference('colorTheme')", 'forceSkinAction' : true})##\n#else\n{{warning}}**$services.localization.render('phenotips.configurationMissing')**{{/warning}}\n#end\n#else\n{{info}}$services.localization.render('phenotips.homepage.myData.noDataMessage'){{/info}}\n#end\n{{/velocity}}</content>\n</property>\n<property>\n<position>2,1</position>\n</property>\n<property>\n<title>{{translation key="phenotips.homepage.myData.title"/}}#if($hasCreatePage) {{html clean=false}}&lt;label for="create-patient-record"&gt;&lt;span class="fa fa-plus-circle"&gt; &lt;/span&gt;$services.localization.render('phenotips.homepage.myData.createPatient')&lt;/label&gt;#end</title>\n</property>\n</object>\n<object>\n<name>data.WebHome</name>\n<number>3</number>\n<className>XWiki.GadgetClass</className>\n<guid>347deddb-651f-4750-b314-10b6f4ed5443</guid>\n<property>\n<content>{{velocity}}\n#if (!$isGuest)\n#set ($groupsAndSelf = [$xcontext.userReference.toString()])\n#set ($groups = [])\n#set ($toProcess = $collectionstool.queue)\n#set ($discard = $toProcess.add($xcontext.userReference.toString()))\n#foreach ($iteration in [0..1000])\n  #if ($toProcess.empty)\n    #break\n  #end\n  #set ($item = $toProcess.poll())\n  #foreach ($group in $xwiki.wrapDocs($xwiki.rightsmanager.getAllGroupsNamesForMember($item)))\n    #set ($groupObj = $group.getObject('PhenoTips.PhenoTipsGroupClass'))\n    #if (!$groupObj &amp;&amp; $group.documentReference.name.endsWith(' Administrators'))\n      #set ($group = $xwiki.getDocument($services.model.resolveDocument($stringtool.removeEnd($group.documentReference.name, ' Administrators'), $group.documentReference.parent)))\n      #set ($groupObj = $group.getObject('PhenoTips.PhenoTipsGroupClass'))\n    #end\n    #if ($groupObj &amp;&amp; !$groups.contains($group.documentReference.toString()))\n      #set ($discard = $toProcess.add($group.documentReference.toString()))\n      #set ($discard = $groups.add($escapetool.sql($group.documentReference.toString())))\n      #set ($discard = $groupsAndSelf.add($escapetool.sql($group.documentReference.toString())))\n    #end\n  #end\n#end\n#set ($groupsString = "('${stringtool.join($groups, ""','"")}')")\n#if ($groups.empty)\n  #set ($query = ", BaseObject accessObj, StringProperty accessProp, BaseObject patientObj, LongProperty iid where patientObj.name = doc.fullName and doc.fullName &lt;&gt; 'PhenoTips.PatientTemplate' and patientObj.className = 'PhenoTips.PatientClass' and iid.id.id = patientObj.id and iid.id.name = 'identifier' and iid.value &gt;= 0 and accessObj.name = doc.fullName and accessProp.id.id = accessObj.id and accessObj.className = 'PhenoTips.CollaboratorClass' and accessProp.value in ('${stringtool.join($groupsAndSelf, ""','"")}') and not exists (from BaseObject ownerObj, StringProperty ownerProp where ownerObj.className = 'PhenoTips.OwnerClass' and ownerObj.name = doc.fullName and ownerProp.id.id = ownerObj.id and ownerProp.value = '$escapetool.sql($xcontext.userReference.toString())')")\n#else\n  #set ($query = ", BaseObject accessObj, StringProperty accessProp, BaseObject patientObj, LongProperty iid where patientObj.name = doc.fullName and doc.fullName &lt;&gt; 'PhenoTips.PatientTemplate' and patientObj.className = 'PhenoTips.PatientClass' and iid.id.id = patientObj.id and iid.id.name = 'identifier' and iid.value &gt;= 0 and accessObj.name = doc.fullName and accessProp.id.id = accessObj.id and ((accessObj.className = 'PhenoTips.OwnerClass' and accessProp.value in ('${stringtool.join($groups, ""','"")}')) or (accessObj.className = 'PhenoTips.CollaboratorClass' and accessProp.value in ('${stringtool.join($groupsAndSelf, ""','"")}'))) and not exists (from BaseObject ownerObj, StringProperty ownerProp where ownerObj.className = 'PhenoTips.OwnerClass' and ownerObj.name = doc.fullName and ownerProp.id.id = ownerObj.id and ownerProp.value = '$escapetool.sql($xcontext.userReference.toString())')")\n#end\n#set ($availableData = $services.query.hql($query).count())\n#if ($availableData &gt; 0)\n$xwiki.ssfx.use('uicomponents/suggest/suggestPicker.css', true)##\n$xwiki.jsfx.use('uicomponents/suggest/suggestPicker.js', true)##\n$xwiki.ssfx.use('uicomponents/widgets/userpicker/userPicker.css', true)##\n$xwiki.jsfx.use('uicomponents/widgets/userpicker/userPicker.js', true)##\n$xwiki.ssx.use('PhenoTips.DatabaseFilters')##\n$xwiki.ssx.use('PhenoTips.Skin', {'colorTheme' : "$xwiki.getSpacePreference('colorTheme')"})##\n$xwiki.jsx.use('PhenoTips.DBWebHomeSheet')##\n$xwiki.ssx.use('PhenoTips.DBWebHomeSheet')##\n$xwiki.ssx.use('PhenoTips.Widgets')##\n$xwiki.jsx.use('PhenoTips.Widgets')##\n$xwiki.jsx.use('XWiki.DateTimePicker')##\n$xwiki.ssx.use('XWiki.DateTimePicker')##\n#set ($config = $xwiki.getDocument('data.WebHome').getObject('PhenoTips.DBConfigurationClass'))\n#set ($patientClassName = 'PhenoTips.PatientClass')\n#if ($config)\n#set ($columns = ['external_id', 'doc.creator', 'doc.creationDate', '_actions'])\n#set ($columnsProperties = {\n  '_actions' : {'actions': ['edit', 'delete']}\n})\n#foreach ($column in $columns)\n  #set ($isFilterable = ($column == 'external_id'))\n  #set ($discard = $columnsProperties.put($column, { 'type' : 'text', 'link' : 'view', 'size' : 7, 'filterable' : $isFilterable, 'sortable': true  }))\n#end\n##\n##\n#set ($options = {\n  'className'         : $patientClassName,\n  'translationPrefix' : 'patient.livetable.',\n  'rowCount'          : 25,\n  'maxPages'          : 10,\n  'selectedColumn'    : $config.getProperty('livetableSortColumn').value,\n  'defaultOrder'      : 'asc',\n  'resultPage'        : 'PhenoTips.LiveTableResults'\n})\n#set ($filterFrom = ", BaseObject accessObj, StringProperty accessProp, LongProperty iid")\n#set ($filterWhere = "and iid.id.id = obj.id and iid.id.name = 'identifier' and iid.value &gt;= 0 and accessObj.name = doc.fullName and accessProp.id.id = accessObj.id and (")\n#if (!$groups.isEmpty())\n  #set ($filterWhere = "${filterWhere}(accessObj.className = 'PhenoTips.OwnerClass' and accessProp.value in ('${stringtool.join($groups, ""','"")}')) or ")\n#end\n#set ($discard = $groups.add($services.model.serialize($xcontext.userReference, 'default')))\n#set ($filterWhere = "${filterWhere}(accessObj.className = 'PhenoTips.CollaboratorClass' and accessProp.value in ('${stringtool.join($groups, ""','"")}'))) and not exists (from BaseObject ownerObj, StringProperty ownerProp where ownerObj.className = 'PhenoTips.OwnerClass' and ownerObj.name = doc.fullName and ownerProp.id.id = ownerObj.id and ownerProp.value = '$escapetool.sql($xcontext.userReference.toString())')")\n#set ($discard = $options.put('extraParams', "&amp;filterFrom=${escapetool.url($filterFrom)}&amp;filterWhere=${escapetool.url($filterWhere)}"))\n#if ("$!config.getProperty('livetableRows').value" != '' &amp;&amp; $config.getProperty('livetableRows').value &gt; 0)\n  #set ($options.rowCount = $config.getProperty('livetableRows').value)\n#end\n#livetable('sharedpatients' $columns $columnsProperties $options)\n$xwiki.ssfx.use('js/xwiki/table/livetable.css', {'colorTheme' : "$xwiki.getSpacePreference('colorTheme')", 'forceSkinAction' : true})##\n#else\n{{warning}}**$services.localization.render('phenotips.configurationMissing')**{{/warning}}\n#end\n#else\n{{info}}$services.localization.render('phenotips.homepage.sharedData.noDataMessage'){{/info}}\n#end\n#else\n{{info}}$services.localization.render('phenotips.homepage.sharedData.noDataMessage'){{/info}}\n#end\n{{/velocity}}</content>\n</property>\n<property>\n<position>2,2</position>\n</property>\n<property>\n<title>$services.localization.render('phenotips.homepage.sharedData.title') (% style="float: right;" %)[[$services.localization.render('phenotips.homepage.sharedData.allData')&gt;&gt;data.AllData]]</title>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.UIExtensionClass</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<content>\n<disabled>0</disabled>\n<name>content</name>\n<number>3</number>\n<prettyName>Extension Content</prettyName>\n<rows>10</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</content>\n<extensionPointId>\n<disabled>0</disabled>\n<name>extensionPointId</name>\n<number>1</number>\n<prettyName>Extension Point ID</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</extensionPointId>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>2</number>\n<prettyName>Extension ID</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parameters>\n<disabled>0</disabled>\n<name>parameters</name>\n<number>4</number>\n<prettyName>Extension Parameters</prettyName>\n<rows>10</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</parameters>\n<scope>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>scope</name>\n<number>5</number>\n<prettyName>Extension Scope</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>wiki=Current Wiki|user=Current User|global=Global</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</scope>\n</class>\n<name>data.WebHome</name>\n<number>0</number>\n<className>XWiki.UIExtensionClass</className>\n<guid>454b809e-0edd-4d8f-9a54-d17c25cd9319</guid>\n<property>\n<content>{{velocity}}{{html clean=false}}\n$xwiki.ssfx.use('icons/font-awesome/css/font-awesome.min.css')##\n$xwiki.ssx.use('PhenoTips.FontAwesomeIcons')##\n&lt;div id="phenotips-mainmenu" class="layoutsubsection actionmenu"&gt;\n&lt;strong id="xwikimenutitle" class="hidden"&gt;$services.localization.render('core.menu.main.title')&lt;/strong&gt;\n&lt;div class="rightmenu"&gt;\n#set ($workspaceManagerMainDocumentReference = $services.model.createDocumentReference($xcontext.mainWikiName, 'WorkspaceManager', 'WebHome'))\n#set ($isWorkspaceManagerAppInstalled = $xwiki.exists($workspaceManagerMainDocumentReference))\n#set ($isWorkspace = $services.workspace.isWorkspace($xcontext.database))\n#set ($isMainWikiUser = ($xcontext.mainWikiName == "$!{xcontext.userReference.wikiReference.name}"))\n##\n## User\n##\n#if (!$xcontext.action.startsWith('login'))\n  #if ($isGuest)\n    #set ($loginurl = $xwiki.getURL('XWiki.XWikiLogin', 'login', "xredirect=$escapetool.url($xwiki.relativeRequestURL)"))\n    #xwikitopmenuentry($!loginurl $!services.localization.render('login') 'tmLogin' 'fa fa-sign-in')\n  #else\n    #set ($logouturl = $xwiki.getURL('XWiki.XWikiLogout', 'logout', "xredirect=$escapetool.url($xwiki.relativeRequestURL)"))\n    #xwikitopmenuentry($!logouturl $!services.localization.render('logout') 'tmLogout' 'fa fa-sign-out')\n  #end\n#end\n#if ($isGuest &amp;&amp; $xwiki.hasAccessLevel('register', 'XWiki.XWikiPreferences'))\n  #set ($regurl = $xwiki.getURL('XWiki.Register', 'register'))\n  #xwikitopmenuentry($!regurl $!services.localization.render('core.register') 'tmRegister' 'fa fa-plus-square')\n#end\n##\n##\n#if (!$isGuest)\n#if ($isSuperAdmin)\n  #xwikitopmenuentry('#' $!services.localization.render('superadmin') 'tmUser' 'fa fa-user')\n#else\n  #xwikitopmenuentry("$!xwiki.getURL($xcontext.user)" "$!xwiki.getUserName($xcontext.user, false)" 'tmUser' 'fa fa-user')\n#end\n#end\n&lt;/div&gt;\n&lt;div class="leftmenu"&gt;\n##\n## Administration\n##\n#set ($isAdminAppInstalled = $xwiki.exists('XWiki.AdminSheet'))\n#if ($isAdminAppInstalled &amp;&amp; $hasSpaceAdmin)\n  #set ($adminspaceaction = $!xwiki.getURL("XWiki.XWikiPreferences", 'admin'))\n  #xwikitopmenuentry($adminspaceaction "$services.localization.render('admin')" 'tmAdminSpace' 'fa fa-cogs')\n#end\n&lt;/div&gt;\n&lt;/div&gt;\n{{/html}}{{/velocity}}</content>\n</property>\n<property>\n<extensionPointId>org.phenotips.header.top:data</extensionPointId>\n</property>\n<property>\n<name>org.phenotips.header.top.globalMen