n        &lt;li&gt;\n          &lt;label for="${targetFieldName}_${field.name}"&gt;\n          &lt;input type="checkbox" name="${targetFieldName}" id="${targetFieldName}_${field.name}" value="${field.name}" #if($valueList.contains(${field.name}) || true) checked="checked" #end /&gt;\n          ${field.translatedPrettyName}\n        &lt;/li&gt;\n        #if ($codeFields.contains(${field.name}) &amp;&amp; !${simple})\n        &lt;li&gt;\n          &lt;label for="${targetFieldName}_${field.name}_code"&gt;\n          &lt;input type="checkbox" name="${targetFieldName}" id="${targetFieldName}_${field.name}_code" value="${field.name}_code" #if($valueList.contains("${field.name}_code")) checked="checked" #end /&gt;\n          ${field.translatedPrettyName} $services.localization.render('phenotips.exportPreferences.field.ID')\n        &lt;/li&gt;\n        &lt;li&gt;\n          &lt;label for="${targetFieldName}_${field.name}_combined"&gt;\n          &lt;input type="checkbox" name="${targetFieldName}" id="${targetFieldName}_${field.name}_combined" value="${field.name}_combined" #if($valueList.contains("${field.name}_combined")) checked="checked" #end /&gt;\n          ${field.translatedPrettyName} $services.localization.render('phenotips.exportPreferences.field.IDandName')\n        &lt;/li&gt;\n        #end\n        #if ($metaFields.contains(${field.name}) &amp;&amp; !${simple})\n        &lt;li&gt;\n          &lt;label for="${targetFieldName}_${field.name}_code_meta"&gt;\n          &lt;input type="checkbox" name="${targetFieldName}" id="${targetFieldName}_${field.name}_code_meta" value="${field.name}_code_meta" #if($valueList.contains("${field.name}_code_meta")) checked="checked" #end /&gt;\n          ${field.translatedPrettyName} $services.localization.render('phenotips.exportPreferences.field.termAndMetaID')\n        &lt;/li&gt;\n        &lt;li&gt;\n          &lt;label for="${targetFieldName}_${field.name}_meta"&gt;\n          &lt;input type="checkbox" name="${targetFieldName}" id="${targetFieldName}_${field.name}_meta" value="${field.name}_meta" #if($valueList.contains("${field.name}_meta") || true) checked="checked" #end /&gt;\n          ${field.translatedPrettyName} $services.localization.render('phenotips.exportPreferences.field.termAndMetaNames')\n        &lt;/li&gt;\n        #end\n        #end\n      #end\n    &lt;/ul&gt;\n    &lt;input type="hidden" name="${targetFieldName}" value="" /&gt;\n  {{/html}}\n#end\n{{/velocity}}\n\n{{velocity}}\n{{html clean="false" filter="indent"}}&lt;form class="xform" action="${escapetool.xml($request.get('export_endpoint'))}" method="post"&gt;&lt;div&gt;{{/html}}\n(% class="section filters"%)(((\n=== (% class="step" %)1(%%) $services.localization.render('phenotips.exportPreferences.filterTitle') ===\n\n#__filters_display('export-filters')\n\n{{info}} $services.localization.render('phenotips.exportPreferences.numMatchingRecords', [ "**(% id='filter-match-count'%) (%%)**" ]) {{/info}}\n)))##section filters\n\n(% class="section columns"%)(((\n=== (% class="step" %)2(%%) $services.localization.render('phenotips.exportPreferences.selectFields') ===\n#if ($request.multipatient)\n  #set($activeFields = ['external_id', 'gender', 'phenotype', 'negative_phenotype', 'omim_id'])\n  #set($ignored = {})\n  #set($customValues = {})\n  #set($codeFields = [])\n  #set($metaFields = [])\n  #set($selectedValues = [])\n  #__export__displayFieldList( "PhenoTips.PatientClass" 'columns' $customValues $ignored $codeFields $selectedValues false $activeFields)\n  #set($exportTitle = "$services.localization.render('phenotips.exportPreferences.push.submit', [$request.remoteserver])")\n  #set($exportButtonID = "push-multiple-patients")\n#else\n  #set($ignored = {\n    'fields' : ['reports_history', 'pedigree', 'extended_negative_phenotype', 'extended_phenotype', 'extended_prenatal_phenotype', 'extended_negative_prenatal_phenotype'],\n    'types'  : []\n  })\n  #if (${request.export_id} == 'phenotips_json_export')\n    #set ($si