add($data))\n      #end\n      #if ($measurement.isDoubleSided())\n        #set ($value = $mathtool.toDouble("$!request.get(""${measurement.name}_right"")"))\n        #if ("$!value" != '' &amp;&amp; $value != 0)\n          #set($data = {'id' : "${measurement.name}_right",\n                        'value' : $value,\n                        'percentile' : $!measurement.valueToPercentile($sex, $age, $value),\n                        'deviation' : $!measurement.valueToStandardDeviation($sex, $age, $value)\n          })\n          #set($discard = $valueMapping.add($data))\n        #end\n      #end\n    #end\n    ## BMI is special, it's computed from two different measurements\n    #set ($weight = $mathtool.toDouble("$!request.weight"))\n    #set ($height = $mathtool.toDouble("$!request.height"))\n    #if ("$!weight" != '' &amp;&amp; $weight != 0 &amp;&amp; "$!height" != '' &amp;&amp; $height != 0)\n      #set($data = {'id' : 'bmi', 'value' : $!mathtool.roundTo(2, $services.measurements.bmi.computeBMI($weight, $height))})\n        #set($discard = $data.put('percentile', $!services.measurements.bmi.valueToPercentile($sex, $age, $weight, $height)))\n        #set($discard = $data.put('deviation', $!services.measurements.bmi.valueToStandardDeviation($sex, $age, $weight, $height)))\n      #set($discard = $valueMapping.add($data))\n    #end\n    ## Arm span is also special, it's computed as the difference from height\n    #set ($armspan = $mathtool.toDouble("$!request.armspan"))\n    #set ($height = $mathtool.toDouble("$!request.height"))\n    #if ("$!armspan" != '' &amp;&amp; $armspan != 0 &amp;&amp; "$!height" != '' &amp;&amp; $height != 0)\n      #set ($dValue = $armspan - $height)\n      #set ($dValue = $mathtool.roundTo(2, $dValue))\n      #set($data = {'id' : 'armspan', 'value' : $dValue})\n      #set($discard = $data.put('evaluation', "~= Height#if ($dValue != 0)#if($dValue &gt;= 0) + #else - #end$mathtool.abs($dValue)cm#end"))\n      #set($discard = $valueMapping.add($data))\n    #end\n  #end##age\n  {\n  #foreach ($entry in $valueMapping)\n    #if ("$!entry.evaluation" != '')\n      #set ($dValue = $entry.evaluation)\n    #elseif ("$!entry.value" == '' || "$!{entry.percentile}" == '' || $entry.percentile &lt; 0 || "$!{entry.deviation}" == '')\n      #set ($dValue = '-')\n    #else\n      #set ($pValue = $entry.percentile)\n      #set ($sdValue = $entry.deviation)\n      #set ($dValue = "${pValue}#if($pValue&gt;10 &amp;&amp; $pValue&lt;20)&lt;sup&gt;th&lt;/sup&gt;#elseif($pValue%10==1)&lt;sup&gt;st&lt;/sup&gt;#elseif($pValue%10==2)&lt;sup&gt;nd&lt;/sup&gt;#elseif($pValue%10==3)&lt;sup&gt;rd&lt;/sup&gt;#{else}&lt;sup&gt;th&lt;/sup&gt;#end pctl (#if ($sdValue &gt;= 0)+#end${mathtool.roundTo(2, $sdValue)}SD)")\n    #end\n    "$entry.id" : {\n        "value" : "#dashIfEmpty($entry.value)",\n        "percentile" : "#dashIfEmpty($entry.percentile)",\n        "deviation" : "#dashIfEmpty($entry.deviation)",\n        "valCategory" : "$!services.measurements.getFuzzyValue($entry.deviation)",\n        "evaluation" : "$dValue"\n    }#if($foreach.hasNext()),\n\n    #end\n  #end\n\n  }\n#end{{/velocity}}\n</content></xwikidoc>
2892263817918590370	1	1	2017-05-12 15:43:36	Install extension [org.phenotips:patient-measurements-ui-1.2.6]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>PhenoTips</web>\n<name>ChartGenerator</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>PhenoTips.ChartService</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1401822204000</creationDate>\n<date>1494618216000</date>\n<contentUpdateDate>1494618216000</contentUpdateDate>\n<version>1.1</version>\n<title></title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.phenotips:patient-measurements-ui-1.2.6]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.1</syntaxId>\n<hidden>true</hidden>\n<content>#macro (getPercentileValue $age $p)\n  #set ($v = $services.measurements.get($chartConfiguration.measurementType).percentileToValue($sex, $age, $p))\n#end\n#macro (getSDValue $age $d)\n  #set ($v = $services.measurements.get($chartConfiguration.measurementType).standardDeviationToValue($sex, $age, $d))\n#end\n#macro (getValuePercentile $age $v)\n  #set ($p = $services.measurements.get($chartConfiguration.measurementType).valueToPercentile($sex, $age, $v))\n#end\n#macro (getValueSD $age $v)\n  #set ($d = $services.measurements.get($chartConfiguration.measurementType).valueToStandardDeviation($sex, $age, $v))\n#end\n#macro (getPercentileColor $p)\n  #set ($macro.h = $mathtool.mul(110, $mathtool.pow($mathtool.div($mathtool.sub(50, $mathtool.abs($mathtool.sub($p, 50))), 50.0), 0.5)))\n  #set ($macro.s = 1)\n  #set ($macro.l = 0.5)\n  #set ($macro.r = $macro.l)\n  #set ($macro.g = $macro.l)\n  #set ($macro.b = $macro.l)\n  #if ($macro.l &lt;= 0.5)\n    #set ($macro.v = ($macro.l * (1.0 + $macro.s)))\n  #else\n    #set ($macro.v = ($macro.l + $macro.s - $macro.l * $macro.s))\n  #end\n  #if ($macro.v &gt; 0)\n    #set ($macro.m = $macro.l + $macro.l - $macro.v)\n    #set ($macro.sv = ($macro.v - $macro.m) / $macro.v)\n    #set ($macro.h = $macro.h / 60.0)\n    #set ($macro.sextant = $mathtool.floor($macro.h))\n    #set ($macro.fract = $macro.h - $macro.sextant)\n    #set ($macro.vsf = $macro.v * $macro.sv * $macro.fract)\n    #set ($macro.mid1 = $macro.m + $macro.vsf)\n    #set ($macro.mid2 = $macro.v - $macro.vsf)\n    #if ($macro.sextant == 0)\n      #set ($macro.r = $macro.v)\n      #set ($macro.g = $macro.mid1)\n      #set ($macro.b = $macro.m)\n    #elseif ($macro.sextant == 1)\n      #set ($macro.r = $macro.mid2)\n      #set ($macro.g = $macro.v)\n      #set ($macro.b = $macro.m)\n    #elseif ($macro.sextant == 2)\n      #set ($macro.r = $macro.m)\n      #set ($macro.g = $macro.v)\n      #set ($macro.b = $macro.mid1)\n    #elseif ($macro.sextant == 3)\n      #set ($macro.r = $macro.m)\n      #set ($macro.g = $macro.mid2)\n      #set ($macro.b = $macro.v)\n    #elseif ($macro.sextant == 4)\n      #set ($macro.r = $macro.mid1)\n      #set ($macro.g = $macro.m)\n      #set ($macro.b = $macro.v)\n    #else\n      #set ($macro.r = $macro.v)\n      #set ($macro.g = $macro.m)\n      #set ($macro.b = $macro.mid2)\n    #end\n  #end\n  #set ($macro.r = $mathtool.toInteger($mathtool.mul($macro.r, 255)))\n  #set ($macro.g = $mathtool.toInteger($mathtool.mul($macro.g, 255)))\n  #set ($macro.b = $mathtool.toInteger($mathtool.mul($macro.b, 255)))\n  #set ($macro.r = $macro.r.toHexString($macro.r))\n  #if ($macro.r.length() == 1)\n    #set ($macro.r = "0$macro.r")\n  #end\n  #set ($macro.g = $macro.g.toHexString($macro.g))\n  #if ($macro.g.length() == 1)\n    #set ($macro.g = "0$macro.g")\n  #end\n  #set ($macro.b = $macro.b.toHexString($macro.b))\n  #if ($macro.b.length() == 1)\n    #set ($macro.b = "0$macro.b")\n  #end\n  ${escapetool.h}${macro.r}${macro.g}${macro.b}##\n#end\n#set ($xlines = $mathtool.toInteger($mathtool.div($mathtool.sub($chartConfiguration.upperAgeLimit, $chartConfiguration.lowerAgeLimit), $chartConfiguration.ageTickStep)))\n#set ($ylines = $mathtool.toInteger($mathtool.div($mathtool.sub($chartConfiguration.upperValueLimit, $chartConfiguration.lowerValueLimit), $chartConfiguration.valueTickStep)))\n#set ($graphWidth = 828)\n#set ($graphHeight = 1080)\n#set ($chartWidth = $mathtool.add($graphWidth, 125))\n#set ($chartHeight = $mathtool.add($graphHeight, 146))\n#set ($xstep = $mathtool.div($graphWidth, $xlines))\n#set ($ystep = $mathtool.div($graphHeight, $ylines))\n#set ($yscale = $mathtool.div($ystep, $chartConfiguration.valueTickStep))\n#set ($xscale = $mathtool.div($xstep, $chartConfiguration.ageTickStep))\n#if ($chartConfiguration.ageLabelStep &gt;= 12)\n  #set ($ageInYears = true)\n#else\n  #set ($ageInYears = false)\n#end\n#if (!$chartCounter)\n  #set ($chartCounter = 0)\n#else\n  #set ($chartCounter = $chartCounter + 1)\n#end\n{{html clean="false"}}\n##$response.setContentType('image/svg+xml')\n&lt;svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="-60.5 -80.5 $chartWidth $chartHeight" ##\n#if ("$!{request.standalone}" == '1' || $xcontext.action == 'export')\n  width="$chartWidth" height="$chartHeight" ##\n#else\n  width="100%" ##\n#end\npreserveAspectRatio="xMinYMin meet" style="overflow: hidden;" text-rendering="optimizeLegibility"&gt;\n  &lt;title&gt;${chartConfiguration.chartTitle}, #if ($sex)$services.localization.render('phenotips.chartGenerator.chartTitle.male')#{else}$services.localization.render('phenotips.chartGenerator.chartTitle.female')#end&lt;/title&gt;\n  &lt;style type="text/css"&gt;\na:hover {\n  text-decoration: underline;\n}\n.chart-background {\n  fill: white;\n  stroke: none;\n}\n.chart-border {\n  stroke: #000;\n  stroke-width: 1px;\n  fill: none;\n}\n.chart-grid {\n  stroke: #AAA;\n  stroke-width: 0.5px;\n  fill: none;\n  shape-rendering: geometricPrecision;\n}\n.chart-grid.bold {\n  stroke-width: 1px;\n  stroke: #AAA;\n}\n.chart-percentile-curve, .chart-deviation-curve {\n  stroke: #000;\n  stroke-width: 1px;\n  stroke-linejoin: round;\n  fill: none;\n}\n.chart-deviation, .chart-deviation-curve {\n  display: none;\n}\n.boy .chart-percentile-curve {\n  stroke: #1059A0;\n}\n.girl .chart-percentile-curve {\n  stroke: #C44;\n  stroke: #D05;\n}\n.chart-percentile-curve.bold {\n  stroke-width: 2px;\n}\n.chart-percentile-curve.guideline {\n  stroke: #AAA;\n  stroke-width: 1px;\n  stroke-dasharray: 3px 3px;\n}\n.chart-title {\n  text-anchor: middle;\n  font-size: 28px;\n  font-family: sans-serif;\n}\n.chart-label {\n  text-anchor: middle;\n  font-size: 14px;\n  font-family: monospace;\n}\n.chart-label.left {\n  text-anchor: end;\n}\n.chart-label.right {\n  text-anchor: start;\n}\n.chart-label.bold {\n  font-weight: 900;\n}\n.chart-label.side {\n  font-family: sans-serif;\n  font-size: 20px;\n  text-anchor: middle;\n}\n.reference {\n  font-size: 10px;\n  text-anchor: end;\n}\n.chart-percentile.chart-background {\n  stroke: none;\n  fill: white;\n}\n  &lt;/style&gt;\n  &lt;defs&gt;\n    &lt;clipPath id="border${chartCounter}"&gt;\n      &lt;rect x="0" y="0.5" width="$graphWidth" height="$graphHeight" class="chart-border" /&gt;\n    &lt;/clipPath&gt;\n  &lt;/defs&gt;\n  &lt;rect x="-60" y="-80" width="$mathtool.sub($chartWidth, 1)" height="$mathtool.sub($chartHeight, 1)" class="chart-background" /&gt;\n  &lt;g transform="translate(0, 10)" class="#if ($sex)boy#{else}girl#{end}"&gt;\n  #foreach ($i in [0..$xlines])\n    #set ($age = $mathtool.add($mathtool.mul($i, $chartConfiguration.ageTickStep), $chartConfiguration.lowerAgeLimit))\n    #set ($isMajorLine = $mathtool.abs($mathtool.sub($mathtool.div($age, $chartConfiguration.ageLabelStep), $mathtool.round($mathtool.div($age, $chartConfiguration.ageLabelStep)))) &lt;= 0.0001)\n    #set ($x = $mathtool.mul($i, $xstep))\n    &lt;line x1="$x" y1="0" x2="$x" y2="$graphHeight" class="chart-grid#if ($isMajorLine) bold#end" /&gt;\n    #if ($age == 0)\n      &lt;text x="$x" y="$mathtool.add($graphHeight, 5)" class="bottom chart-label bold" dy="1ex"&gt;$services.localization.render('phenotips.chartGenerator.birth')&lt;/text&gt;\n      &lt;text x="$x" y="-4" class="top chart-label bold"&gt;$services.localization.render('phenotips.chartGenerator.birth')&lt;/text&gt;\n    #elseif ($isMajorLine)\n      #if ($ageInYears)\n        #set ($age = $age / 12)\n      #end\n      &lt;text x="$x" y="$mathtool.add($graphHeight, 5)" class="bottom chart-label#if (!$ageInYears &amp;&amp; $age % 12 == 0) bold#end" dy="1ex"&gt;$age&lt;/text&gt;\n      &lt;text x="$x" y="-4" class="top chart-label#if (!$ageInYears &amp;&amp; $age % 12 == 0) bold#end"&gt;$age&lt;/text&gt;\n    #end\n  #end\n  #if (($chart.startsWith('height') || $chart.startsWith('bmi')) &amp;&amp; $chartConfiguration.lowerAgeLimit &lt; 24 &amp;&amp; $chartConfiguration.upperAgeLimit &gt; 24)\n    #set ($x = $mathtool.mul(24, $xstep))\n    &lt;line x1="$x" y1="0" x2="$x" y2="$graphHeight" class="chart-border" /&gt;\n  #end\n  #foreach ($i in [0..$ylines])\n    #set ($value = $mathtool.roundTo(1, $mathtool.add($mathtool.mul($i, $chartConfiguration.valueTickStep), $chartConfiguration.lowerValueLimit)))\n    #set ($isMajorLine = $mathtool.abs($mathtool.sub($mathtool.div($value, $chartConfiguration.valueLabelStep), $mathtool.round($mathtool.div($value, $chartConfiguration.valueLabelStep)))) &lt;= 0.0001)\n    #set ($y = $mathtool.sub($graphHeight, $mathtool.mul($i, $ystep)))\n    &lt;line x1="0" y1="$y" x2="$graphWidth" y2="$y" class="chart-grid#if ($isMajorLine) bold#end" /&gt;\n    #if ($isMajorLine)\n      #if ($mathtool.floor($chartConfiguration.valueLabelStep) == $chartConfiguration.valueLabelStep)\n        #set ($value = $mathtool.toInteger($value))\n      #end\n      &lt;text x="-4" y="$y" class="left chart-label" dy="0.5ex"&gt;$value&lt;/text&gt;\n      &lt;text x="$mathtool.add($graphWidth, 4)" y="$y" class="right chart-label" dy="0.5ex"&gt;$value&lt;/text&gt;\n    #end\n  #end\n  #foreach ($p in [3, 10, 25, 50, 75, 90, 97])\n    #getPercentileValue($chartConfiguration.lowerAgeLimit $p)\n    &lt;path clip-path="url(#border${chartCounter})" class="chart-percentile-curve#if ($p == 3 || $p == 50 || $p == 97) bold#end" d="M0 $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))L##\n    #foreach ($i in [1..$xlines])\n      #set ($age = $mathtool.add($mathtool.mul($i, $chartConfiguration.ageTickStep), $chartConfiguration.lowerAgeLimit))\n      #getPercentileValue($age $p)\n      $mathtool.mul($foreach.count, $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale)) ##\n      #if ($age == 23 &amp;&amp; ($chartConfiguration.measurementType == 'height' || $chartConfiguration.measurementType == 'bmi') &amp;&amp; $chartConfiguration.lowerAgeLimit &lt; 24 &amp;&amp; $chartConfiguration.upperAgeLimit &gt; 24)\n        #set ($v2 = $v)\n        #getPercentileValue($mathtool.sub($age, 1) $p)\n        #set ($v1 = $v)\n        #set ($d = ($v2 - $v1) / 2)\n        #set ($v3 = $v2 + $d)\n        $mathtool.mul($mathtool.add(1, $foreach.count), $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v3, $chartConfiguration.lowerValueLimit), $yscale)) ##\n        #getPercentileValue($mathtool.add($age, 2) $p)\n        #set ($v3 = $v)\n        #getPercentileValue($mathtool.add($age, 1) $p)\n        #set ($v2 = $v)\n        #set ($d = ($v3 - $v2) / 2)\n        #set ($v1 = $v2 - $d)\n        M $mathtool.mul($mathtool.add(1, $foreach.count), $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v1, $chartConfiguration.lowerValueLimit), $yscale)) L##\n      #end\n    #end\n    "/&gt;\n  #end\n  #foreach ($d in [-3..3])\n    #getSDValue($chartConfiguration.lowerAgeLimit $d)\n    &lt;path clip-path="url(#border${chartCounter})" class="chart-deviation-curve#if ($d == -2 || $d == 2) bold#end" d="M0 $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))L##\n    #foreach ($i in [1..$xlines])\n      #set ($age = $mathtool.add($mathtool.mul($i, $chartConfiguration.ageTickStep), $chartConfiguration.lowerAgeLimit))\n      #getSDValue($age $d)\n      $mathtool.mul($foreach.count, $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale)) ##\n      #if ($age == 23 &amp;&amp; ($chartConfiguration.measurementType == 'height' || $chartConfiguration.measurementType == 'bmi') &amp;&amp; $chartConfiguration.lowerAgeLimit &lt; 24 &amp;&amp; $chartConfiguration.upperAgeLimit &gt; 24)\n        #set ($v2 = $v)\n        #getSDValue($mathtool.sub($age, 1) $d)\n        #set ($v1 = $v)\n        #set ($m = ($v2 - $v1) / 2)\n        #set ($v3 = $v2 + $m)\n        $mathtool.mul($mathtool.add(1, $foreach.count), $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v3, $chartConfiguration.lowerValueLimit), $yscale)) ##\n        #getSDValue($mathtool.add($age, 2) $d)\n        #set ($v3 = $v)\n        #getSDValue($mathtool.add($age, 1) $d)\n        #set ($v2 = $v)\n        #set ($m = ($v3 - $v2) / 2)\n        #set ($v1 = $v2 - $m)\n        M $mathtool.mul($mathtool.add(1, $foreach.count), $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v1, $chartConfiguration.lowerValueLimit), $yscale)) L##\n      #end\n    #end\n    "/&gt;\n  #end\n&lt;g clip-path="url(#border${chartCounter})"&gt;\n  #foreach ($m in $measurements)\n    #if ($m.a &gt;= $chartConfiguration.lowerAgeLimit &amp;&amp; $m.a &lt; $chartConfiguration.upperAgeLimit)\n      #getValuePercentile($m.a $m.x)\n      #getPercentileValue($chartConfiguration.lowerAgeLimit $p)\n      &lt;path class="chart-percentile-curve guideline" d="M0 $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))L##\n      #foreach ($i in [1..$xlines])\n        #set ($age = $mathtool.add($mathtool.mul($i, $chartConfiguration.ageTickStep), $chartConfiguration.lowerAgeLimit))\n        #getPercentileValue($age $p)\n        $mathtool.mul($foreach.count, $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale)) ##\n        #if ($age == 23 &amp;&amp; ($chartConfiguration.measurementType == 'height' || $chartConfiguration.measurementType == 'bmi') &amp;&amp; $chartConfiguration.lowerAgeLimit &lt; 24 &amp;&amp; $chartConfiguration.upperAgeLimit &gt; 24)\n          #set ($v2 = $v)\n          #getPercentileValue($mathtool.sub($age, 1) $p)\n          #set ($v1 = $v)\n          #set ($d = ($v2 - $v1) / 2)\n          #set ($v3 = $v2 + $d)\n          $mathtool.mul($mathtool.add(1, $foreach.count), $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v3, $chartConfiguration.lowerValueLimit), $yscale)) ##\n          #getPercentileValue($mathtool.add($age, 2) $p)\n          #set ($v3 = $v)\n          #getPercentileValue($mathtool.add($age, 1) $p)\n          #set ($v2 = $v)\n          #set ($d = ($v3 - $v2) / 2)\n          #set ($v1 = $v2 - $d)\n          M $mathtool.mul($mathtool.add(1, $foreach.count), $xstep) $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v1, $chartConfiguration.lowerValueLimit), $yscale)) L##\n        #end\n      #end\n      "/&gt;\n    #end\n  #end\n  #foreach ($p in [3, 10, 25, 50, 75, 90, 97])\n    #getPercentileValue($mathtool.sub($chartConfiguration.upperAgeLimit, 1) $p)\n    &lt;circle cx="$mathtool.mul($mathtool.sub($xlines, 0.5), $xstep)" cy="$mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))" r="#if ($p == 3)0.5#{else}0.7#{end}em" class="chart-percentile chart-background"/&gt;\n    &lt;text x="$mathtool.mul($mathtool.sub($xlines, 0.5), $xstep)" y="$mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))" class="chart-percentile chart-label" dy="0.5ex"&gt;$p&lt;/text&gt;\n  #end\n  #foreach ($d in [-3..3])\n    #getSDValue($mathtool.sub($chartConfiguration.upperAgeLimit, 1) $d)\n    &lt;ellipse cx="$mathtool.mul($mathtool.sub($xlines, 0.85), $xstep)" cy="$mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))" ry="0.7em" rx="1.2em" class="chart-deviation chart-background"/&gt;\n    &lt;text x="$mathtool.mul($mathtool.sub($xlines, 0.85), $xstep)" y="$mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($v, $chartConfiguration.lowerValueLimit), $yscale))" class="chart-deviation chart-label" dy="0.5ex"&gt;#if ($d &gt;= 0)+#end${d}SD&lt;/text&gt;\n  #end\n  #foreach ($m in $measurements)\n    #if ($m.a &gt;= $chartConfiguration.lowerAgeLimit &amp;&amp; $m.a &lt; $chartConfiguration.upperAgeLimit)\n      #getValuePercentile($m.a $m.x)\n      #getValueSD($m.a $m.x)\n      #set ($d = $mathtool.roundTo(2, $d))\n      #set ($x = $mathtool.mul($mathtool.sub($m.a, $chartConfiguration.lowerAgeLimit), $xscale))\n      #set ($y = $mathtool.sub($graphHeight, $mathtool.mul($mathtool.sub($m.x, $chartConfiguration.lowerValueLimit), $yscale)))\n      #if ($y &gt; $mathtool.sub($graphHeight, 10))\n        #set ($y = $graphHeight - 4)\n        &lt;path d="M $x $y l 7 -14 h -14 z" fill="#getPercentileColor($p)" stroke="black" stroke-width="4" title="$mathtool.roundTo(2, $m.x), $p pctl (#if ($d &gt;= 0)+#end${d}SD)"/&gt;\n      #elseif ($y &lt; 10)\n        #set ($y = 4)\n        &lt;path d="M $x $y l 7 14 h -14 z" fill="#getPercentileColor($p)" stroke="black" stroke-width="4" title="$mathtool.roundTo(2, $m.x), $p pctl (#if ($d &gt;= 0)+#end${d}SD)"/&gt;\n      #else\n        &lt;circle cx="$x" cy="$y" fill="#getPercentileColor($p)" stroke="black" stroke-width="4" r="8" title="$mathtool.roundTo(2, $m.x), $p pctl (#if ($d &gt;= 0)+#end${d}SD)"/&gt;\n      #end\n    #end\n  #end\n  &lt;/g&gt;\n  &lt;rect x="0" y="0" width="$graphWidth" height="$graphHeight" class="chart-border" /&gt;\n  &lt;text x="