pe="hidden" name="space" value="data"/&gt;\n          &lt;label for="headerglobalsearchinput"&gt;&lt;span class="fa fa-search"&gt; &lt;/span&gt;&lt;/label&gt;&lt;input class="globalsearchinput" id="headerglobalsearchinput" type="text" name="text" placeholder="$services.localization.render('phenotips.globalHeader.search.placeholder')" size="20"/&gt;\n        &lt;/div&gt;\n      #end\n    &lt;/div&gt;\n    &lt;div class="topmenuentry all"&gt;&lt;label for="browse-all-patients"&gt;&lt;span class="fa fa-folder-open"&gt; &lt;/span&gt;&lt;a id="browse-all-patients" href="$xwiki.getURL('data.AllData')"&gt;$services.localization.render('phenotips.globalHeader.allData')&lt;/a&gt;&lt;/label&gt;&lt;/div&gt;\n    #if ($hasCreatePage)\n      &lt;div class="topmenuentry add"&gt;\n{{/html}}\n\n{{include reference="PhenoTips.CreatePatientRecordForm" /}}\n\n{{html clean=false}}&lt;/div&gt;\n    #end\n  &lt;/div&gt;\n  &lt;div class="breadcrumbs leftmenu"&gt;\n    &lt;a href="$!xwiki.getURL($services.model.resolveDocument('', 'default', $doc.documentReference.extractReference('WIKI')))" title="Home" rel="home"&gt;&lt;span class="fa fa-home fa-lg"&gt;&lt;/span&gt;&lt;/a&gt; &amp;raquo;\n    &lt;a href="$!xwiki.getURL("${doc.space}.WebHome")" &gt;$!{doc.space}&lt;/a&gt;\n    #if ($doc.name != 'WebHome')\n      &amp;raquo; &lt;a href="$doc.getURL()"&gt;$doc.displayTitle&lt;/a&gt;\n    #end\n  &lt;/div&gt;\n&lt;/div&gt;\n{{/html}}{{/velocity}}</content>\n</property>\n<property>\n<extensionPointId>org.phenotips.header.bottom:Groups</extensionPointId>\n</property>\n<property>\n<name>org.phenotips.header.bottom.globalTools</name>\n</property>\n<property>\n<parameters></parameters>\n</property>\n<property>\n<scope>wiki</scope>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.UIExtensionClass</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameFiel