sType>\n</extensionPointId>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>2</number>\n<prettyName>Extension ID</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parameters>\n<disabled>0</disabled>\n<name>parameters</name>\n<number>4</number>\n<prettyName>Extension Parameters</prettyName>\n<rows>10</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</parameters>\n<scope>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>scope</name>\n<number>5</number>\n<prettyName>Extension Scope</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>wiki=Current Wiki|user=Current User|global=Global</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</scope>\n</class>\n<name>PhenoTips.PhenoTipsGroupSheet</name>\n<number>0</number>\n<className>XWiki.UIExtensionClass</className>\n<guid>f501f9c0-0ee3-4ec1-8a7e-cb81db0ab52b</guid>\n<property>\n<content>{{velocity}}\n$xwiki.ssx.use('PhenoTips.PhenoTipsGroupSheet')##\n#if ($xcontext.action == 'view' &amp;&amp; $hasEdit &amp;&amp; ($doc.getObject('PhenoTips.PhenoTipsGroupClass') || $doc.getObject('XWiki.XWikiGroups') &amp;&amp; $doc.space == 'Groups'))(% class="doc-tools buttonwrapper" %)((([[ {{icon name="pencil"/}}&gt;&gt;path:$doc.getURL('edit') || title="$services.localization.render('phenotips.groups.edit')" class="doc-tool edit button"]])))#end{{/velocity}}</content>\n</property>\n<property>\n<extensionPointId>org.xwiki.platform.content.top</extensionPointId>\n</property>\n<property>\n<name>org.phenotips.groupSheet.tools</name>\n</property>\n<property>\n<parameters></parameters>\n</property>\n<property>\n<scope>wiki</scope>\n</property>\n</object>\n<content>{{velocity}}\n$xwiki.ssx.use('PhenoTips.PhenoTipsGroupSheet')##\n$xwiki.jsx.use('PhenoTips.PhenoTipsGroupSheet')##\n$xwiki.jsx.use('PhenoTips.Widgets')##\n$xwiki.ssx.use('PhenoTips.Widgets')##\n$xwiki.jsx.use('PhenoTips.ImageDisplayer')##\n$xwiki.ssx.use('PhenoTips.ImageDisplayer')##\n$xwiki.ssfx.use('icons/font-awesome/css/font-awesome.min.css')##\n#if ($xcontext.action == 'edit')\n(% class="xform" %)(((\n; {{html}}&lt;label&gt;$services.localization.render('phenotips.groups.name')&lt;/label&gt;{{/html}}\n: (% class="xHint" %)$services.localization.render('phenotips.groups.nameHint')\n: {{html}}&lt;input type="text" name="title" value="$!doc.title"/&gt;{{/html}}\n; {{html}}&lt;label&gt;$services.localization.render('phenotips.groups.image')&lt;/label&gt;{{/html}}\n: (% class="xHint" %)$services.localization.render('phenotips.groups.imageHint')\n: $doc.display('image')\n; {{html}}&lt;label&gt;$services.localization.render('phenotips.groups.description')&lt;/label&gt;{{/html}}\n: (% class="xHint" %)$services.localization.render('phenotips.groups.descriptionHint')\n: $doc.display('description')\n; {{html}}&lt;label&gt;$services.localization.render('phenotips.groups.contact')&lt;/label&gt;{{/html}}\n: (% class="xHint" %)$services.localization.render('phenotips.groups.contactHint')\n: $doc.display('contact')\n; {{html}}&lt;label&gt;$services.localization.render('phenotips.groups.publicInfo')&lt;/label&gt;{{/html}}\n: (% class="xHint" %)$services.localization.render('phenotips.groups.publicInfoHint')\n: $doc.display('public_sections')\n#if ($xwiki.exists('PhenoTips.StudyClass'))\n; {{html}}&lt;label&gt;$services.localization.render('phenotips.groups.studies')&lt;/label&gt;{{/html}}\n: (% class="xHint" %)$services.localization.render('phenotips.groups.studiesHint')\n: $doc.display('studies')\n#end\n\n)))\n(% class="xform" %)(((\n== $services.localization.render('phenotips.groups.manageMembers') ==\n\n(% class="buttonwrapper" %)[[{{icon name="wrench" /}} $services.localization.render('phenotips.groups.manageAdmins')&gt;&gt;path:$xwiki.getURL("${doc.fullName} Administrators", 'edit')||rel="__blank" class="button" style="float: right" id="manage-administrators"]]\n\n{{include reference='XWiki.XWikiGroupSheet'/}}\n\n)))\n#else\n(% class="group-logo" %)(((#if ("$!{doc.getObject('PhenoTips.PhenoTipsGroupClass').getProperty('image').value}" != '')$doc.display('image')#{else}$xwiki.getDocument('PhenoTips.PhenoTipsGroupTemplate').display('image')#{end})))$doc.display('description')\n\n#set ($isMyGroup = $xwiki.user.isUserInGroup($doc.fullName) || $xwiki.user.isUserInGroup("${doc.fullName} Administrators"))\n#if ($isMyGroup){{info}}{{translation key="phenotips.groups.selfMembership"/}}{{/info}}#end\n(% class="clearfloats" %)((()))\n#end\n\n#if ($xcontext.action == 'view')\n#set ($obj = $doc.getObject('PhenoTips.PhenoTipsGroupClass'))\n#set ($sections = [\n  {'id' : 'members', 'name' : "$services.localization.render('phenotips.groups.menu.groupMembers')", 'icon' : 'users',       'content' : '{{include reference="XWiki.XWikiGroupSheet"/}}'},\n  {'id' : 'cases',   'name' : "$services.localization.render('phenotips.groups.menu.cases')",  'icon' : 'folder-open', 'content' : '{{include reference="PhenoTips.GroupCases"/}}'}\n])\n#if ($xwiki.exists('PhenoTips.CollaboratorClass'))\n  #set ($discard = $sections.add({'id' : 'sharedCases', 'name' : "$services.localization.render('phenotips.groups.menu.sharedCases')", 'icon' : 'share-square', 'content' : '{{include reference="PhenoTips.GroupSharedCases"/}}'}))\n#end\n#if ($xwiki.exists('PhenoTips.StudyClass'))\n  #set ($discard = $sections.add({'id' : 'studies' ,   'name' : "$services.localization.render('phenotips.groups.menu.studies')",  'icon' : 'copy',        'content' : "((({{phenotips-studies filterby='group' filterval='${services.rendering.escape($doc.fullName, $doc.syntax)}' /}})))"}))\n#end\n#set ($menu = [])\n#set ($contents = {})\n#foreach ($s in $sections)\n  #if ($isMyGroup || $hasAdmin || $obj.getProperty('public_sections').value.contains($s.id))\n    #set ($discard = $menu.add({\n      'id' : $s.id,\n      'name' : "&lt;i class='fa fa-$s.icon'&gt;&lt;/i&gt; $s.name",\n      'url' : "?s=${s.id}#content-${s.id}"\n    }))\n    #set ($discard = $contents.put($s.id, $s.content))\n  #end\n#end\n##\n#set ($crtContent = '')\n##\n#if ($menu.size() &gt; 0)\n  #set ($crtItem = "$!request.s")\n  #if ("$!contents.get($crtItem)" == '')\n    #set ($crtItem = "$!menu.get(0).id")\n  #end\n  #set ($crtContent = "$!contents.get($crtItem)")\n#end\n#if ($menu.size() &gt; 1)\n(% class="vertical-menu $!{options.cssClass}" %)(((\n#foreach ($i in $menu)\n* {{html clean=false wiki=false}}&lt;a href="$i.url" id="group-section-$i.id" #if ($i.id == $crtItem) class="current" #end&gt;$i.name&lt;/a&gt;{{/html}}\n#end\n)))\n(% class="menu-section" id="content-${crtItem}" %)#end((($crtContent)))\n#end\n{{/velocity}}\n</content></xwikidoc>
625106655743598530	1	1	2017-05-12 15:43:37	Install extension [org.phenotips:patient-access-rules-ui-1.2.6]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>PhenoTips</web>\n<name>PatientAccessRightsManagement</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>PhenoTips.PatientSheet</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1401822202000</creationDate>\n<date>1494618217000</date>\n<contentUpdateDate>1494618217000</contentUpdateDate>\n<version>1.1</version>\n<title></title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.phenotips:patient-access-rules-ui-1.2.6]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.1</syntaxId>\n<hidden>true</hidden>\n<object>\n<name>PhenoTips.PatientAccessRightsManagement</name>\n<number>0</number>\n<className>XWiki.ConfigurableClass</className>\n<guid>7df2fc72-5cd6-4c35-a73c-de2bbf5f2fde</guid>\n<property>\n<advancedOnly>0</advancedOnly>\n</property>\n<property>\n<categoryPriority>0</categoryPriority>\n</property>\n<property>\n<codeToExecute>#set ($targetDocName = 'PhenoTips.PatientTemplate')\n#set ($targetDoc = $xwiki.getDocument($targetDocName))\n#set ($className = 'PhenoTips.VisibilityClass')\n#set ($visibilityObject = $targetDoc.getObject($className))\n#set ($currentValue = '')\n#if ($visibilityObject)\n  #set ($currentValue = "$!visibilityObject.getProperty('visibility').value")\n#else\n  #set ($visibilityObject = $targetDoc.newObject($className))\n  $!visibilityObject.set('visibility', 'private')##\n#end\n#set ($prefix = "${className}_${visibilityObject.number}_")\n#if ($currentValue == '')\n  #set ($currentValue = 'private')\n#end\n#set ($fullPrefix = "${targetDocName}_${prefix}")\n\n{{html clean=false}}\n&lt;form id="welcome_${targetDocName}" method="post" action="${targetDoc.getURL('save')}" class="xform half"&gt;\n&lt;fieldset&gt;&lt;dl&gt;\n&lt;dt&gt;&lt;label for="${fullPrefix}private"&gt;$services.localization.render("phenotips.patientAccessRightsManagement.defaultVisibilityOption")&lt;/label&gt;\n&lt;span class="xHint"&gt;$services.localization.render("phenotips.patientAccessRightsManagement.defaultVisibilityHint")&lt;/span&gt;&lt;/dt&gt;\n#foreach ($visibility in $services.permissions.listVisibilityOptions())\n  &lt;dd&gt;\n    &lt;label for="${fullPrefix}${visibility.name}"&gt;\n      &lt;input id="${fullPrefix}${visibility.name}" name="${prefix}visibility" type="radio" value="$!escapetool.xml($visibility.name)"#if ($currentValue == $visibility.name) checked="checked"#end /&gt; $visibility.label&lt;/label&gt;\n    &lt;span class="xHint"&gt;${visibility.description}&lt;/span&gt;\n  &lt;/dd&gt;\n#end\n&lt;/dl&gt;\n&lt;input type="hidden" id="${targetDocName}_redirect" name="xredirect" value="$escapetool.xml($doc.getURL($xcontext.action, $request.queryString))" /&gt;\n&lt;input type="hidden" name="form_token" value="$!{escapetool.xml($services.csrf.token)}" /&gt;\n&lt;input type="hidden" name="objectPolicy" value="updateOrCreate"/&gt;\n&lt;/fieldset&gt;\n&lt;div class="bottombuttons"&gt;&lt;p class="admin-buttons"&gt;\n&lt;span class="buttonwrapper"&gt;&lt;input class="button" type="submit" name="action_saveandcontinue" value="$services.localization.render('phenotips.patientAccessRightsManagement.defaultVisibilitySave')" /&gt;&lt;/span&gt;\n&lt;/p&gt;&lt;/div&gt;\n&lt;/form&gt;\n{{/html}}</codeToExecute>\n</property>\n<property>\n<configurationClass></configurationClass>\n</property>\n<property>\n<configureGlobally>1</configureGlobally>\n</property>\n<property>\n<displayInCategory>phenotips</displayInCategory>\n</property>\n<property>\n<displayInSection>access</displayInSection>\n</property>\n<property>\n<heading>Default patient visibility</heading>\n</property>\n<property>\n<iconAttachment></iconAttachment>\n</property>\n<property>\n<linkPrefix></linkPrefix>\n</property>\n<property>\n<propertiesToShow/>\n</property>\n<property>\n<sectionPriority>200</sectionPriority>\n</property>\n</object>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>PhenoTips.PatientAccessRightsManagement</name>\n<number>0</number>\n<className>XWiki.JavaScriptExtension</className>\n<guid>ab66e72f-1d22-4a38-ad9b-f55d74a0473f</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>var PhenoTips = (function (PhenoTips) {\n  var widgets = PhenoTips.widgets = PhenoTips.widgets || {};\n  widgets.AccessRightsManager = Class.create({\n    initialize : function (patientId) {\n      this.patientId = patientId;\n      // ---------------------------------------------------------------------\n      // Search for access levels manager elements. Exist if missing.\n      // ---------------------------------------------------------------------\n      this._element = $('access-rights-summary');\n      if (!this._element) { return; }\n      this._editorLauncher = this._element.down('.tool.edit a');\n      if (!this._editorLauncher) { return; }\n      this._serviceURL = this._element.down('input[name="serviceURL"]');\n      if (this._serviceURL) {\n        this._serviceURL = this._serviceURL.value;\n      } else {\n        return;\n      }\n      // ---------------------------------------------------------------------\n      // Initialize the manager UI\n      // ---------------------------------------------------------------------\n      this._initAccessLevels();\n      this._initManagerUI();\n      // ---------------------------------------------------------------------\n      // Attach manager launcher behavior:\n      // ---------------------------------------------------------------------\n      var _this = this;\n      this._editorLauncher.observe('click', function(event) {\n        event.stop();\n        event.findElement().blur();\n        _this._launchEditor();\n      });\n      // ---------------------------------------------------------------------\n      // Initialization done\n      // ---------------------------------------------------------------------\n    },\n    _initAccessLevels : function() {\n      var levels = {'access-level' : [], 'visibility' : []};\n      this._element.select('input[name="access-level"], input[name="visibility"]').each(function (item) {\n        levels[item.name].push({id : item.value, name : item.alt, title : item.title, icon: item.next('span.fa') || ''});\n      });\n      this.ACCESS_LEVELS = levels['access-level'];\n      this.VISIBILITY = levels['visibility'];\n    },\n    _initManagerUI : function() {\n      this._container = new Element('form', {'id' : 'access-levels-manager', 'class' : 'xform', 'method' : 'post', 'action' : this._serviceURL});\n      //this._element.insert({'after' : this._container});\n      this._container.insert(this._generateSection('manage-ownership', "$services.localization.render('phenotips.patientAccessRightsManagement.modifyOwnershipHeader')", "$services.localization.render('phenotips.patientAccessRightsManagement.modifyOwnershipBody')"))\n                     .insert(this._generateSection('manage-visibility', "$services.localization.render('phenotips.patientAccessRightsManagement.modifyVisibilityHeader')", "$services.localization.render('phenotips.patientAccessRightsManagement.modifyVisibilityBody')"))\n                     .insert(this._generateSection('manage-collaborators', "$services.localization.render('phenotips.patientAccessRightsManagement.modifyCollaboratorsHeader')", "$services.localization.render('phenotips.patientAccessRightsManagement.modifyCollaboratorsBody')"))\n                     .insert(new Element('div', {id : 'manager-messages'}));\n      this._ownershipManager = this._container.down('#manage-ownership .section-contents');\n      this._visibilityManager = this._container.down('#manage-visibility .section-contents');\n      this._collaboratorsManager = this._container.down('#manage-collaborators .section-contents');\n      this._messages = this._container.down('#manager-messages');\n      this._initOwnershipManager();\n      this._initVisibilityManager();\n      this._initCollaboratorsManager();\n      this._initManagerActions();\n      this._dialog = new PhenoTips.widgets.ModalPopup(this._container, false, {'title': "$services.localization.render('phenotips.patientAccessRightsManagement.heading')".replace("__patientID__", this.patientId), 'verticalPosition': 'top', 'removeOnClose': false});\n      //document.fire('xwiki:dom:updated', {'elements' : [this._container]});\n    },\n    _generateSection : function(id, title, intro) {\n      return new Element('fieldset', {'id': id, 'class' : 'section'})\n                 .insert(title &amp;&amp; new Element('h2').update(title) || '')\n                 .insert(intro &amp;&amp; new Element('p', {'class' : 'intro xHint'}).update(intro) || '')\n                 .insert(new Element ('div', {'class' : 'section-contents'}));\n    },\n    _updateOwnershipManager : function(owner) {\n      this._ownerInfo.update("$services.localization.render('phenotips.patientAccessRightsManagement.modifyOwnershipInfo')".replace("__owner__", owner));\n      if (this._canTransferOwnership) {\n        this._ownerInfo.insert(" "+"$services.localization.render('phenotips.patientAccessRightsManagement.modifyOwnershipOptions')");\n        this._checkKeepOwnershipOption();\n      }\n    },\n    _initOwnershipManager : function() {\n      this._ownerInfo = new Element('div', {id : 'owner', 'class' : 'intro xHint'});\n      this._ownershipManager.update(this._ownerInfo);\n\n      // HACK: 'new-owner-input' control had to be put into the document from the start\n      //       to make suggest picker attach to it correctly; it now has to be moved into\n      //       the `owner` section of this "access rights" dialog/popup\n      var newOwnerInput       = $('new-owner-input') || '';\n      var newOwnerGroupSelect = $('new-owner-group-select') || '';\n\n      this._defaultOwnerOption   = undefined;\n      this._removeSelectedUser   = undefined;\n      this._canTransferOwnership = newOwnerInput || newOwnerGroupSelect;\n\n      if (this._canTransferOwnership) {\n        var transfer = new Element('table', {id : 'transfer'});\n        this._removeSelectedUser = function() {  // removes previously selected user displayed by the suggest user picker\n            transfer.select('.delete-tool').each(function (item) {\n               item.click();\n            });\n        }\n        var _this = this;\n        var _getTransferOption = function (type, text, controlledElement) {\n           var optionWrapper = new Element('tr');\n           var input = new Element('input', {"type" : "radio", name : "transfer-to"});\n           var label = new Element('label').insert(input).insert(text);\n           input.observe('change', function() {\n             transfer.select('.controlled-element input, .controlled-element select').each(function (item) {\n                item.disable();\n             });\n             _this._removeSelectedUser();\n             if (input.checked &amp;&amp; controlledElement) {\n               input.up('tr').select('.controlled-element input, .controlled-element select').each(function (item) {\n                  item.enable();\n               });\n             }\n           });\n           optionWrapper.insert(new Element('span', {'class' : 'fa fa-' + type}).wrap('td'))\n                        .insert(label.wrap('td'))\n                        .insert(controlledElement &amp;&amp; controlledElement.wrap('td', {'class' : 'controlled-element'}) || '');\n           return optionWrapper;\n        }\n        this._defaultOwnerOption = _getTransferOption("check", "$services.localization.render('phenotips.patientAccessRightsManagement.modifyOwnershipKeepOwnership')", "");\n        transfer.insert(this._defaultOwnerOption);\n        //this._checkKeepOwnershipOption();\n        if (newOwnerGroupSelect) {\n          transfer.insert(_