b5a7f3</guid>\n<property>\n<content>{{velocity output="false"}}\n#set ($serviceDocName = 'PhenoTips.PatientAccessRightsManagement')\n#set ($serviceDoc = $xwiki.getDocument($serviceDocName))\n$xwiki.ssfx.use('uicomponents/suggest/suggestPicker.css', true)\n$xwiki.jsfx.use('uicomponents/suggest/suggestPicker.js', true)\n$xwiki.ssfx.use('uicomponents/widgets/userpicker/userPicker.css', true)\n$xwiki.jsfx.use('uicomponents/widgets/userpicker/userPicker.js', true)\n$xwiki.jsx.use($serviceDocName)\n$xwiki.ssx.use($serviceDocName)\n{{/velocity}}\n\n{{velocity}}\n#if ($xcontext.action != 'export')\n#set ($patient = $services.patients.getPatientById($doc.documentReference))\n#if ($patient)\n  #set ($_service = $services.permissions)\n  #set ($patientAccess = $_service.getPatientAccess($patient))\n  ## ===========================================================\n  ## Display access summary for this patient and enable changing\n  ## -----------------------------------------------------------\n  #set ($visibility =  $patientAccess.visibility)\n  #set ($collaborators = $patientAccess.collaborators)\n  #set ($collaboratorsCount = $collaborators.size())\n  #set ($owner = $patientAccess.getOwner())\n  #set ($ownerReference = $owner.user)\n  #if (!$ownerReference)\n    #set ($ownerName = $services.localization.render("phenotips.patientAccessRightsManagement.noOwner"))\n  #elseif ($ownerReference.equals($xcontext.userReference))\n    #set ($ownerName = $services.localization.render("phenotips.patientAccessRightsManagement.selfOwner"))\n  #else\n    #if ($owner.isUser())\n      #set ($ownerName = $xwiki.getUserName("$ownerReference", false))\n    #else\n      #set ($ownerName = $xwiki.getDocument($ownerReference).plainTitle)\n    #end\n  #end\n  #set ($canTransfer = $patientAccess.hasAccessLevel('owner'))\n  #if ($owner.isGroup())\n    #set ($adminGroup = $xcontext.getDatabase() + ":Groups." + $owner.getUsername() + " Administrators")\n    #if (!$xwiki.getUser().isUserInGroup($adminGroup))\n      #set ($canTransfer = false)\n    #end\n  #end\n  #if ($hasAdmin)\n    #set ($canTransfer = true)\n  #end\n  #set ($canManage = $patientAccess.hasAccessLevel('manage'))\n  #if ("$!{ownerReference}" != '')\n    #set ($ownerElement = "{{html wiki='true' clean='false'}}&lt;a class='owner' href=""${xwiki.getURL($ownerReference)}""&gt;{{icon name='user'/}}$services.rendering.escape($ownerName, $doc.syntax)&lt;/a&gt;{{/html}}")\n  #else\n    #set ($ownerElement = "{{html wiki='true' clean='false'}}&lt;span class='owner'&gt;{{icon name='user'/}}$ownerName&lt;/span&gt;{{/html}}")\n  #end\n  (% id="access-rights-summary" %)(((\n    $services.localization.render("phenotips.patientAccessRightsManagement.caseOwnerandVisibility",["(% class='access-rights-info' %)$ownerElement(%%)","(% class='access-rights-info visibility' title='$!{visibility.description}' %){{icon name='$visibility'/}}${visibility.label}(%%)"])##\n    ##if ($canManage),#else and#end it is (% class="access-rights-info visibility" title="$!{visibility.description}" %){{icon name="$visibility"/}}${visibility.label}(%%)##\n    #if ($canManage) ##\n      $services.localization.render("phenotips.patientAccessRightsManagement.collaboratorsSummary",["(% class='access-rights-info' %){{html wiki='true' clean='false'}}{{icon name='group'/}}&lt;span class='collaborators'&gt;",$collaboratorsCount, "&lt;/span&gt;{{/html}}(%%)"])##\n      (% class="buttonwrapper tool edit" %)[[ {{icon name="wrench" title="$services.localization.render('phenotips.patientAccessRightsManagement.modifyButtonTitle')" /}} $services.localization.render("phenotips.patientAccessRightsManagement.modifyButton")&gt;&gt;path:#||class="button"]]##\n      (% class="hidden" %)((({{html wiki="true" clean="false"}}\n        &lt;input type="hidden" name="serviceURL" value="$serviceDoc.getURL('get', 'outputSyntax=plain')"/&gt;\n        #foreach ($l in $_service.listAccessLevels())\n          &lt;input type="hidden" name="access-level" value="${l.name}" alt="$!{l.description}" /&gt;\n        #end\n        #foreach ($l in $_service.listVisibilityOptions())\n          &lt;input type="hidden" name="visibility" value="${l.name}" alt="$!{l.label}" title="$!{l.description}" /&gt;{{icon name="${l.name}" /}}\n        #end\n        #if ($canManage)\n          &lt;input type="text" name="user" class="suggestUsers" value="" placeholder="$services.localization.render('phenotips.patientAccessRightsManagement.newCollaborator')" id="new-collaborator-input" /&gt;\n          &lt;input type="text" name="group" class="suggestWorkgroups" value="" placeholder="$services.localization.render('phenotips.patientAccessRightsManagement.newGroupCollaborator')" id="new-group-input" /&gt;\n        #end\n        #if ($canTransfer)\n          &lt;div id="new-owner-input"&gt;&lt;input type="text" name="owner" id="new-owner-user-select" class="suggestUsers" value="" placeholder="$services.localization.render('phenotips.patientAccessRightsManagement.newOwner')" /&gt;&lt;/div&gt;\n          #set ($toProcess = $collectionstool.queue)\n          #set ($discard = $toProcess.add($xcontext.userReference.toString()))\n          #set ($groups = $collectionstool.sortedMap)\n          #if ($hasAdmin)\n            #set ($groupClassName = 'PhenoTips.PhenoTipsGroupClass')\n            #set ($groupTemplateName = 'PhenoTips.PhenoTipsGroupTemplate')\n            #set ($query = $services.query.xwql("from doc.object(${groupClassName}) as grp where doc.fullName &lt;&gt; :template").bindValue('template', $groupTemplateName))\n            #set ($groupDocs = $xwiki.wrapDocs($query.execute()))\n            #foreach ($groupDoc in $groupDocs)\n              #set ($discard = $groups.put($groupDoc.documentReference, $groupDoc.plainTitle))\n            #end\n          #else\n            #foreach ($iteration in [0..1000])\n              #if ($toProcess.empty)\n                #break\n              #end\n              #set ($item = $toProcess.poll())\n              #foreach ($group in $xwiki.wrapDocs($xwiki.rightsmanager.getAllGroupsNamesForMember($item)))\n                #set ($groupObj = $group.getObject('PhenoTips.PhenoTipsGroupClass'))\n                #if (!$groupObj &amp;&amp; $group.documentReference.name.endsWith(' Administrators'))\n                  #set ($group = $xwiki.getDocument($services.model.resolveDocument($stringtool.removeEnd($group.documentReference.name, ' Administrators'), $group.documentReference.parent)))\n                  #set ($groupObj = $group.getObject('PhenoTips.PhenoTipsGroupClass'))\n                #end\n                #if ($groupObj &amp;&amp; !$groups.containsKey($group.documentReference))\n                  #set ($discard = $toProcess.add($group.documentReference.toString()))\n                  #if ("$group.plainTitle" != '')\n                    #set ($discard = $groups.put($group.documentReference, $group.plainTitle))\n                  #else\n                    #set ($discard = $groups.put($group.documentReference, $group.documentReference.name))\n                  #end\n                #end\n              #end\n            #end\n          #end\n          #if (!$groups.isEmpty())\n          &lt;select name="owner" id="new-owner-group-select"&gt;\n            &lt;option value="" selected="selected" class="hidden"&gt;$services.localization.render('phenotips.patientAccessRightsManagement.newOwnerGroup')&lt;/option&gt;\n            &lt;optgroup label="$services.localization.render('phenotips.patientAccessRightsManagement.newOwnerGroup')"&gt;\n            #foreach ($g in $groups.entrySet())\n              &lt;option value="${services.rendering.escape($services.model.serialize($g.key), $doc.syntax)}"#if ("$!{ownerReference}" == "$g.key") selected="selected"#end&gt;${services.rendering.escape($g.value, $doc.syntax)}&lt;/option&gt;\n            #end\n            &lt;/optgroup&gt;\n          &lt;/select&gt;\n          #end\n        #end\n      {{/html}})))\n    #end\n  )))\n#end## Patient exists\n#end#