make sure PhenomeCentral is enabled/configured, and if it is list it as the first push target\n  #if ($mapEntry.key.getServerID() == "PhenomeCentral")\n    (% id="push-patient-pc" name="PhenomeCentral" %)((([[$services.localization.render('phenotips.PushPatient.pushPhenomeCentral')&gt;&gt;path:#]])))\n  #end\n#end\n#set ($counter = 0)\n#foreach ($mapEntry in $configuredServers.entrySet())\n  #set ($serverName = $mapEntry.key.getServerID())\n  #if ($serverName != "PhenomeCentral")\n    (% id="push-patient-$counter" name="$serverName" %)((([[$services.localization.render('phenotips.PushPatient.pushToAnotherServer', [$serverName])&gt;&gt;path:#]])))\n    #set( $counter = $counter + 1 )\n  #end\n#end\n{{/velocity}}</content>\n</property>\n<property>\n<extensionPointId>org.phenotips.patientRecordMenu.moreActions</extensionPointId>\n</property>\n<property>\n<name>org.phenotips.widget.pushpatient</name>\n</property>\n<property>\n<parameters></parameters>\n</property>\n<property>\n<scope>wiki</scope>\n</property>\n</object>\n<content></content></xwikidoc>\n
