\n    #set($fullName = $name)\n  #end\n  #set($id = $term.getId())\n  &lt;li class="disorder"&gt;\n    &lt;span class="id" title="${id}"&gt;&lt;a href="http://www.omim.org/entry/${id}" target="_blank" title="Read about this disorder on OMIM"&gt;[MIM:${id}]&lt;/a&gt;&lt;/span&gt;\n    &lt;span class="title" title="${fullName}"&gt;${shortName}&lt;/span&gt;\n  &lt;/li&gt;\n#end ## foreach item\n&lt;/ul&gt;\n{{/html}}\n   #set ($hasOutput = true)\n#else\n   #set ($hasOutput = false)\n#end## results.size() &gt; 0\n    #end## html format\n  #else\n    #set ($hasOutput = false)\n  #end## non-empty query\n#end## get action\n##\n#if (!$hasOutput)\n(% class="hint" %)No matches found\n#end\n{{/velocity}}</content></xwikidoc>\n
