    #set ($disorderNames = $pedigreeDataJSON.settings.names.disorders)\n    #if ($disorderColors &amp;&amp; $disorderNames &amp;&amp; $disorderColors.size() &gt; 0)\n      Disorders:\n      &lt;ul class="pedigree-legend-list" style="margin-top: .4em; margin-bottom: .5em;"&gt;\n      #foreach ($color in $disorderColors.entrySet())\n        &lt;li class="pedigree-disorder-item" style="list-style-type: none;"&gt;\n          &lt;span class="pedigree-disorder-color" style="color: $color.value; $listyle"&gt;$circle&lt;/span&gt;\n          &lt;span class="pedigree-disorder-name"&gt;$escapetool.xml($disorderNames[$color.key])&lt;/span&gt;\n        &lt;/li&gt;\n      #end\n      &lt;/ul&gt;\n    #end\n    #if ($geneColors &amp;&amp; $geneColors.size() &gt; 0)\n      Candidate Genes:\n      &lt;ul class="pedigree-legend-list" style="margin-top: .4em"&gt;\n      #foreach ($color in $geneColors.entrySet())\n        &lt;li class="pedigree-disorder-item" style="list-style-type: none;"&gt;\n          &lt;span class="pedigree-disorder-color" style="color: $color.value; $listyle"&gt;$circle&lt;/span&gt;\n          &lt;span class="pedigree-disorder-name"&gt;$color.key&lt;/span&gt;\n        &lt;/li&gt;\n      #end\n      &lt;/ul&gt;\n    #end\n    #if ($cancerColors &amp;&amp; $cancerColors.size() &gt; 0)\n      Cancers:\n      &lt;ul class="pedigree-legend-list" style="margin-top: .4em"&gt;\n      #foreach ($color in $cancerColors.entrySet())\n        &lt;li class="pedigree-disorder-item" style="list-style-type: none;"&gt;\n          &lt;span class="pedigree-disorder-color" style="color: $color.value; $listyle"&gt;$circle&lt;/span&gt;\n          &lt;span class="pedigree-disorder-name"&gt;$color.key&lt;/span&gt;\n        &lt;/li&gt;\n      #end\n      &lt;/ul&gt;\n    #end\n\n\n    &lt;/div&gt;\n  #end\n#end\n{{/velocity}}</content></xwikidoc>\n
