d',\n  'extensionPointId' : 'extension point id'\n})\n#set ($defaultOrder = 'doc.fullName')\n#set ($order = "$!{request.order}")\n#if (!$orders.get($order))\n  #set($order = $defaultOrder)\n#end\n\n#set ($uixClassName = 'XWiki.UIExtensionClass')\n#set ($uixTemplate = 'PhenoTips.UIXTemplate')\n\n#set ($uixDocs = $xwiki.wrapDocs($xwiki.searchDocuments(", BaseObject obj where doc.fullName &lt;&gt; ? and doc.fullName = obj.name and obj.className= ? order by doc.fullName asc", [$uixTemplate, $uixClassName])))\n\n#set($uixData = [])\n\n#foreach ($uixDoc in $uixDocs)\n  #set ($uixObjs = $uixDoc.getObjects($uixClassName))\n  #foreach ($uixObj in $uixObjs)\n    #set ($discard = $uixData.add({\n      'doc' : $uixDoc,\n      'obj' : $uixObj,\n      'doc.name' : $uixDoc.name,\n      'doc.fullName' : $uixDoc.fullName,\n      'doc.space' : $uixDoc.space,\n      'extensionId' : $uixObj.getProperty('name').value,\n      'extensionPointId' : $uixObj.getProperty('extensionPointId').value\n    }))\n  #end\n#end\n#set ($uixSortedData = $sorttool.sort($uixData, [$order]))\n\nSort UI extensions alphabetically by: ##\n#foreach ($o in $orders.keySet())\n  #if ($o == $order)\n   **$orders.get($o)**##\n  #else\n    [[$orders.get($o)&gt;&gt;$doc.fullName||queryString="$!{request.queryString.replaceAll('[&amp;]?order=[^&amp;]*', '')}&amp;order=${o}"]]##\n  #{end}#if ($foreach.hasNext()) | #end\n#end\n{{/velocity}}\n\n{{velocity}}\n#if ($hasAdmin)\n#set ($errorMessage = '')\n#if ($request.doCreate == '1' &amp;&amp; $services.csrf.isTokenValid($request.form_token))\n  #if ("$!{request.name.trim()}" == '')\n    #set ($errorMessage = "$services.localization.render('phenotips.UIXDirectory.noNameError')")\n  #else\n    #set ($targetDocument = $services.model.createDocumentReference($xcontext.database, $request.space, $request.name.trim()))\n    #if ($xwiki.exists($targetDocument))\n      #set ($errorMessage = "$services.localization.render('phenotips.UIXDirectory.nameExistsError', [${request.name}])")\n    #else\n      #set ($uixPoint = 'org.phenotips.patientSheet.section.none')\n      #set ($uixName = "org.phenotips.widget.$!{request.name.trim().toLowerCase().replaceAll(' +', '-')}")\n      #set ($uixFieldPrefix = "${uixClassName}_0_")\n      $response.sendRedirect($xwiki.getURL($targetDocument, 'edit', "editor=inline&amp;template=$escapetool.url($!{request.classTemplate})&amp;title=$!escapetool.url($request.name)&amp;parent=$!escapetool.url($request.parent)&amp;${uixFieldPrefix}name=$!escapetool.url(${uixName})&amp;${uixFieldPrefix}extensionPointId=${uixPoint}"))\n      #break\n    #end\n  #end\n#end\n\n\n#if ("$!errorMessage" != '')\n{{error}}$errorMessage{{/error}}\n\n#end\n{{html clean=false}}\n&lt;form class="xformInline" action="$doc.getURL($xcontext.action, $request.queryString)" method="post"&gt;&lt;div&gt;\n  &lt;input type="hidden" name="form_token" value="$!{services.csrf.getToken()}" /&gt;\n  &lt;input type="hidden" name="doCreate" value="1" /&gt;\n  &lt;input type="hidden" name="classTemplate" value="$uixTemplate" /&gt;\n  &lt;input type="hidden" name="space" value="$xwiki.getDocument(${uixTemplate}).space" /&gt;\n  &lt;input type="hidden" name="parent" value="${xwiki.getDocument($uixTemplate).space}.WebHome" /&gt;\n  &lt;label for="extension-name"&gt;$services.localization.render('phenotips.UIXDirectory.newExtension.label')&lt;/label&gt;&lt;input type="text" name="name" id="extension-name" placeholder="$services.localization.render('phenotips.UIXDirectory.newExtension.placeholder')"/&gt;&lt;input class="button" type="submit" value="$services.localization.render('phenotips.UIXDirectory.newExtension.create')"/&gt;\n&lt;/div&gt;&lt;/form&gt;\n{{/html}}\n\n#foreach ($o in $orders.keySet())\n  #if ($o == $order)\n|= $services.localization.render('phenotips.UIXDirectory.sortedBy', ["**$orders.get($o)**"])  ##\n  #else\n|= $services.localization.render('phenotips.UIXDirectory.sortBy', ["[[$orders.get($o)&gt;&gt;$doc.fullName||queryString='$!{request.queryString.replaceAll('[&amp;]?order=[^&amp;]*', '')}&amp;order=${o}']]"]) ##\n  #{end}#if (!$foreach.hasNext())\n|=\n#end\n#end\n#foreach ($uixDatum in $uixSortedData)\n| [[$uixDatum.get('doc.fullName')]] | $uixDatum.get('doc.space') | $uixDatum.extensionId | $uixDatum.extensionPointId | (% class="tools" %)(((##\n  [[{{icon name="pencil" title="$services.localization.render('phenotips.UIXDirectory.options.edit')"/}}&gt;&gt;path:$xwiki.getDocument($uixDatum.get('doc.fullName')).getURL('edit', "editor=object&amp;object=${uixDatum.obj.number}&amp;classname=${uixClassName}")]] ##\n  [[{{icon name="history" title="$services.localization.render('phenotips.UIXDirectory.options.history')"/}}&gt;&gt;path:$xwiki.getDocument($uixDatum.get('doc.fullName')).getURL('view', "viewer=history")]] ##\n  [[{{icon name="copy" title="$services.localization.render('phenotips.UIXDirectory.options.copy')"/}}&gt;&gt;path:$xwiki.getDocument($uixDatum.get('doc.fullName')).getURL('view', "xpage=copy")]] ##\n  [[{{icon name="file" title="$services.localization.render('phenotips.UIXDirectory.options.rename')"/}}&gt;&gt;path:$xwiki.getDocument($uixDatum.get('doc.fullName')).getURL('view', "xpage=rename")]] ##\n  [[{{icon name="download" title="$services.localization.render('phenotips.UIXDirectory.options.download')"/}}&gt;&gt;path:$xwiki.getDocument($uixDatum.get('doc.fullName')).getURL('export', "format=xar&amp;pages=${uixDatum.get('doc.fullName')}&amp;name=${uixDatum.get('doc.fullName')}")]] ##\n  [[{{icon name="times" title="$services.localization.render('phenotips.UIXDirectory.options.delete')"/}}&gt;&gt;path:$xwiki.getDocument($uixDatum.get('doc.fullName')).getURL('delete')]] ##\n)))\\\\\n#end\n#end## Has Admin\n{{/velocity}}\n</content></xwikidoc>
