tentType("text/xml")\n    &lt;?xml version="1.0" encoding="UTF-8"?&gt;\n    &lt;results type="3"&gt;\n    #foreach($result in $finalResults)\n      &lt;rs id="$foreach.count" info=""&gt;$escapetool.xml($result)&lt;/rs&gt;\n    #end\n    &lt;/results&gt;\n  #else\n    $response.setContentType("application/json")\n    {\n      "returnedrows": $finalResults.size(),\n      "rows": [\n      #foreach($result in $finalResults)\n        #if ($foreach.count &gt; 1)\n          ,\n        #end\n        { "index": "$foreach.count", "ethnicity": "$escapetool.json($result)" }\n      #end\n      ]\n    }\n  #end\n#end\n{{/velocity}}\n</content></xwikidoc>
