ument-title {\n  margin-bottom: 1em;\n}\n#change-context {\n  float: right;\n  padding-top: 15px;\n}\n/* IE6 is very sick... */\n#change-context div {\n  display: inline;\n}\n#goto-select optgroup {\n  margin: 6px;\n}\n\n/*******************************************************/\n\n#admin-page-content {\n  margin-left: 15em;\n}\n\n.admin-category {\n  list-style: none outside none;\n  margin: 0 !important;\n  float: left;\n}\n\n.admin-category li {\n  clear: left;\n  color: $theme.textSecondaryColor;\n  margin: 0 1.5em 2em 0;\n  max-width: 400px;\n  overflow: hidden;\n}\n\n.admin-category strong {\n  font-size: 1.44em;\n  line-height: 2em;\n}\n\n.admin-category img {\n  float: left;\n  margin: 0 1em 0 0;\n}\n\n.admin-category .description {\n  font-size: .9em;\n  display: block;\n}\n\n.admin-menu .group, .admin-menu .group:hover  {\n  background-position: 7px 50%, top center;\n}\n\n#set ($phenotipsIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/xwiki/favicon16.png')${escapetool.S})")\n.admin-menu .group.phenotipsIcon {\n  background-image: ${phenotipsIcon};\n  #css3_backgroundIconAndLinearGradient($phenotipsIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.phenotipsIcon:hover , .admin-menu .current.phenotipsIcon {\n  #css3_backgroundIconAndLinearGradient($phenotipsIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($configurationIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/silk/wrench.png')${escapetool.S})")\n.admin-menu .group.configurationIcon {\n  background-image: $configurationIcon;\n  #css3_backgroundIconAndLinearGradient($configurationIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.configurationIcon:hover , .admin-menu .current.configurationIcon {\n  #css3_backgroundIconAndLinearGradient($configurationIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($lfIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/silk/layout_content.png')${escapetool.S})")\n.admin-menu .group.lfIcon {\n  background-image: $lfIcon;\n  #css3_backgroundIconAndLinearGradient($lfIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.lfIcon:hover , .admin-menu .current.lfIcon {\n  #css3_backgroundIconAndLinearGradient($lfIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($usersgroupsIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/silk/group.png')${escapetool.S})")\n.admin-menu .group.usersgroupsIcon {\n  background-image: $usersgroupsIcon;\n  #css3_backgroundIconAndLinearGradient($usersgroupsIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.usersgroupsIcon:hover , .admin-menu .current.usersgroupsIcon {\n  #css3_backgroundIconAndLinearGradient($usersgroupsIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($contentIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/silk/folder_page.png')${escapetool.S})")\n.admin-menu .group.contentIcon {\n  background-image: $contentIcon;\n  #css3_backgroundIconAndLinearGradient($contentIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.contentIcon:hover , .admin-menu .current.contentIcon {\n  #css3_backgroundIconAndLinearGradient($contentIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($extensionmanagerIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/xwiki/plugin_wrench.png')${escapetool.S})")\n.admin-menu .group.extensionmanagerIcon {\n  background-image: $extensionmanagerIcon;\n  #css3_backgroundIconAndLinearGradient($extensionmanagerIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.extensionmanagerIcon:hover , .admin-menu .current.extensionmanagerIcon {\n  #css3_backgroundIconAndLinearGradient($extensionmanagerIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($applicationsIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/silk/plugin.png')${escapetool.S})")\n.admin-menu .group.applicationsIcon {\n  background-image: $applicationsIcon;\n  #css3_backgroundIconAndLinearGradient($applicationsIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.applicationsIcon:hover , .admin-menu .current.applicationsIcon {\n  #css3_backgroundIconAndLinearGradient($applicationsIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n\n#set ($readOnlyIcon = "url(${escapetool.S}$xwiki.getSkinFile('icons/silk/error.png')${escapetool.S})")\n.admin-menu .group.readOnly {\n  background-image: $readOnlyIcon;\n  #css3_backgroundIconAndLinearGradient($readOnlyIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuContentGradientColor, 'position': '0%'},\n      {'color': $theme.menuContentBackgroundColor, 'position': '100%'}\n    ]\n  })\n}\n.admin-menu .group.readOnly:hover , .admin-menu .current.readOnly {\n  #css3_backgroundIconAndLinearGradient($readOnlyIcon, {\n     'to': 'bottom',\n     'colors': [\n      {'color': $theme.menuGradientColor, 'position': '0%'},\n      {'color': $theme.menuBackgroundColor, 'position': '50%'}\n    ]\n  })\n}\n.admin-menu .group.readOnly, .admin-menu .group.readOnly:hover , .admin-menu .current.readOnly  {\n  background-position: 5px 50%, top center;\n}\n\n/* Override general table styles. */\n/* TODO: Move to livetable.css */\n\n#userstable td, #groupstable td, #usersandgroupstable td, #alldocstable td {\n  border-color: transparent;\n}\n\n#userstable, #groupstable, #usersandgroupstable, #alldocstable {\n  border-color: transparent;\n}\n\n#usersandgroupstable-filters #name {\n    width: 65%;\n}\n\n.rights-settings dt {\n  /* The labels for the general rights settings are long and thus look bad when displayed with bold text. */\n  font-weight: normal;\n}</code>\n</property>\n<property>\n<name>Administration application stylesheet</name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<content>{{include reference="XWiki.ConfigurableClassMacros" /}}\n\n{{velocity output="false"}}\n#if ($request.xaction == 'switchContext')\n  $response.sendRedirect($request.target)\n  #stop\n#end\n\n#set ($adminAction = 'admin')\n#set ($crtCategoryId = "$!{request.category}")\n#if ($crtCategoryId != '')\n  #set ($crtCategoryId = $mathtool.toInteger($crtCategoryId))\n#end\n#set ($crtSectionId = "$!{request.section}")\n\n##\n## Admin menu map\n##\n#set($adminMenu = [\n  {\n    'id' : 'configuration',\n    'priority' : 100,\n    'children': [\n       {'id' : 'Editing', 'advanced' : true, 'order': 100},\n       {'id' : 'Localization', 'advanced' : true, 'order': 200},\n       {'id' : 'XWiki.OfficeImporterAdmin', 'advanced' : true, 'order': 300}\n    ]\n  },\n  {\n    'id' : 'lf',\n    'priority' : 200,\n    'children': [\n       {'id' : 'Presentation', 'perSpace' : true, 'order': 100},\n       {'id' : 'Elements', 'perSpace' : true, 'advanced' : true, 'order': 200},\n       {'id' : 'Panels.PanelWizard', 'perSpace' : true, 'advanced' : true, 'order': 300}\n    ]\n  },\n  {\n    'id' : 'usersgroups',\n    'priority' : 300,\n    'children': [\n       {'id' : 'Users', 'order': 100},\n       {'id' : 'Groups', 'order': 200},\n       {'id' : 'Rights', 'perSpace' : true, 'advanced' : true, 'order': 300},\n       {'id' : 'Registration', 'advanced' : true, 'order': 400},\n       {'id' : 'UserProfile', 'advanced' : true, 'order': 500}\n    ]\n  },\n  {\n    'id' : 'content',\n    'priority' : 400,\n    'advanced' : true,\n    'children': [\n       {'id' : 'Import', 'action' : 'import', 'order': 100},\n       {'id' : 'Export', 'action' : 'export', 'order': 200},\n       {'id' : 'Templates', 'order': 300}\n    ]\n  },\n  {\n    'id' : 'extensionmanager',\n    'priority' : 500,\n    'children': [\n       {'id' : 'XWiki.AddExtensions', 'order': 100},\n       {'id' : 'XWiki.InstalledExtensions', 'order': 200},\n       {'id' : 'XWiki.CoreExtensions', 'advanced' : true, 'order': 300},\n       {'id' : 'XWiki.ExtensionUpdater', 'order': 400},\n       {'id' : 'XWiki.ExtensionHistory', 'advanced' : true, 'order': 500}\n    ]\n  },\n  {\n    'id' : 'applications',\n    'priority' : 1000,\n    'advanced' : true,\n    'children' : []\n  }\n])\n\n#**\n * Returns whether or not the requested section exists\n *\n * Example of use:\n * #if("#admin_hasSection('sectionId')" != '')\n *   OK\n * #end\n *#\n#macro (admin_hasSection $sectionId)\n  #foreach($category in $adminMenu)\n    #foreach($section in $category.children)\n      #if($section.id == $sectionId)\n        OK\n      #end\n    #end\n  #end\n#end\n\n##\n## Fill in the list of custom applications to configure\n##\n#findCustomSectionsToConfigure($adminMenu)\n\n##\n## Filter only the sections that are valid in a space, when administering a space\n##\n#if ($editor == 'spaceadmin')\n  #set ($categoriesToRemove = [])\n  #foreach ($category in $adminMenu)\n    #set ($sectionsToRemove = [])\n    #foreach ($section in $category.children)\n      #if (!$section.perSpace)\n        #set ($discard = $sectionsToRemove.add($section))\n      #end\n    #end\n    #set ($discard = $category.children.removeAll($sectionsToRemove))\n    #if ($category.children.size() == 0)\n      #set ($discard = $categoriesToRemove.add($category))\n    #end\n  #end\n  #set ($discard = $adminMenu.removeAll($categoriesToRemove))\n#end\n##\n## For simple users, filter only the sections that are not marked as 'advanced' confoguration\n##\n#if (!$isAdvancedUser)\n  #set ($categoriesToRemove = [])\n  #foreach ($category in $adminMenu)\n    #set ($sectionsToRemove = [])\n    #foreach ($section in $category.children)\n      #if ($section.advanced)\n        #set ($discard = $sectionsToRemove.add($section))\n      #end\n    #end\n    #set ($discard = $category.children.removeAll($sectionsToRemove))\n    #if ($category.children.size() == 0 || $category.advanced)\n      #set ($discard = $categoriesToRemove.add($category))\n    #end\n  #end\n  #set ($discard = $adminMenu.removeAll($categoriesToRemove))\n#end\n#if ("$!crtCategoryId" != '' &amp;&amp; $crtCategoryId &gt;= $adminMenu.size())\n  #set ($crtCategoryId = '')\n#end\n\n#if ("$!crtSectionId" != '')\n  #if("#admin_hasSection($crtSectionId)" != '')\n    #set ($crtItemId = $crtSectionId)\n  #else\n    #set($crtSectionId = $NULL)\n  #end\n#elseif ("$!crtCategoryId" != '')\n  #set ($crtItemId = $adminMenu.get($crtCategoryId).id)\n#end\n#set ($crtSection = $NULL)\n#set ($crtCategory = $NULL)\n\n\n##\n## Prepare the Admin menu map for processing\n##\n#set ($filteredAdminMenu = [])\n#foreach ($category in $adminMenu)\n  ## "Standard" URLs and icons for categories\n  #set ($category.url = $xwiki.getURL($currentDoc, $adminAction, "category=${mathtool.sub($velocityCount, 1)}"))\n  #if ($xwiki.getDocument('XWiki.AdminSheet').getAttachment("${category.id}.png"))\n    #set ($category.iconReference = "XWiki.AdminSheet@${category.id}.png")\n  #else\n    #set ($category.iconReference = "XWiki.ConfigurableClass@DefaultAdminSectionIcon.png")\n  #end\n  #set ($category.description = $services.localization.render("admin.${category.id}.description").trim())\n  #set ($category.cssClass = "${category.id}Icon")\n  #set ($category.name = $services.localization.render("admin.${category.id}").trim())\n  #if ("$!{crtCategoryId}" != '' &amp;&amp; $velocityCount == $mathtool.add($crtCategoryId, 1))\n    #set ($crtCategory = $category)\n  #end\n  ##\n  ## Process each admin section\n  #set ($filteredCategoryChildren = [])\n  #foreach ($section in $category.children)\n    #if ($xwiki.exists($section.id) || $xwiki.exists("XWiki.Admin${section.id}Sheet"))\n      #if ($crtSectionId == $section.id)\n        #set ($crtSection = $section)\n        #set ($crtCategory = $category)\n      #end\n      #set ($section.iconReference = '')\n      #if ($section.id.indexOf('.') &gt; 0)\n        #set ($sectionDoc = $xwiki.getDocument($section.id))\n        #set ($section.name = $sectionDoc.getDisplayTitle())\n        #if ($sectionDoc.getAttachment('icon.png'))\n          #set ($section.iconReference = "${sectionDoc}@icon.png")\n        #else\n          #set ($section.iconReference = 'XWiki.ConfigurableClass@DefaultAdminSectionIcon.png')\n        #end\n      #else\n        #set ($sectionDoc = $xwiki.getDocument('XWiki.AdminSheet'))\n        #set ($section.name = $services.localization.render("admin.${section.id.toLowerCase()}"))\n        #set ($iconName = "${section.id.toLowerCase()}.png")\n        #if ($sectionDoc.getAttachment($iconName))\n          #set ($section.iconReference = "${sectionDoc}@${iconName}")\n        #else\n          #set ($section.iconReference = 'XWiki.ConfigurableClass@DefaultAdminSectionIcon.png')\n        #end\n      #end\n      #set ($query = "editor=$escapetool.url(${editor})&amp;amp;section=$escapetool.url(${section.id})")\n      #if ($editor != 'globaladmin')\n        #set ($query = $query + "&amp;amp;space=$escapetool.url(${currentSpace})")\n      #end\n      #set ($action = "$!{section.action}")\n      #if ($action == '')\n        #set ($action = $adminAction)\n      #end\n      #set ($section.url = $xwiki.getURL($currentDoc, $action, $query))\n      #set ($key = "admin.${section.id.toLowerCase()}.description")\n      #if ($services.localization.get($key))\n        #set ($section.description = $services.localization.render($key))\n      #end\n      #set ($discard = $filteredCategoryChildren.add($section))\n    #elseif ($section.configurable)\n      #if ($section.readOnly)\n        #set ($section.cssClass = 'readOnly')\n      #end\n      #if ($crtSectionId == $section.id)\n        #set ($crtSection = $section)\n        #set ($crtCategory = $category)\n      #end\n      #set ($discard = $filteredCategoryChildren.add($section))\n    #end\n  #end\n  #set ($category.children = $filteredCategoryChildren)\n  #if ($filteredCategoryChildren.size() &gt; 0)\n    #set ($discard = $filteredAdminMenu.add($category))\n  #end\n#end\n#set ($adminMenu = $filteredAdminMenu)\n\n#**\n * Displays the sections from an administration category\n *\n * Expected format:\n * sections = vector of items\n * item = map with the following fields:\n *        'id'       : mandatory\n *        'name'     : the text displayed for the corresponding menu item;\n *                     optional, defaults to\n *                     $services.localization.render("$!{translationPrefix}${item.id}")\n *        'description' : the description displayed for the corresponding section;\n *                     optional\n *        'link'     : the "action" of the menu item; mandatory\n *        'cssClass' : a specific css class for the menu item for custom\n *                     styling; optional, defaults to ''\n *\n * @param $sections the sections list, in the format described above\n * @param $translationPrefix the translation prefix added to the id of each\n *        item, in order to generate the name and description; ignored when\n *        name or description are specified\n *#\n#macro(admin_displayCategory $sections $translationPrefix)\n(% class="admin-category" %)\n  #set ($sortedSections = [])\n  #sortCollectionOfMapsByField($sections, 'order', 9999, 'asc', $sortedSections)\n  #foreach ($section in $sortedSections)\n    * {{html wiki="true"}}&lt;a href="$section.url"&gt;[[image:${section.iconReference}]] **${section.name}**&lt;/a&gt;{{/html}} (% class="description" %)$!{section.description}\n  #end\n#end\n\n\n#**\n * Displays the administration categories\n *\n * Expected format:\n * sections = vector of items\n * item = map with the following fields:\n *        'id'       : mandatory\n *        'name'     : the text displayed for the corresponding menu item;\n *                     optional, defaults to\n *                     $services.localization.render("$!{translationPrefix}${item.id}")\n *        'description' : the description displayed for the corresponding section;\n *                     optional\n *        'link'     : the "action" of the menu item; mandatory\n *        'cssClass' : a specific css class for the menu item for custom\n *                     styling; optional, defaults to ''\n *\n * @param $sections the sections list, in the format described above\n * @param $translationPrefix the translation prefix added to the id of each\n *        item, in order to generate the name and description; ignored when\n *        name or description are specified\n *#\n#macro(admin_displayCategories $adminMenu $translationPrefix)\n(% class="admin-category" %)\n  #foreach ($category in $adminMenu)\n    * [[[[image:${category.iconReference}]] **${category.name}**&gt;&gt;path:${category.url}]] (% class="description" %)$!{category.description}\n  #end\n#end\n\n#**\n * Displays the drop down allowing to choose a different space to administer.\n *#\n#macro (admin_spaceSwitch)\n{{html clean="false"}}\n  &lt;form id="change-context" class="xformInline" action="$!doc.getURL($xcontext.action)"&gt;\n    &lt;div&gt;\n      &lt;input type="hidden" name="xaction" value="switchContext" /&gt;\n      &lt;select id="goto-select" name="target"&gt;\n        #if ($xwiki.hasAccessLevel('admin', $xcontext.user, 'XWiki.XWikiPreferences'))\n          &lt;optgroup label="$services.localization.render('admin.gotoglobaladministration')"&gt;\n            &lt;option value="$xwiki.getURL('XWiki.XWikiPreferences', 'admin', "section=$escapetool.url($crtSectionId)")" #if("$!{editor}"=="globaladmin")selected="selected"#end&gt;$services.localization.render('admin.globaladministration')&lt;/option&gt;\n          &lt;/optgroup&gt;\n        #end\n        &lt;optgroup label="$services.localization.render('admin.gotospaceadministration')"&gt;\n        #foreach($spaceitem in $xwiki.spaces)\n          #set ($spacePreferencesDocument = $services.model.createDocumentReference('', $spaceitem, 'WebPreferences'))\n          #if ($xwiki.hasAccessLevel('admin', $xcontext.user, $services.model.serialize($spacePreferencesDocument, 'default')))\n            &lt;option value="$xwiki.getURL($spacePreferencesDocument, 'admin', "section=$escapetool.url($crtSectionId)")" #if("$!{currentSpace}" == ${spaceitem} &amp;&amp; "$!{editor}" != 'globaladmin')selected="selected"#end&gt;$escapetool.xml($spaceitem)&lt;/option&gt;\n          #end\n        #end\n        &lt;/optgroup&gt;\n      &lt;/select&gt;\n      &lt;span class="buttonwrapper"&gt;&lt;input type="submit" value="$escapetool.xml($services.localization.render('admin.switchContext'))" class="button" /&gt;&lt;/span&gt;\n    &lt;/div&gt;\n  &lt;/form&gt;\n{{/html}}\n#end\n{{/velocity}}\n\n{{velocity}}\n##**************************************************************************************************\n## Administration Sheet, used to display a common UI for some wiki features (presentation, users,\n## groups, rights etc.) at global / space level and also for several applications.\n##**************************************************************************************************\n#if($xcontext.action == 'view')\n  $response.sendRedirect($xwiki.getURL($doc.getFullName(), 'admin', $request.getQueryString()))##\n#else\n  $xwiki.jsx.use('XWiki.AdminSheet')##\n  ## Construct the SSX parameter map:\n  ## - One parameter for the color theme\n  ## - Each custom ConfigurableClass can provide a custom icon to display in categories headings and\n  ##   thus we need to pass them to the SSX of the AdminSheet.\n  #set ($parameterMap = {})\n  #if ($themeDoc)\n    #set ($discard = $parameterMap.put('colorTheme', $themeDocFullName))\n  #end\n  #foreach ($adminMenuCategory in $adminMenu)\n    #set ($customIcon = $adminMenuCategory.categoryIcon)\n    #if ("$!customIcon" != '')\n      #set ($discard = $parameterMap.put("${adminMenuCategory.id}Icon", $customIcon))\n    #end\n  #end\n  $xwiki.ssx.use('XWiki.AdminSheet', $parameterMap)##\n  #if ("$!crtSectionId" != '' &amp;&amp; $crtSectionId.indexOf('.') &gt; 0 &amp;&amp; $xwiki.exists($crtSectionId))\n    #set ($sectionName = $xwiki.getDocument($crtSectionId).getDisplayTitle())\n  #elseif ($crtSectionId != '' &amp;&amp; $services.localization.get("admin.${crtSectionId.toLowerCase()}"))\n    #set ($sectionName = $services.localization.render("admin.${crtSectionId.toLowerCase()}"))\n  #elseif ("$!crtSectionId" != '')\n    #set ($sectionName = $crtSectionId)\n  #elseif ($crtCategoryId != '')\n    #set ($sectionName = $services.localization.render("admin.${crtItemId}"))\n  #elseif ($editor == 'globaladmin')\n    #set ($sectionName = $services.localization.render('xe.admin.global'))\n  #else\n    #set ($sectionName = $currentSpace)\n  #end\n#admin_spaceSwitch()\n(% id="hierarchy" %)\n(((\n\n{{html}}\n#breadcrumb_start()\n  #if ($crtCategory)\n    #breadcrumb_line($xwiki.getURL($currentDoc, $adminAction), $services.localization.render('admin.main.title'))\n    ##&lt;li&gt;&lt;a href="${xwiki.getURL($currentDoc, $adminAction)}"&gt;$services.localization.render('admin.main.title')&lt;/a&gt;&lt;/li&gt;\n  #else\n    #breadcrumb_current_line($services.localization.render('admin.main.title'))\n    ##&lt;li class="active"&gt;$services.localization.render('admin.main.title')&lt;/li&gt;\n  #end\n  #if ($crtCategory)\n    #if ($crtSection)\n      #breadcrumb_line($crtCategory.url, $crtCategory.name)\n      ##&lt;li&gt;&lt;a href="$crtCategory.url"&gt;$crtCategory.name&lt;/a&gt;&lt;/li&gt;\n    #else\n      #breadcrumb_current_line($crtCategory.name)\n      ##&lt;li class="active"&gt;$crtCategory.name&lt;/li&gt;\n    #end\n    #if ($crtSection)\n      #breadcrumb_current_line($crtSection.name)\n      ##&lt;li class="active"&gt;$crtSection.name&lt;/li&gt;\n    #end\n  #end\n#breadcrumb_end()\n{{/html}}\n\n)))\n(% id="document-title" %)(((\n  = $services.localization.render('admin.section.title', [$sectionName]) =\n)))\n\n  #verticalNavigation($adminMenu {'translationPrefix' : 'admin.', 'crtItemId' : "$!crtItemId", 'cssClass' : 'admin-menu'})\n  ##-----------------------------------------\n  ## admin-page display\n  ##-----------------------------------------\n    #if(!$crtSection &amp;&amp; !$crtCategory)\n      #admin_displayCategories($adminMenu 'admin.')\n    #elseif (!$crtSection)\n      #admin_displayCategory($crtCategory.children 'admin.')\n    #else\n      (% id="admin-page-content" %)(((\n        ##------------------------------------------------------------------------------------------------------------\n        ## The Administration allows editing other pages from different applications inside the admin context (UI)\n        ##------------------------------------------------------------------------------------------------------------\n        #if("$!{request.editmode}" == 'inline' &amp;&amp; $xwiki.exists($section))\n          $xcontext.setDisplayMode('edit')##\n\n          {{html clean="false"}}{{include reference="XWiki.AdminInlineSheet" /}}{{/html}}\n        #else\n          #if($xwiki.exists("XWiki.Admin${section}Sheet"))\n            ## Custom XE administration section\n\n            {{include reference="XWiki.Admin${section}Sheet" /}}\n\n          #elseif($xwiki.exists($section))\n            {{html clean="false"}}#includeForm($section){{/html}}\n          #end\n        #end\n        #if ($crtSection.configurable)\n          {{include reference="XWiki.ConfigurableClass" /}}\n        #end\n      ))) ## admin-page-content\n    #end\n#end\n{{/velocity}}</content></xwikidoc>\n
483170161964232996	1	1	2017-05-12 15:43:38	Install extension [org.phenotips:phenotips-ui-1.2.6]	XWiki.Admin	f	<?xml version="1.0" encoding="UTF-8"?>\n<xwikidoc>\n<web>XWiki</web>\n<name>ConfigurableClass</name>\n<language></language>\n<defaultLanguage></defaultLanguage>\n<translation>0</translation>\n<parent>XWiki.WebHome</parent>\n<creator>XWiki.Admin</creator>\n<author>XWiki.Admin</author>\n<customClass></customClass>\n<contentAuthor>XWiki.Admin</contentAuthor>\n<creationDate>1401822120000</creationDate>\n<date>1494618218000</date>\n<contentUpdateDate>1494618218000</contentUpdateDate>\n<version>1.1</version>\n<title>$services.localization.render('xe.admin.configurable.title')</title>\n<defaultTemplate></defaultTemplate>\n<validationScript></validationScript>\n<comment>Install extension [org.phenotips:phenotips-ui-1.2.6]</comment>\n<minorEdit>false</minorEdit>\n<syntaxId>xwiki/2.0</syntaxId>\n<hidden>true</hidden><attachment>\n<filename>DefaultAdminSectionIcon.png</filename>\n<filesize>4198</filesize>\n<author>xwiki:XWiki.Admin</author>\n<date>1494618218000</date>\n<version>1.1</version>\n<comment></comment></attachment>\n<class>\n<name>XWiki.ConfigurableClass</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<advancedOnly>\n<customDisplay></customDisplay>\n<defaultValue></defaultValue>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType></displayType>\n<name>advancedOnly</name>\n<number>5</number>\n<prettyName>advancedOnly</prettyName>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</advancedOnly>\n<categoryPriority>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>categoryPriority</name>\n<number>2</number>\n<numberType>integer</numberType>\n<prettyName>categoryPriority</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.NumberClass</classType>\n</categoryPriority>\n<codeToExecute>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<editor>---</editor>\n<name>codeToExecute</name>\n<number>11</number>\n<picker>0</picker>\n<prettyName>codeToExecute</prettyName>\n<rows>5</rows>\n<size>40</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</codeToExecute>\n<configurationClass>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>configurationClass</name>\n<number>7</number>\n<picker>0</picker>\n<prettyName>configurationClass</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</configurationClass>\n<configureGlobally>\n<customDisplay></customDisplay>\n<defaultValue></defaultValue>\n<disabled>0</disabled>\n<displayFormType>checkbox</displayFormType>\n<displayType></displayType>\n<name>configureGlobally</name>\n<number>8</number>\n<prettyName>configureGlobally</prettyName>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</configureGlobally>\n<displayInCategory>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>displayInCategory</name>\n<number>1</number>\n<picker>0</picker>\n<prettyName>displayInCategory</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</displayInCategory>\n<displayInSection>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>displayInSection</name>\n<number>3</number>\n<picker>0</picker>\n<prettyName>displayInSection</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</displayInSection>\n<heading>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>heading</name>\n<number>6</number>\n<picker>0</picker>\n<prettyName>heading</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</heading>\n<iconAttachment>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>iconAttachment</name>\n<number>12</number>\n<picker>0</picker>\n<prettyName>iconAttachment</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</iconAttachment>\n<linkPrefix>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>linkPrefix</name>\n<number>9</number>\n<picker>0</picker>\n<prettyName>linkPrefix</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</linkPrefix>\n<propertiesToShow>\n<cache>0</cache>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<displayType>input</displayType>\n<multiSelect>1</multiSelect>\n<name>propertiesToShow</name>\n<number>10</number>\n<picker>0</picker>\n<prettyName>propertiesToShow</prettyName>\n<relationalStorage>1</relationalStorage>\n<separator> </separator>\n<separators> ,|</separators>\n<size>20</size>\n<sort>none</sort>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<values></values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</propertiesToShow>\n<sectionPriority>\n<customDisplay></customDisplay>\n<disabled>0</disabled>\n<name>sectionPriority</name>\n<number>4</number>\n<numberType>integer</numberType>\n<prettyName>sectionPriority</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<validationMessage></validationMessage>\n<validationRegExp></validationRegExp>\n<classType>com.xpn.xwiki.objects.classes.NumberClass</classType>\n</sectionPriority>\n</class>\n<object>\n<class>\n<name>XWiki.JavaScriptExtension</name>\n<customClass></customClass>\n<customMapping></customMapping>\n<defaultViewSheet></defaultViewSheet>\n<defaultEditSheet></defaultEditSheet>\n<defaultWeb></defaultWeb>\n<nameField></nameField>\n<validationScript></validationScript>\n<cache>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>cache</name>\n<number>5</number>\n<prettyName>Caching policy</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>long|short|default|forbid</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</cache>\n<code>\n<disabled>0</disabled>\n<name>code</name>\n<number>2</number>\n<prettyName>Code</prettyName>\n<rows>20</rows>\n<size>50</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.TextAreaClass</classType>\n</code>\n<name>\n<disabled>0</disabled>\n<name>name</name>\n<number>1</number>\n<prettyName>Name</prettyName>\n<size>30</size>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.StringClass</classType>\n</name>\n<parse>\n<disabled>0</disabled>\n<displayFormType>select</displayFormType>\n<displayType>yesno</displayType>\n<name>parse</name>\n<number>4</number>\n<prettyName>Parse content</prettyName>\n<unmodifiable>0</unmodifiable>\n<classType>com.xpn.xwiki.objects.classes.BooleanClass</classType>\n</parse>\n<use>\n<cache>0</cache>\n<disabled>0</disabled>\n<displayType>select</displayType>\n<multiSelect>0</multiSelect>\n<name>use</name>\n<number>3</number>\n<prettyName>Use this extension</prettyName>\n<relationalStorage>0</relationalStorage>\n<separator> </separator>\n<separators>|, </separators>\n<size>1</size>\n<unmodifiable>0</unmodifiable>\n<values>currentPage|onDemand|always</values>\n<classType>com.xpn.xwiki.objects.classes.StaticListClass</classType>\n</use>\n</class>\n<name>XWiki.ConfigurableClass</name>\n<number>0</number>\n<className>XWiki.JavaScriptExtension</className>\n<guid>71fc6ffa-92cb-48f1-9d80-a845d1807b10</guid>\n<property>\n<cache>long</cache>\n</property>\n<property>\n<code>document.observe('xwiki:dom:loaded', function() {\n  // Hide headers unless they have error messages under them.\n  var elementsInPage = $('admin-page-content').childNodes;\n  var errorShown = false;\n  for (var i = elementsInPage.length - 1; i &gt; -1; i--) {\n    var e = elementsInPage[i];\n    if (e.tagName != undefined &amp;&amp; e.tagName.toLowerCase() == 'div' &amp;&amp; e.getAttribute('class') != undefined &amp;&amp; e.getAttribute('class').indexOf('errormessage') != -1)\n    {\n      errorShown = true;\n    } else if (!errorShown\n               &amp;&amp; e.tagName != undefined\n               &amp;&amp; e.tagName.toLowerCase() == 'h1'\n               &amp;&amp; e.getAttribute('id') != undefined\n               &amp;&amp; e.getAttribute('id').toLowerCase().indexOf('hcustomize') == 0)\n    {\n      e.parentNode.removeChild(e);\n      errorShown = false;\n    }\n  }\n\n  // Hide individual submit buttons.\n  var forms = $('admin-page-content').select('form');\n  var inputs = $('admin-page-content').select('input');\n  for (var i = 0; i &lt; inputs.length; i++) {\n    if (inputs[i].getAttribute('type') != undefined &amp;&amp; inputs[i].getAttribute('type').toLowerCase() == 'submit') {\n      var bottombuttons = inputs[i].up('.bottombuttons');\n      bottombuttons &amp;&amp; bottombuttons.remove();\n    }\n  }\n\n  // Add a submit button for saving all sections at once.\n  var button = new Element('input', {'type':'submit', 'class':'button', 'value':'$services.localization.render("admin.save")', 'name':'formactionsac'});\n  var wrapper = new Element('span', {'class':'buttonwrapper'});\n  var adminButtons = new Element('p', {'class':'admin-buttons'});\n  var bottomButtons = new Element('div', {'class':'bottombuttons'});\n  $('admin-page-content').appendChild(bottomButtons);\n  bottomButtons.appendChild(adminButtons);\n  adminButtons.appendChild(wrapper);\n  wrapper.appendChild(button);\n\n  Event.observe(button, 'click', function() {\n    var forms = $('admin-page-content').getElementsByTagName('form');\n    for (var i = 0; i &lt; forms.length; i++) {\n      Event.fire(document, 'xwiki:actions:save', {'form':forms[i].id, 'continue':true});\n    }\n  });\n});</code>\n</property>\n<property>\n<name></name>\n</property>\n<property>\n<parse>1</parse>\n</property>\n<property>\n<use>onDemand</use>\n</property>\n</object>\n<content>{{include reference="XWiki.ConfigurableClassMacros" /}}\n\n{{velocity}}\n#*\n * This part takes the configuration from any documents containing XWiki.ConfigurableClass objects and creates a form\n * for each. To includeForm this document, you may specify:\n *\n * $section - String - The section which we are administrating eg: "Registration", "Users", or "Import".\n *                     If none is specified then it checks for a request parameter called "section" and uses that,\n *                     if no parameter, then this code assumes that it is part of the admin icons sheet and adds icons\n *                     for any section which is not in $sections, in that event, this code assumes it is being run\n *                     inside of a &lt;ul&gt; block.\n *\n * $sections - List&lt;String&gt; - If section is not specified, any sections on this list will not have icons made for them,\n *                            the assumption being that the icons are already there. If section is specified then this\n *                            is not taken into account and may safely be undefined.\n *\n * $currentDoc - String (document.fullName) - The administration document, users who don't have permission to edit\n *                                            it will not be able to include applications (possibly injecting\n *                                            arbitrary code.) if none specified then $doc.getFullName() is used.\n *\n * $globaladmin - boolean - If set true then we will assume we are administrationg the entire wiki.\n *                          If not set then we look for a request parameter called "editor" if that exists and equals\n *                          "globaladmin" then $globaladmin is true, if it doesn't exist then we check to see if\n *                          $currentDoc.getFullName() equals "XWiki.XWikiPreferences".\n *###\n##\n## Form submission depends on this.\n$xwiki.jsfx.use('js/xwiki/actionbuttons/actionButtons.js', true)\n##\n#if(!$section)\n  #set($section = $request.getParameter('section'))\n#end\n#if(!$currentDoc)\n  #set($currentDoc = $doc.getFullName())\n#end\n## Get value of $globaladmin if not specified.\n#if("$!globaladmin" == '')\n  #if($editor != 'globaladmin'\n      &amp;&amp; $request.getParameter('editor') != 'globaladmin'\n      &amp;&amp; $currentDoc != 'XWiki.XWikiPreferences')\n  ##\n    #set($globaladmin = false)\n  #else\n    #set($globaladmin = true)\n  #end\n#end\n#set($currentSpace = $xwiki.getDocument($currentDoc).getSpace())\n##\n## This application should not run with programming rights because it evaluates code which may not be trustworthy.\n## Removing the next line will open a security hole.\n$doc.dropPermissions()##\n##\n##------------------------------------------------------------------------------------------------------------\n## If $section exists then we are viewing the admin page for a particular section.\n## eg: 'Registration', 'Presentation', 'Import' etc.\n##------------------------------------------------------------------------------------------------------------\n##\n#if($section &amp;&amp; $section != '')\n  ##\n  ## This is for keeping track of whether we have shown the heading yet or not.\n  ## If the heading doesn't need to be shown, but an error occurs in processing, then we show the heading\n  ## so that the user knows what the error relates to.\n  #set($headingShowing = false)\n  ##\n  ## Searches the database for names of apps to be configured\n  #set($outputList = [])\n  #findNamesOfAppsToConfigure($section, $globaladmin, $xwiki.getDocument($currentDoc).getSpace(), $outputList)\n  ##\n  #foreach($appName in $outputList)\n    ##\n    ## Make sure the current user has permission to edit the configurable application.\n    #set($userHasAccessToDocument = $xcontext.hasAccessLevel('edit', $appName))\n    ##\n    ## If the document was not last saved by a user with edit privilege on this page\n    ## then we can't safely display the page but we should warn the viewer.\n    #if($userHasAccessToDocument)\n      ## Get the configurable application\n      #set($app = $xwiki.getDocument($appName))\n      ##\n      #set($documentSavedByAuthorizedUser = false)\n      #checkDocumentSavedByAuthorizedUser($app, $currentDoc, $documentSavedByAuthorizedUser)\n    #end\n    ##\n    ## There is no need to display a heading unless:\n    ## 1. There was already a section before this document.\n    ## 2. This is not the first document in this section.\n    ##\n    ## If we are displaying the heading and there is an error to be shown Javascript will not strip the heading.\n    #if(!$appName.equals($outputList.get(0)) || $sections.contains($section))\n      ## Create a document heading.\n      #showHeading($appName, $headingShowing)\n    #end\n    ##\n    #if(!$userHasAccessToDocument)\n      #showHeading($appName, $headingShowing)\n\n      {{error}}{{translation key="xe.admin.configurable.noPermissionThisApplication"/}}{{/error}}\n\n    #elseif(!$documentSavedByAuthorizedUser)\n      #showHeading($appName, $headingShowing)\n\n      {{error}}{{translation key="xe.admin.configurable.applicationAuthorNoAdmin" parameters="$app.Author"/}}{{/error}}\n\n    ##\n    ##------------------------------------------------------------------------------------------------------------\n    ## If the document is locked and not by the current user and forceEdit is not set true,\n    #elseif($app.getLocked() &amp;&amp; $app.getLockingUser() != $xcontext.getUser() &amp;&amp; !$request.getParameter('forceEdit'))\n      #set($requestURL = "$request.getRequestURL()")\n      #if($requestURL.indexOf('?') == -1)\n        #set($requestURL = "${requestURL}?")\n      #end\n      #showHeading($appName, $headingShowing)\n\n      {{error}}{{translation key="doclockedby"/}} $app.getLockingUser() [[{{translation key="forcelock"/}}&gt;&gt;${requestURL}&amp;forceEdit=1]]{{/error}}\n\n    #else\n      ## If the document is not already locked, attempt to acquire the lock.\n      #if(!$app.getLocked())\n\n        {{html wiki=true}}\n          &lt;noscript&gt;\n\n            {{warning}}{{translation key="xe.admin.configurable.cannotLockNoJavascript"/}}{{/warning}}\n\n          &lt;/noscript&gt;\n          &lt;script type="text/javascript"&gt;\n            document.observe("xwiki:dom:loaded", function() {\n              XWiki.DocumentLock &amp;&amp; new XWiki.DocumentLock('$escapetool.javascript($app.fullName)').lock();\n            });\n          &lt;/script&gt;\n        {{/html}}\n      #end\n      ##------------------------------------------------------------------------------------------------------------\n      ## Done Locking.\n      ##\n      ## Get all objects of the "ConfigurableClass" from this document.\n      #set($allConfigurableObjs = $app.getObjects($nameOfThisDocument))\n      ## Separate out the objects which are for this section.\n      #set($configurableObjs = [])\n      #foreach($configurableObj in $allConfigurableObjs)\n        #if($app.getValue('displayInSection', $configurableObj) == $section)\n          ## If this is space admin, then don't display global, if global don't display space.\n          #if($globaladmin == ($app.getValue('configureGlobally', $configurableObj) == 1))\n            #set($discard = $configurableObjs.add($configurableObj))\n          #end\n        #end\n      #end\n      #if($configurableObjs.size() == 0)\n        ## Internal error, not translated.\n        #showHeading($appName, $headingShowing)\n\n        {{error}}Internal error: All objects were filtered out for application: $appName.{{/error}}\n\n      #else\n        #set($formAction = $xwiki.getURL($app.getFullName(), 'save'))\n        #set($formId = "${section.toLowerCase()}_${app.getFullName()}")\n        #set($escapedAppName = $escapetool.xml($app.getFullName()))\n        #foreach($configurableObj in $configurableObjs)\n          ## Display the header if one exists.\n          #set($heading = $app.getValue('heading', $configurableObj))\n          #if($heading &amp;&amp; $heading != '')\n            == #evaluate($heading) ==\n          #end\n          ##\n          #set($codeToExecute = "$!app.getValue('codeToExecute', $configurableObj)")\n          #if($codeToExecute != '')\n            (%class="codeToExecute"%)(((##\n              #evaluate($codeToExecute)##\n            )))\n          #end\n          ##\n          ## If propertiesToShow is set, then we will only show the properties contained therein.\n          #set($propertiesToShow = $app.getValue('propertiesToShow', $configurableObj))\n          #if(!$propertiesToShow || $propertiesToShow.getClass().getName().indexOf('List') == -1)\n            #set($propertiesToShow = [])\n          #end\n          ##\n          ## If linkPrefix is set, then we will make each property label a link which starts with that prefix.\n          #set($linkPrefix = "$!app.getValue('linkPrefix', $configurableObj)")\n          ##\n          ## If the Configurable object specifies a configuration class, use it,\n          ## otherwise assume custom forms are used instead.\n          #set($configClassName = "$!app.getValue('configurationClass', $configurableObj)")\n          #if($configClassName != '')\n            #set($objClass = $xwiki.getDocument($configClassName).getxWikiClass())\n            #if(!$objClass || $objClass.getClass().getName().indexOf('.Class') == -1)\n              #showHeading($appName, $headingShowing)\n\n              {{error}}{{translation key="xe.admin.configurable.configurationClassNonexistant"/}}{{/error}}\n\n            #else\n              ## Use the first object from the document which is of the configuration class.\n              #set($obj = $app.getObject($objClass.getName()))\n              ##\n              #if(!$obj || $obj.getClass().getName().indexOf('.Object') == -1)\n                #showHeading($appName, $headingShowing)\n\n                {{error}}\n                  {{translation key="xe.admin.configurable.noObjectOfConfigurationClassFound" parameters="$objClass.getName(), $app.getFullName()"/}}\n                {{/error}}\n\n              #else\n                ##\n                ## Merge save buttons, remove headings from subsections, and make information links into popups.\n                ## This is not done if there is only a custom defined form.\n                $xwiki.jsx.use($nameOfThisDocument)##\n                ##\n                ## We don't begin the form until we have content for it so that a configurable can specify a\n                ## custom form in codeToExecute and if that configurable object is the first of it's kind in that\n                ## document, the custom form will not be put inside of our form.\n                #if(!$insideForm)\n                  ## We are opening a form and fieldset without closing it, thus we cannot clean this html.\n\n                  {{html clean=false}}\n                    &lt;form id="$formId" method="post" action="$formAction" class="xform half"&gt;\n                      &lt;fieldset&gt;\n                  {{/html}}\n                  #set($insideForm = true)\n                #end\n\n                {{html}}\n                  $formHtml.toString()\n                {{/html}}\n              #end## If object exists\n            #end## If class exists\n          #end## If class name is specified.\n        #end## Foreach configurable object found in this document\n        ## If a form was started then we end it.\n        #if($insideForm)\n\n          ## This is closing an open form which was opened above, we cannot clean this html.\n          {{html clean=false}}\n          ## We add in a redirect field to prevent the user from being carried away when they save\n          ## if they don't have javascript.\n          #set($thisURL = $request.getRequestURL())\n          #if($request.getQueryString() &amp;&amp; $request.getQueryString().length() &gt; 0)\n            #set($thisURL = "${thisURL}?$request.getQueryString()")\n          #end\n          &lt;input type="hidden" id="${escapedAppName}_redirect" name="$redirectParameter" value="$escapetool.xml($thisURL)" /&gt;\n          &lt;input type="hidden" name="form_token" value="$!{services.csrf.getToken()}" /&gt;\n          &lt;/fieldset&gt;\n          &lt;div class="bottombuttons"&gt;\n            &lt;p class="admin-buttons"&gt;\n              &lt;span class="buttonwrapper"&gt;\n                ## Text to display on the button. If there is a heading then this button should be labeled\n                ## that it is for saving this section. Otherwise it should be a generic "save" button.\n                #if($headingShowing)\n                  #set($buttonText = "$services.localization.render('admin.save') $escapedAppName")\n                #else\n                  #set($buttonText = "$services.localization.render('admin.save')")\n                #end\n                &lt;input class="button" type="submit" name="action_saveandcontinue" value="$buttonText" /&gt;\n              &lt;/span&gt;\n            &lt;/p&gt;\n          &lt;/div&gt; ## bottombuttons\n          &lt;/form&gt;\n          #set($insideForm = false)\n          {{/html}}\n        #end\n      #end## If there are configurable objects\n    #end## If document is not locked or forceEdit is enabled\n  #end## Foreach document name in names to configure\n\n  {{html}}\n  &lt;script type="text/javascript"&gt;\n  /* &lt;![CDATA[ */\n  ## Alt+Shift+S presses the first saveAndContinue button it finds, not what we want so we will disable edit shortcuts.\n  document.observe('xwiki:dom:loaded', function() {\n    XWiki.actionButtons.EditActions = Object.extend(XWiki.actionButtons.EditActions, {addShortcuts : function() { }});\n  });\n  //]]&gt;\n  &lt;/script&gt;\n  {{/html}}##\n  ##\n#else\n  ##\n  ##------------------------------------------------------------------------------------------------------------\n  ## If section is not set then we are viewing the main administration page.\n  ##------------------------------------------------------------------------------------------------------------\n  ##\n  ## If there is no list called sections then we set sections to an empty list.\n  #if(!$sections || $sections.getClass().getName().indexOf('List') == -1)\n    #set($sections = [])\n  #end\n  ##\n  ## We have to create a list of documents which the current user doesn't have permission to view.\n  ## So we can add an error message to the bottom of the page if there are any.\n  #set($appsUserCannotView = [])\n  ##\n  ## A list of sections (to be added) which the user is not allowed to edit, icons will be displayed with a message\n  #set($sectionsUserCannotEdit = [])\n  ## List of sections to be added, in order by creationDate of oldest contained application.\n  #set($sectionsToAdd = [])\n  ## Map of URL of icon to use by the name of the section to use that icon on.\n  #set($iconBySection = {})\n  ##\n  #set($outputList = [])\n  #findNamesOfAppsToConfigure("", $globaladmin, $currentSpace, $outputList)\n  ##\n  #foreach($appName in $outputList)\n    ##\n    ## Get the configurable application\n    #set($app = $xwiki.getDocument($appName))\n    ##\n    ## If getDocument returns null, then warn the user that they don't have view access to that application.\n    #if(!$app)\n      #set($discard = $appsUserCannotView.add($appName))\n    #end\n    ##\n    #set($configurableObjects = $app.getObjects($nameOfThisDocument))\n    #foreach($configurableObject in $configurableObjects)\n      #set($displayInSection = $app.getValue('displayInSection', $configurableObject))\n      ##\n      ## If there is no section for this configurable or if the section cannot be edited, then check if the\n      ## application can be edited by the current user, if so then we display the icon from the current app and\n      ## don't display any message to tell the user they can't edit that section.\n      #if(!$sections.contains($displayInSection) || $sectionsUserCannotEdit.contains($displayInSection))\n        ##\n        ## If there is no section for this configurable, then we will have to add one.\n        #if(!$sections.contains($displayInSection) &amp;&amp; !$sectionsToAdd.contains($displayInSection))\n          #set($discard = $sectionsToAdd.add($displayInSection))\n        #end\n        ##\n        ## If an attachment by the filename iconAttachment exists and is an image\n        #set($attachment = $app.getAttachment("$app.getValue('iconAttachment', $configurableObject)"))\n        #if($attachment &amp;&amp; $attachment.isImage())\n          ## Set the icon for this section as the attachment URL.\n          #set($discard = $iconBySection.put($displayInSection, $app.getAttachmentURL($attachment.getFilename())))\n        #end\n        ##\n        ## If the user doesn't have edit access to the application, we want to show a message on the icon\n        #if(!$xcontext.hasAccessLevel("edit", $app.getFullName()))\n          #if(!$sectionsUserCannotEdit.contains($displayInSection))\n            #set($discard = $sectionsUserCannotEdit.add($displayInSection))\n          #end\n        #elseif($sectionsUserCannotEdit.contains($displayInSection))\n          ## If the user didn't have access to the section before but does have access to _this_ app which is\n          ## configured in the section, then the section becomes accessible.\n          #set($discard = $sectionsUserCannotEdit.remove($displayInSection))\n        #end\n      #end## If section doesn't exist or user doesn't have access.\n    #end## Foreach configurable object in this app.\n  #end## Foreach application which is configurable.\n  ##\n  ## Now we go through sectionsToAdd and generate icons for them\n  #set($defaultIcon = $xwiki.getAttachmentURL($nameOfThisDocument, 'DefaultAdminSectionIcon.png'))\n  #if($globaladmin)\n    #set($queryString = "editor=globaladmin&amp;amp;section=")\n  #else\n    #set($queryString = "space=${currentSpace}&amp;amp;section=")\n    #if($request.getParameter('editor'))\n      #set($queryString = "editor=$escapetool.url($request.getParameter('editor'))&amp;amp;$queryString")\n    #end\n  #end\n\n  ## This is an html fragment and thus cannot be cleaned\n  {{html clean=false}}\n  #foreach($sectionToAdd in $sectionsToAdd)\n    #set($icon = $iconBySection.get($sectionToAdd))\n    #if(!$icon)\n      #set($icon = $defaultIcon)\n    #end\n    &lt;li class="$escapetool.xml($sectionToAdd).replaceAll(' ', '_')"&gt;\n      #set($hasAccess = !$sectionsUserCannotEdit.contains($sectionToAdd))\n      #if($hasAccess)\n        &lt;a href="$xwiki.getURL($currentDoc, $xcontext.getAction(), "$queryString$escapetool.url($sectionToAdd)")"&gt;\n      #else\n        &lt;a title="$services.localization.render('xe.admin.configurable.sectionIconNoAccessTooltip')"&gt;\n      #end\n      &lt;span&gt;\n      &lt;img src="$icon" alt="$escapetool.xml($sectionToAdd) icon"/&gt;\n      ## Try to translate the names of the sections, build the key by adding an "admin." in front. \n      ## Not the best way to translate, but very inline with the way the translations are done in XWiki.AdminSheet for individual administration page titles.\n      ## If there is no translation (translated message is equals to key), don't display the message key, but the section name instead.\n      #if($services.localization.get("admin.${sectionToAdd.toLowerCase()}")) \n        #set($sectionDisplayName = $services.localization.render("admin.${sectionToAdd.toLowerCase()}")) \n      #else\n        #set($sectionDisplayName = $sectionToAdd)\n      #end\n      $escapetool.xml($sectionDisplayName)\n      &lt;/span&gt;\n      #if(!$hasAccess)\n        &lt;br/&gt;&lt;span class="errormessage"&gt;$services.localization.render('xe.admin.configurable.sectionIconNoAccess')&lt;/span&gt;\n      #end\n      &lt;/a&gt;\n    &lt;/li&gt;\n  #end\n  {{/html}}\n\n  ## Finally we display an error message if there are any applications which we were unable to view.\n  #if($appsUserCannotView.size() &gt; 0)\n\n    {{error}}$services.localization.render('xe.admin.configurable.noViewAccessSomeApplications', [$appsUserCannotView]){{/error}}\n\n  #end\n#end## If we should be looking at the main administration page.\n{{/velocity}}</content></xwikidoc>\n
